QT_ISI(27,{"4706":["(Ibrahim bertanya, \"Apakah urusan kalian) maksudnya, kepentingan kalian (hai para utusan?\");",[["۞ قَالَ","Dia berkata"],["فَمَا","Kemudian apa"],["خَطْبُكُمْ","(adalah) misi kamu"],["أَيُّهَا","Wahai para rasul"],["ٱلْمُرْسَلُونَ","Wahai para rasul"]]],"4707":["(Mereka menjawab, \"Sesungguhnya kami diutus kepada kaum yang berdosa) kaum yang kafir, mereka adalah kaum Nabi Luth.",[["قَالُوٓا۟","Mereka berkata"],["إِنَّآ","Sesungguhnya kami"],["أُرْسِلْنَآ","[kami] telah dihantar"],["إِلَىٰ","kepada"],["قَوْمٍۢ","suatu kaum"],["مُّجْرِمِينَ","penjenayah"]]],"4708":["(Agar kami timpakan kepada mereka batu-batu dari tanah yang keras) yang dibakar oleh api.",[["لِنُرْسِلَ","Supaya kami turunkan"],["عَلَيْهِمْ","ke atas mereka"],["حِجَارَةًۭ","batu"],["مِّن","daripada"],["طِينٍۢ","tanah liat"]]],"4709":["(Yang ditandai) yang diberi tanda padanya nama orang-orang yang akan dilemparkan (di sisi Rabbmu) menjadi Zharaf dari lafal yang sebelumnya (untuk orang-orang yang melampaui batas\") karena mereka gemar melakukan homosex, dan kekafiran mereka.",[["مُّسَوَّمَةً","Ditanda"],["عِندَ","oleh Tuhanmu"],["رَبِّكَ","oleh Tuhanmu"],["لِلْمُسْرِفِينَ","bagi orang yang melampaui batas"]]],"4710":["(Lalu Kami keluarkan orang-orang yang berada di negeri itu) kampung-kampung Nabi Luth (yakni orang-orang yang beriman) karena orang-orang kafirnya akan dibinasakan.",[["فَأَخْرَجْنَا","Kemudian Kami keluarkan"],["مَن","(mereka) yang"],["كَانَ","adalah"],["فِيهَا","di dalamnya"],["مِنَ","daripada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"4711":["(Dan Kami tidak mendapati di negeri itu, kecuali sebuah rumah dari orang-orang yang berserah diri) mereka adalah Nabi Luth dan kedua orang putrinya, mereka dinamakan sebagai orang-orang yang beriman dan berserah diri, karena mereka adalah orang-orang yang beriman dengan sepenuh kalbu serta mengamalkan ketaatan dengan semua anggota tubuh mereka.",[["فَمَا","Tetapi tidak"],["وَجَدْنَا","Kami jumpa"],["فِيهَا","di dalamnya"],["غَيْرَ","selain daripada"],["بَيْتٍۢ","sebuah rumah"],["مِّنَ","daripada"],["ٱلْمُسْلِمِينَ","kaum muslimin"]]],"4712":["(Dan Kami tinggalkan pada negeri itu) sesudah semua orang-orang kafir dibinasakan (suatu tanda) yakni tanda yang menunjukkan bahwa mereka telah dibinasakan (bagi orang-orang yang takut kepada siksa yang pedih) hingga hal itu dijadikan sebagai peringatan buat mereka, supaya mereka tidak melakukan perbuatan yang sama.",[["وَتَرَكْنَا","Dan Kami pergi"],["فِيهَآ","di dalamnya"],["ءَايَةًۭ","sebuah Tanda"],["لِّلَّذِينَ","bagi mereka yang"],["يَخَافُونَ","bertakwa"],["ٱلْعَذَابَ","azab"],["ٱلْأَلِيمَ","yang menyakitkan"]]],"4713":["(Dan juga pada Musa) di-'athaf-kan kepada lafal Fiihaa. Maknanya, Dan Kami jadikan pada kisah Musa suatu tanda (ketika Kami mengutusnya kepada Firaun) (dengan membawa bukti yang nyata) yakni hujjah yang jelas dan terang.",[["وَفِى","Dan dalam"],["مُوسَىٰٓ","Musa"],["إِذْ","apabila"],["أَرْسَلْنَـٰهُ","Kami hantar dia"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["بِسُلْطَـٰنٍۢ","dengan kuasa"],["مُّبِينٍۢ","yang nyata"]]],"4714":["(Maka dia berpaling) yakni Firaun tidak mau beriman (bersama tentaranya) bersama dengan pasukannya; di sini bala tentara dinamakan Ar Rukn yang arti asalnya adalah pilar karena memang bala tentara itu adalah pilar atau penopang bagi pemimpinnya (dan berkata) kepada Nabi Musa, bahwa (dia adalah seorang tukang sihir atau seorang gila).",[["فَتَوَلَّىٰ","Tetapi dia berpaling"],["بِرُكْنِهِۦ","bersama penyokongnya"],["وَقَالَ","dan berkata"],["سَـٰحِرٌ","Seorang ahli silap mata"],["أَوْ","atau"],["مَجْنُونٌۭ","orang gila"]]],"4715":["(Maka Kami siksa dia dan bala tentaranya lalu Kami lemparkan mereka) Kami campakkan mereka (ke dalam laut) hingga tenggelamlah mereka (sedangkan dia) yakni Firaun (melakukan pekerjaan yang tercela) yaitu mendustakan rasul-rasul dan mengaku-ngaku menjadi Tuhan.",[["فَأَخَذْنَـٰهُ","Maka Kami ambil dia"],["وَجُنُودَهُۥ","dan tuan rumahnya"],["فَنَبَذْنَـٰهُمْ","dan melemparkannya"],["فِى","ke dalam"],["ٱلْيَمِّ","laut"],["وَهُوَ","sedangkan dia"],["مُلِيمٌۭ","(adalah) patut dipersalahkan"]]],"4716":["(Dan juga pada) kisah pembinasaan kaum (Ad) terdapat tanda yang dijadikan sebagai pelajaran (ketika Kami kirimkan kepada mereka angin yang membinasakan) yaitu angin yang sama sekali tidak membawa kebaikan, karena tidak membawa air hujan dan tidak dapat menyerbukkan pohon-pohon, angin ini dinamakan angin puting beliung.",[["وَفِى","Dan dalam"],["عَادٍ","Aad"],["إِذْ","apabila"],["أَرْسَلْنَا","Kami utus"],["عَلَيْهِمُ","terhadap mereka"],["ٱلرِّيحَ","angin"],["ٱلْعَقِيمَ","yang tandus"]]],"4717":["(Angin itu tidak membiarkan sesuatu pun) baik jiwa atau harta benda (yang dilandanya, melainkan dijadikannya seperti serbuk) yakni sebagai barang rongsokan yang tercabik-cabik.",[["مَا","Tidak"],["تَذَرُ","ia pergi"],["مِن","sebarang"],["شَىْءٍ","perkara"],["أَتَتْ","ia datang"],["عَلَيْهِ","atasnya"],["إِلَّا","tetapi"],["جَعَلَتْهُ","ia berjaya"],["كَٱلرَّمِيمِ","seperti runtuhan yang hancur"]]],"4718":["(Dan pada) kisah pembinasaan kaum (Tsamud) terdapat tanda yang dijadikan sebagai pelajaran (ketika dikatakan kepada mereka) sesudah mereka menyembelih unta, (\"Bersenang-senanglah kalian sampai suatu waktu\") yakni sampai habisnya ajal kalian, dan di dalam ayat lain disebutkan, \"Bersukarialah kamu sekalian di rumah kalian selama tiga, hari.\" (Q.S. Hud, 65)",[["وَفِى","Dan dalam"],["ثَمُودَ","kaum Thamud"],["إِذْ","apabila"],["قِيلَ","telah dikatakan"],["لَهُمْ","kepada mereka"],["تَمَتَّعُوا۟","Nikmati (sendiri)"],["حَتَّىٰ","bagi"],["حِينٍۢ","suatu masa"]]],"4719":["(Maka mereka berlaku angkuh) bersikap sombong (terhadap perintah Rabb mereka) yaitu mereka tidak mau mengerjakannya (lalu mereka disambar petir) yakni teriakan yang membinasakan mereka, hal ini terjadi setelah tiga hari sejak mereka menyembelih unta itu (sedangkan mereka melihatnya) karena azab itu terjadi di siang hari.",[["فَعَتَوْا۟","Tetapi mereka memberontak"],["عَنْ","terhadap"],["أَمْرِ","(the) Perintah"],["رَبِّهِمْ","(dari) Tuhan mereka"],["فَأَخَذَتْهُمُ","jadi merampas mereka"],["ٱلصَّـٰعِقَةُ","petir"],["وَهُمْ","sedangkan mereka"],["يَنظُرُونَ","sedang mencari"]]],"4720":["(Maka mereka sama sekali tidak dapat bangun) mereka tidak mampu bangkit sewaktu azab turun kepada mereka (dan tiadalah mereka orang-orang yang dapat mengalahkan) yang membinasakan mereka.",[["فَمَا","Kemudian tidak"],["ٱسْتَطَـٰعُوا۟","mereka dapat"],["مِن","[daripada]"],["قِيَامٍۢ","berdiri"],["وَمَا","dan bukan"],["كَانُوا۟","mereka boleh"],["مُنتَصِرِينَ","menolong diri mereka sendiri"]]],"4721":["(Dan kaum Nuh) kalau dibaca Qaumi Nuuh, dibaca Jar, berarti di-'athaf-kan kepada lafal Tsamuuda; yakni di dalam pembinasaan mereka dengan azab yang turun dari langit dan azab dari bumi terdapat pelajaran. Kalau dibaca Nashab yakni Qauma Nuuh artinya, kami telah membinasakan kaum Nuh (sebelum itu) sebelum dibinasakan orang-orang yang telah disebutkan tadi. (Sesungguhnya mereka adalah kaum yang fasik).",[["وَقَوْمَ","Dan (orang-orang) itu"],["نُوحٍۢ","(daripada) Nuh"],["مِّن","sebelum"],["قَبْلُ ۖ","sebelum"],["إِنَّهُمْ","sesungguhnya, mereka"],["كَانُوا۟","adalah"],["قَوْمًۭا","suatu kaum"],["فَـٰسِقِينَ","membangkang menderhaka"]]],"4722":["(Dan langit itu Kami bangun dengan kekuasaan Kami) dengan kekuatan Kami (dan sesungguhnya Kami benar-benar berkuasa) dikatakan Adar Rajulu Ya-idu Qawiyyu artinya lelaki itu menjadi kuat. Dikatakan Awsa'ar Rajulu, artinya ia menjadi orang yang memiliki pengaruh dan kekuatan.",[["وَٱلسَّمَآءَ","Dan syurga"],["بَنَيْنَـٰهَا","Kami membinanya"],["بِأَيْي۟دٍۢ","dengan kekuatan"],["وَإِنَّا","dan sesungguhnya Kami"],["لَمُوسِعُونَ","(adalah) pasti (ia) yang mengembang"]]],"4723":["(Dan bumi itu Kami hamparkan) Kami buat terhampar, menurut pandangan mata (maka sebaik-baik yang menghamparkan) adalah Kami.",[["وَٱلْأَرْضَ","Dan bumi"],["فَرَشْنَـٰهَا","Kami telah menyebarkannya"],["فَنِعْمَ","betapa cemerlangnya"],["ٱلْمَـٰهِدُونَ","(adalah) Penyebar"]]],"4724":["(Dan segala sesuatu) ber-ta'alluq kepada lafal Khalaqnaa (Kami ciptakan berpasang-pasangan) yakni dari dua jenis, yaitu jenis pria dan wanita; ada langit dan ada bumi; ada matahari dan ada bulan; ada dataran rendah dan ada dataran tinggi, ada musim panas dan ada musim dingin, ada rasa manis dan ada rasa masam, ada gelap dan ada terang (supaya kalian berfikir) asal kata Tadzakkaruuna adalah Tatadzakkaruuna, lalu salah satu huruf Ta-nya dibuang sehingga jadilah Tadzakkaruuna. Karena itu kalian mengetahui bahwa Pencipta pasangan-pasangan itu adalah Esa, lalu kalian menyembah-Nya.",[["وَمِن","Dan daripada"],["كُلِّ","setiap"],["شَىْءٍ","perkara"],["خَلَقْنَا","Kami telah mencipta"],["زَوْجَيْنِ","berpasangan"],["لَعَلَّكُمْ","supaya kamu"],["تَذَكَّرُونَ","ingat"]]],"4725":["(Maka segeralah kembali kepada Allah) larilah kalian kepada pahala-Nya dari siksaan-Nya, yaitu dengan jalan menaati-Nya dan tidak mendurhakai-Nya. (Sesungguhnya aku seorang pemberi peringatan yang nyata dari Allah untuk kalian) aku adalah seorang pemberi peringatan yang jelas lagi gamblang.",[["فَفِرُّوٓا۟","Jadi larilah"],["إِلَى","kepada"],["ٱللَّهِ ۖ","Allah"],["إِنِّى","sesungguhnya, aku"],["لَكُم","kepada kamu"],["مِّنْهُ","daripadaNya"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌۭ","yang nyata"]]],"4726":["(Dan Janganlah kalian mengadakan tuhan Yang lain di samping Allah. Sesunguhnya aku seorang pemberi peringatan yang nyata dari Allah untuk kalian) sebelum firman-Nya, \"Fafirruu\" diperkirakan ada lafal Qul Lahum artinya, \"Katakanlah kepada mereka.\"",[["وَلَا","Dan jangan"],["تَجْعَلُوا۟","buat"],["مَعَ","dengan"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","tuhan"],["ءَاخَرَ ۖ","yang lain"],["إِنِّى","Memang aku"],["لَكُم","kepada kamu"],["مِّنْهُ","daripadaNya"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌۭ","yang nyata"]]],"4727":["(Demikianlah tidak seorang rasul pun yang datang kepada orang-orang yang sebelum mereka, melainkan mereka mengatakan,) \"Dia (adalah seorang tukang sihir atau orang gila\") sebagaimana mereka mendustakanmu melalui perkataan mereka, bahwa sesungguhnya kami adalah seorang tukang sihir atau kamu adalah orang gila. Maka umat-umat terdahulu pun pernah mengatakan hal yang serupa sewaktu mereka mendustakan rasul-rasulnya.",[["كَذَٰلِكَ","Begitu juga"],["مَآ","tidak"],["أَتَى","datang"],["ٱلَّذِينَ","(kepada) mereka"],["مِن","sebelum mereka"],["قَبْلِهِم","sebelum mereka"],["مِّن","sebarang"],["رَّسُولٍ","Utusan"],["إِلَّا","tetapi"],["قَالُوا۟","mereka berkata"],["سَاحِرٌ","Seorang ahli silap mata"],["أَوْ","atau"],["مَجْنُونٌ","orang gila"]]],"4728":["(Apakah mereka saling berpesan) mereka semuanya (tentang hal itu) Istifham atau kata tanya di sini mengandung makna Nafi. (Sebenarnya mereka adalah kaum yang melampaui batas) sikap kelewat batas merekalah yang mendorong mereka semuanya mengatakan perkataan tersebut.",[["أَتَوَاصَوْا۟","Adakah mereka telah menyampaikannya kepada mereka"],["بِهِۦ ۚ","Adakah mereka telah menyampaikannya kepada mereka"],["بَلْ","Bahkan"],["هُمْ","mereka"],["قَوْمٌۭ","(adalah) suatu kaum"],["طَاغُونَ","melanggar"]]],"4729":["(Maka berpalinglah kamu) palingkanlah dirimu (dari mereka dan kamu sekali-kali tidak tercela) karena sesungguhnya kamu telah menyampaikan risalahmu kepada mereka.",[["فَتَوَلَّ","Jadi berpalinglah"],["عَنْهُمْ","daripada mereka"],["فَمَآ","kerana tidak"],["أَنتَ","kamu"],["بِمَلُومٍۢ","(adalah) harus dipersalahkan"]]],"4730":["(Dan tetaplah memberi peringatan) maksudnya, tetaplah memberi nasihat dengan Alquran (karena sesungguhnya peringatan itu bermanfaat bagi orang-orang yang beriman) hal ini termasuk ilmu Allah swt. yang telah mengetahui, bahwa orang yang bersangkutan adalah orang yang beriman.",[["وَذَكِّرْ","Dan ingatkan"],["فَإِنَّ","kerana sesungguhnya"],["ٱلذِّكْرَىٰ","peringatan itu"],["تَنفَعُ","faedah"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"4731":["(Dan Aku tidak menciptakan jin dan manusia melainkan supaya mereka menyembah-Ku) pengertian dalam ayat ini sama sekali tidak bertentangan dengan kenyataan, bahwa orang-orang kafir tidak menyembah-Nya. Karena sesungguhnya tujuan dari ayat ini tidaklah memastikan keberadaannya. Perihalnya sama saja dengan pengertian yang terdapat di dalam perkataanmu, \"Aku runcingkan pena ini supaya aku dapat menulis dengannya.\" Dan kenyataannya terkadang kamu tidak menggunakannya.",[["وَمَا","Dan tidak"],["خَلَقْتُ","Aku telah mencipta"],["ٱلْجِنَّ","jin"],["وَٱلْإِنسَ","dan umat manusia"],["إِلَّا","kecuali"],["لِيَعْبُدُونِ","supaya mereka menyembah-Ku"]]],"4732":["(Aku tidak menghendaki rezeki sedikit pun dari mereka) untuk-Ku dan untuk mereka serta untuk selain mereka (dan Aku tidak menghendaki supaya mereka memberi Aku makan) baik dari diri mereka atau pun dari selain mereka.",[["مَآ","Tidak"],["أُرِيدُ","aku nak"],["مِنْهُم","daripada mereka"],["مِّن","sebarang"],["رِّزْقٍۢ","peruntukan"],["وَمَآ","dan bukan"],["أُرِيدُ","aku nak"],["أَن","bahawa"],["يُطْعِمُونِ","mereka (harus) memberi makan kepada-Ku"]]],"4733":["(Sesungguhnya Allah Dialah Maha Pemberi rezeki Yang mempunyai Kekuatan lagi Sangat Kokoh) yakni Sangat Perkasa.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلرَّزَّاقُ","(ialah) Maha Pemberi"],["ذُو","Pemilik"],["ٱلْقُوَّةِ","(dari) Kuasa"],["ٱلْمَتِينُ","yang Kuat"]]],"4734":["(Maka sesungguhnya untuk orang-orang yang aniaya) terhadap diri mereka sendiri karena melakukan kekafiran, yaitu dari kalangan penduduk Mekah dan lain-lainnya (ada bagian) bagian siksaan (seperti bagian) yakni sebagaimana bagian siksa yang diterima oleh (teman-teman mereka) yang telah binasa sebelum mereka (maka janganlah mereka meminta kepada-Ku menyegerakannya) meminta azab disegerakan atas mereka bila Aku menangguhkannya sampai hari kiamat nanti.",[["فَإِنَّ","Jadi memang"],["لِلَّذِينَ","bagi mereka yang"],["ظَلَمُوا۟","buat salah"],["ذَنُوبًۭا","(adalah) sebahagian"],["مِّثْلَ","suka"],["ذَنُوبِ","(bahagian)."],["أَصْحَـٰبِهِمْ","(dari) sahabat mereka"],["فَلَا","maka janganlah mereka meminta Aku menyegerakan"],["يَسْتَعْجِلُونِ","maka janganlah mereka meminta Aku menyegerakan"]]],"4735":["(Maka kecelakaanlah) artinya, azab yang amat keraslah (bagi orang-orang yang kafir pada) (hari yang diancamkan kepada mereka) pada hari kiamat nanti.",[["فَوَيْلٌۭ","Kemudian celaka"],["لِّلَّذِينَ","kepada mereka yang"],["كَفَرُوا۟","kufur"],["مِن","daripada"],["يَوْمِهِمُ","Hari mereka"],["ٱلَّذِى","yang"],["يُوعَدُونَ","mereka dijanjikan"]]],"4736":["(Demi Thur) Thur nama sebuah bukit tempat Allah berfirman secara langsung kepada Nabi Musa.",[["وَٱلطُّورِ","Oleh Gunung"]]],"4737":["(Dan demi Kitab yang ditulis).",[["وَكِتَـٰبٍۢ","Dan demi Kitab"],["مَّسْطُورٍۢ","bertulis"]]],"4738":["(Pada lembaran yang terbuka) yakni kitab Taurat atau kitab Alquran.",[["فِى","Dalam"],["رَقٍّۢ","perkamen"],["مَّنشُورٍۢ","terbongkar"]]],"4739":["(Dan demi Baitulmakmur) yang berada di langit ketiga, atau keenam atau yang ketujuh, letaknya persis berada di atas Kakbah; setiap hari diziarahi oleh tujuh puluh ribu malaikat yang melakukan tawaf dan salat di situ dan mereka tidak kembali lagi kepadanya untuk selama-lamanya.",[["وَٱلْبَيْتِ","Oleh Dewan"],["ٱلْمَعْمُورِ","kerap dikunjungi"]]],"4740":["(Dan demi atap yang ditinggikan) yakni langit.",[["وَٱلسَّقْفِ","Di tepi bumbung"],["ٱلْمَرْفُوعِ","dinaikkan tinggi"]]],"4741":["(Dan demi laut yang penuh) penuh airnya.",[["وَٱلْبَحْرِ","Di tepi laut"],["ٱلْمَسْجُورِ","diisi"]]],"4742":["(Sesungguhnya azab Rabbmu pasti terjadi) pasti menimpa orang yang berhak menerimanya.",[["إِنَّ","Sesungguhnya"],["عَذَابَ","azab"],["رَبِّكَ","Tuhanmu"],["لَوَٰقِعٌۭ","(akan) pasti berlaku"]]],"4743":["(Tidak ada seorang pun yang dapat menolaknya) yang mampu menolak azab itu.",[["مَّا","Tidak"],["لَهُۥ","baginya"],["مِن","sebarang"],["دَافِعٍۢ","pencegah"]]],"4744":["(Pada hari) menjadi Ma'mul bagi lafal Waaqi'un (ketika langit benar-benar berguncang) pada waktu langit bergerak dan berputar.",[["يَوْمَ","(Pada) Hari"],["تَمُورُ","akan bergegar"],["ٱلسَّمَآءُ","syurga itu"],["مَوْرًۭا","(dengan ganas) goncangan"]]],"4745":["(Dan gunung-gunung benar-benar berjalan) maksudnya, menjadi debu yang beterbangan, demikian itu adalah hari kiamat.",[["وَتَسِيرُ","Dan akan menjauh"],["ٱلْجِبَالُ","pergunungan"],["سَيْرًۭا","(dengan pergerakan yang mengerikan)."]]],"4746":["(Maka kecelakaan yang besar) azab yang keras (di hari itu bagi orang-orang yang mendustakan) rasul-rasul.",[["فَوَيْلٌۭ","Kemudian celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"4747":["(Yaitu orang-orang yang dalam kebatilan) dalam perkara yang batil (mereka bermain-main) mereka sibuk dengan kekafiran mereka.",[["ٱلَّذِينَ","Siapa"],["هُمْ","[mereka]"],["فِى","dalam"],["خَوْضٍۢ","(sia-sia) wacana"],["يَلْعَبُونَ","sedang bermain"]]],"4748":["(pada hari mereka didorong ke neraka Jahanam dengan sekuat-kuatnya) mereka didorong dengan kasar. Lafal ayat ini menjadi Badal dari lafal Yauma Tamuuru. Kemudian dikatakan kepada mereka dengan nada mencemoohkan,",[["يَوْمَ","(The) Hari"],["يُدَعُّونَ","mereka akan didorong"],["إِلَىٰ","(dalam)kepada"],["نَارِ","(the) Api"],["جَهَنَّمَ","(dari) Neraka"],["دَعًّا","(dengan) tujahan"]]],"4749":["(\"Inilah neraka yang dahulu kalian selalu mendustakannya\").",[["هَـٰذِهِ","Ini"],["ٱلنَّارُ","(ialah) Api"],["ٱلَّتِى","yang"],["كُنتُم","kamu pernah"],["بِهَا","[daripadanya]"],["تُكَذِّبُونَ","menafikan"]]],"4750":["(Maka apakah ini sihir) maksudnya, apakah azab yang kalian lihat sekarang seperti juga apa yang kalian katakan mengenai wahyu, bahwa itu adalah sihir. (Ataukah kalian tidak melihat?).",[["أَفَسِحْرٌ","Kemudian adalah sihir ini"],["هَـٰذَآ","Kemudian adalah sihir ini"],["أَمْ","atau"],["أَنتُمْ","kamu"],["لَا","jangan"],["تُبْصِرُونَ","lihat"]]],"4751":["(Masukilah ia dan bersabarlah kalian) menanggung azabnya (atau kalian tidak bersabar) kalian tidak tahan (sama saja bagi kalian) karena sesungguhnya kesabaran kalian tidak ada manfaatnya sama sekali (sesungguhnya kalian hanya diberi balasan terhadap apa yang telah kalian kerjakan) tentang pembalasannya.",[["ٱصْلَوْهَا","Bakar di dalamnya"],["فَٱصْبِرُوٓا۟","maka bersabarlah"],["أَوْ","atau"],["لَا","jangan"],["تَصْبِرُوا۟","bersabarlah"],["سَوَآءٌ","(ia) sama"],["عَلَيْكُمْ ۖ","bagi kamu"],["إِنَّمَا","Hanya"],["تُجْزَوْنَ","kamu sedang diberi ganjaran"],["مَا","(untuk) apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"4752":["(Sesungguhnya orang-orang yang bertakwa berada dalam surga dan kenikmatan).",[["إِنَّ","Sesungguhnya"],["ٱلْمُتَّقِينَ","orang yang soleh"],["فِى","(akan) masuk"],["جَنَّـٰتٍۢ","Taman-taman"],["وَنَعِيمٍۢ","dan kesenangan"]]],"4753":["(Mereka bersuka ria) artinya, hidup penuh dengan kesenangan (dengan apa) huruf Maa di sini adalah Mashdariyah (yang didatangkan kepada mereka) diberikan kepada mereka (oleh Rabb mereka; dan Rabb mereka memelihara mereka dari azab neraka) lafal Wawaqaahum di'athafkan kepada lafal Ataahum. Yakni mereka hidup dengan pemberian Rabb mereka dan berada dalam pemeliharaan-Nya. Lalu dikatakan kepada mereka,",[["فَـٰكِهِينَ","Menikmati"],["بِمَآ","pada apa"],["ءَاتَىٰهُمْ","telah memberi mereka"],["رَبُّهُمْ","Tuhan mereka"],["وَوَقَىٰهُمْ","dan melindungi mereka"],["رَبُّهُمْ","Tuhan mereka"],["عَذَابَ","(dari) hukuman"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"4754":["(\"Makan dan minumlah dengan enak) lafal Hanii-an menjadi Hal atau kata keterangan keadaan, artinya dengan nikmat (sebagai balasan dari apa) huruf Ba di sini mengandung makna Sababiyah (yang telah kalian kerjakan\").",[["كُلُوا۟","makan"],["وَٱشْرَبُوا۟","dan minum"],["هَنِيٓـًٔۢا","(dalam) kepuasan"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"4755":["(Mereka bertelekan) menjadi Hal dari Dhamir yang terkandung di dalam firman-Nya, \"Fii jannaatin\" (di atas dipan-dipan berderetan) sebagian dari dipan-dipan itu letaknya berdampingan dengan yang lainnya (dan Kami kawinkan mereka) di'athafkan kepada lafal jannaatin, yakni Kami buat mereka senang dan tenang (dengan bidadari-bidadari) yang jeli matanya lagi sangat cantik.",[["مُتَّكِـِٔينَ","Berbaring"],["عَلَىٰ","pada"],["سُرُرٍۢ","takhta"],["مَّصْفُوفَةٍۢ ۖ","beratur"],["وَزَوَّجْنَـٰهُم","dan Kami akan mengahwini mereka"],["بِحُورٍ","kepada yang adil"],["عِينٍۢ","(dengan) mata yang besar"]]],"4756":["(Dan orang-orang yang beriman) berkedudukan menjadi Mubtada (dan mereka diikuti) menurut suatu qiraat dibaca Wa-atba'naahum yakni, Kami ikutkan kepada mereka, Di'athafkan kepada lafal Amanuu (oleh anak cucu mereka) menurut suatu qiraat dibaca Dzurriyyatahum, dalam bentuk Mufrad; artinya oleh keturunan mereka, baik yang masih kecil maupun yang sudah dewasa (dalam keimanan) maksudnya, diikuti oleh anak cucu mereka keimanannya. Dan yang menjadi Khabarnya ialah (Kami hubungkan anak cucu mereka dengan mereka) ke dalam surga, dengan demikian maka anak cucu mereka memiliki kedudukan yang sama dengan mereka, sekalipun anak cucu mereka tidak mempunyai amalan sebagaimana mereka. Hal ini dimaksudkan sebagai kehormatan buat bapak-bapak mereka, yang karenanya lalu anak cucu mereka dikumpulkan dengan mereka (dan Kami tidak mengurangi) dapat dibaca Alatnaahum atau Alitnaahum, artinya Kami tidak mengurangi (dari pahala amal mereka) huruf Min di sini adalah Zaidah (barang sedikit pun) yang ditambahkan kepada amal perbuatan anak-cucu mereka. (Tiap-tiap orang dengan apa yang dikerjakannya) yakni amal baik atau amal buruknya (terikat) yakni, ia dalam keadaan terikat, bila ia mengerjakan kejahatan diazab dan bila ia mengerjakan kebaikan diberi pahala.",[["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["وَٱتَّبَعَتْهُمْ","dan mengikuti mereka"],["ذُرِّيَّتُهُم","keturunan mereka"],["بِإِيمَـٰنٍ","dalam iman"],["أَلْحَقْنَا","Kami akan sertai"],["بِهِمْ","bersama mereka"],["ذُرِّيَّتَهُمْ","keturunan mereka"],["وَمَآ","dan bukan"],["أَلَتْنَـٰهُم","Kami akan merampas mereka"],["مِّنْ","daripada"],["عَمَلِهِم","perbuatan mereka"],["مِّن","(dalam) mana-mana"],["شَىْءٍۢ ۚ","perkara"],["كُلُّ","Setiap"],["ٱمْرِئٍۭ","orang"],["بِمَا","bagi apa"],["كَسَبَ","dia perolehi"],["رَهِينٌۭ","(adalah) dicagarkan"]]],"4757":["(Dan Kami beri mereka) Kami tambahkan kepada mereka dari waktu ke waktu yang lain (dengan buah-buahan dan daging dari segala jenis yang mereka inginkan) sekalipun mereka tidak menjelaskan permintaannya.",[["وَأَمْدَدْنَـٰهُم","Dan Kami akan memberi mereka rezeki"],["بِفَـٰكِهَةٍۢ","dengan buah"],["وَلَحْمٍۢ","dan daging"],["مِّمَّا","daripada apa"],["يَشْتَهُونَ","mereka inginkan"]]],"4758":["(Mereka saling memperebutkan) mereka saling beri (di dalamnya) dalam surga (piala) yang berisikan khamar (yang isinya tidak menimbulkan kata-kata yang tidak berfaedah) di antara mereka disebabkan karena meminumnya (dan tiada pula perbuatan dosa) yang menimpa mereka disebabkan meminumnya, berbeda dengan khamar di dunia.",[["يَتَنَـٰزَعُونَ","Mereka akan berpindah kepada satu sama lain"],["فِيهَا","di dalamnya"],["كَأْسًۭا","secawan"],["لَّا","tidak"],["لَغْوٌۭ","pertuturan yang tidak baik"],["فِيهَا","di dalamnya"],["وَلَا","dan tidak"],["تَأْثِيمٌۭ","dosa"]]],"4759":["(Dan berkeliling di sekitar mereka) sebagai pelayan-pelayan (anak-anak muda) yang semuanya orang-orang merdeka (untuk meladeni mereka seakan-akan mereka itu) kecakapan dan kelembutannya (mutiara yang tersimpan) artinya mereka itu bagaikan mutiara yang disimpan di dalam laut; karena sesungguhnya mutiara yang tersimpan di dalam laut itu jauh lebih indah daripada mutiara-mutiara yang berada di tempat lainnya.",[["۞ وَيَطُوفُ","Dan akan beredar"],["عَلَيْهِمْ","antara mereka"],["غِلْمَانٌۭ","budak lelaki"],["لَّهُمْ","bagi mereka"],["كَأَنَّهُمْ","seolah-olah mereka (adalah)"],["لُؤْلُؤٌۭ","mutiara"],["مَّكْنُونٌۭ","terlindung dengan baik"]]],"4760":["(Dan sebagian mereka menghadap kepada sebagian yang lain saling tanya menanya) atau sebagian di antara mereka bertanya kepada sebagian yang lain tentang apa yang telah mereka kerjakan di dunia, dan tentang pahala yang telah mereka peroleh, dengan maksud untuk bersenang-senang dan mengakui nikmat Allah.",[["وَأَقْبَلَ","Dan akan mendekati"],["بَعْضُهُمْ","sebahagian mereka"],["عَلَىٰ","kepada"],["بَعْضٍۢ","yang lain"],["يَتَسَآءَلُونَ","menyiasat"]]],"4761":["(Mereka berkata) seraya mengisyaratkan kepada penyebab mereka sampai kepada derajat ini, (\"Sesungguhnya kami dahulu, sewaktu berada di tengah-tengah keluarga kami) di dunia (kami merasa takut) akan azab Allah.",[["قَالُوٓا۟","Mereka akan berkata"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","[kami] dulu"],["قَبْلُ","sebelum"],["فِىٓ","antara"],["أَهْلِنَا","keluarga kita"],["مُشْفِقِينَ","takut"]]],"4762":["(Maka Allah memberikan karunia kepada kami) berupa ampunan (dan memelihara kami dari azab neraka\") dinamakan Samuum karena sakitnya sampai merasuk ke dalam pori-pori. Dan mereka mengisyaratkan pula melalui perkataan mereka,",[["فَمَنَّ","Tetapi Allah memberi nikmat"],["ٱللَّهُ","Tetapi Allah memberi nikmat"],["عَلَيْنَا","atas kita"],["وَوَقَىٰنَا","dan melindungi kami"],["عَذَابَ","(dari) hukuman"],["ٱلسَّمُومِ","(dari) Api yang Membara"]]],"4763":["(\"Sesungguhnya kami dahulu) sewaktu di dunia (menyeru-Nya) menyembah dan mengesakan-Nya. (Sesungguhnya Dia) kalau dibaca Innahuu dengan dikasrahkan huruf Hamzahnya, berarti merupakan jumlah Isti'naf atau kalimat permulaan, sekalipun maknanya mengandung 'Illat. Dan bila dibaca Annahuu dengan difatahkan huruf Hamzahnya, berarti lafalnya menunjukkan makna 'Illat (adalah yang melimpahkan kebaikan) Yang berbuat kebaikan dan menepati janji-Nya (lagi Maha",[["إِنَّا","Sesungguhnya kami"],["كُنَّا","[kita] dulu"],["مِن","sebelum"],["قَبْلُ","sebelum"],["نَدْعُوهُ ۖ","panggil Dia"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","[Dia]"],["ٱلْبَرُّ","(adalah) Yang Maha Pemurah"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"4764":["(Maka tetaplah memberi peringatan) tetaplah kamu memberi peringatan kepada orang-orang musyrik dan jangan sekali-kali kamu mundur dalam hal ini hanya karena mereka mengatakanmu sebagai seorang penenung lagi gila (dan kamu disebabkan nikmat Rabbmu bukanlah) karena limpahan nikmat-Nya kepadamu (seorang tukang tenung) menjadi Khabar dari Maa (dan bukan pula seorang gila\") lafal ayat ini di'athafkan kepada lafal Kaahinin.",[["فَذَكِّرْ","Oleh itu ingatkan"],["فَمَآ","kerana tidak"],["أَنتَ","kamu"],["بِنِعْمَتِ","(adalah) dengan rahmat"],["رَبِّكَ","Tuhanmu"],["بِكَاهِنٍۢ","tukang ramal"],["وَلَا","dan bukan"],["مَجْنُونٍ","orang gila"]]],"4765":["(Bahkan) lebih dari itu (mereka mengatakan,) \"Dia (adalah seorang penyair yang kami tunggu-tunggu kecelakaan menimpanya\") malapetaka menimpanya lalu ia binasa sebagaimana nasib yang dialami oleh para penyair lainnya.",[["أَمْ","Atau"],["يَقُولُونَ","(lakukan) mereka berkata"],["شَاعِرٌۭ","Seorang penyair"],["نَّتَرَبَّصُ","kita tunggu"],["بِهِۦ","baginya"],["رَيْبَ","malang masa"],["ٱلْمَنُونِ","malang masa"]]],"4766":["(Katakanlah! \"Tunggulah) oleh kalian kebinasaanku (maka sesungguhnya aku pun termasuk orang yang menunggu pula bersama kalian\") menunggu kebinasaan kalian; akhirnya mereka disiksa oleh Allah melalui pedang dalam perang Badar. Makna Tarabbush. adalah menunggu.",[["قُلْ","Katakanlah"],["تَرَبَّصُوا۟","Tunggu"],["فَإِنِّى","kerana sesungguhnya aku"],["مَعَكُم","bersama kamu"],["مِّنَ","antara"],["ٱلْمُتَرَبِّصِينَ","mereka yang menunggu"]]],"4767":["(Apakah mereka diperintah oleh pikiran pikiran mereka) oleh akal pikiran mereka (untuk mengucapkan tuduhan-tuduhan itu) yakni perkataan mereka terhadapnya, bahwa dia adalah seorang tukang sihir, seorang tukang tenung, dan seorang gila. Maksudnya, ialah bahwa pikiran-pikiran mereka tidak memerintahkan mereka untuk melakukan hal tersebut (bahkan) lebih dari itu (mereka kaum yang melampaui batas) dengan keingkaran dan pembangkangan mereka itu.",[["أَمْ","Atau"],["تَأْمُرُهُمْ","perintahkan mereka"],["أَحْلَـٰمُهُم","fikiran mereka"],["بِهَـٰذَآ ۚ","ini"],["أَمْ","atau"],["هُمْ","mereka"],["قَوْمٌۭ","(adalah) suatu kaum"],["طَاغُونَ","melanggar"]]],"4768":["(Ataukah mereka mengatakan, bahwa dia membuat-buatnya) yakni Nabi Muhammad telah membuat-buat Alquran, padahal dia tidak membuat-buatnya (sebenarnya mereka tidak beriman) karena kesombongan mereka. Jika mereka mengatakan bahwa Muhammad telah membuat-buatnya.",[["أَمْ","Atau"],["يَقُولُونَ","(lakukan) mereka berkata"],["تَقَوَّلَهُۥ ۚ","Dia telah mengada-adakan"],["بَل","Bahkan"],["لَّا","tidak"],["يُؤْمِنُونَ","mereka beriman"]]],"4769":["(Maka hendaklah mereka mendatangkan kalimat) yang dibuat-buat (yang semisal dengan Alquran itu jika mereka orang-orang yang benar) di dalam tuduhannya itu.",[["فَلْيَأْتُوا۟","Kemudian biarkan mereka membawa"],["بِحَدِيثٍۢ","satu kenyataan"],["مِّثْلِهِۦٓ","suka"],["إِن","jika"],["كَانُوا۟","mereka adalah"],["صَـٰدِقِينَ","jujur"]]],"4770":["(Apakah mereka diciptakan tanpa sesuatu pun) tanpa ada yang menciptakannya (ataukah mereka yang menciptakan) diri mereka sendiri. Dan tidak masuk akal ada makhluk tanpa pencipta, dan tiada sesuatu yang Ma'dum yakni yang asalnya tiada, dapat menciptakan yang menciptakannya, yaitu Allah yang Maha Esa. Mereka tetap tidak mau mengesakan-Nya dan tidak mau beriman kepada rasul dan kitab-Nya.",[["أَمْ","Atau"],["خُلِقُوا۟","mereka dicipta"],["مِنْ","daripada"],["غَيْرِ","tiada apa"],["شَىْءٍ","tiada apa"],["أَمْ","atau"],["هُمُ","(adalah) mereka"],["ٱلْخَـٰلِقُونَ","para pencipta"]]],"4771":["(Ataukah mereka telah menciptakan langit dan bumi itu?) tiada seorang pun yang dapat menciptakan keduanya selain Allah Yang Maha Pencipta; maka mengapa tidak menyembah-Nya. (Sebenarnya mereka tidak meyakini) Allah, karena seandainya mereka beriman kepada-Nya, niscaya mereka pun akan beriman kepada Nabi-Nya.",[["أَمْ","Atau"],["خَلَقُوا۟","(adakah) mereka cipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ ۚ","dan bumi"],["بَل","Bahkan"],["لَّا","tidak"],["يُوقِنُونَ","mereka pasti"]]],"4772":["(Ataukah di sisi mereka ada perbendaharaan Rabbmu) berupa kenabian, rezeki dan hal-hal lainnya, lalu karenanya mereka dapat memberikannya kepada siapa yang dikehendaki oleh mereka sesuai dengan apa yang mereka sukai (atau merekakah yang berkuasa?) yang mempunyai kekuasaan dan dapat berlaku sewenang-wenang. Fi'il atau kata kerja dari lafal Mushaythir ini adalah Saythara, maknanya sesinonim dengan lafal Baithara dan Baiqara.",[["أَمْ","Atau"],["عِندَهُمْ","bersama mereka"],["خَزَآئِنُ","(adalah) khazanah"],["رَبِّكَ","Tuhanmu"],["أَمْ","atau"],["هُمُ","(adalah) mereka"],["ٱلْمُصَۣيْطِرُونَ","para pengawal"]]],"4773":["(Ataukah mereka mempunyai tangga) alat untuk naik ke langit (untuk mendengarkan pada langit itu?) perkataan para malaikat sehingga mereka dapat menyaingi nabi, sesuai dengan pengakuan mereka seandainya mereka mengaku-aku memiliki hal tersebut (Maka hendaklah orang yang mendengarkan di antara mereka mendatangkan) orang yang mengaku-aku dapat mendengarkan perkataan malaikat-malaikat di langit (suatu keterangan yang nyata) atau hujah yang jelas lagi gamblang. Mengingat adanya keserupaan pada tuduhan ini dengan tuduhan mereka yang menyatakan, bahwa malaikat-malaikat itu adalah anak-anak perempuan Allah, maka Allah swt. berfirman,",[["أَمْ","Atau"],["لَهُمْ","bagi mereka"],["سُلَّمٌۭ","(adalah) tangga"],["يَسْتَمِعُونَ","mereka mendengar"],["فِيهِ ۖ","dengan itu"],["فَلْيَأْتِ","Kemudian mari bawa"],["مُسْتَمِعُهُم","pendengar mereka"],["بِسُلْطَـٰنٍۢ","sebuah pihak berkuasa"],["مُّبِينٍ","yang nyata"]]],"4774":["(\"Ataukah untuk Allah anak-anak perempuan) sesuai dengan tuduhan kalian (dan untuk kalian anak-anak laki-laki?) Maha Tinggi Allah dari segala apa yang mereka duga itu.",[["أَمْ","Atau"],["لَهُ","untuk Dia"],["ٱلْبَنَـٰتُ","(adalah) anak perempuan"],["وَلَكُمُ","manakala untuk kamu"],["ٱلْبَنُونَ","(adalah) anak lelaki"]]],"4775":["(Ataukah kalian meminta upah kepada mereka) atas jerih payahmu di dalam menyampaikan agama yang kamu datangkan itu (sehingga mereka oleh utang mereka) oleh tanggungan dalam hal itu (dibebani) karena itu mereka tidak dapat mengembalikannya.",[["أَمْ","Atau"],["تَسْـَٔلُهُمْ","(adakah) kamu meminta daripada mereka"],["أَجْرًۭا","bayaran"],["فَهُم","jadi mereka"],["مِّن","daripada"],["مَّغْرَمٍۢ","hutang"],["مُّثْقَلُونَ","(adalah) terbeban"]]],"4776":["(Apakah ada pada sisi mereka pengetahuan tentang yang gaib) mengetahui hal yang gaib (lalu mereka menuliskannya?) sehingga mereka mampu untuk menentang Nabi saw dalam masalah hari berbangkit dan perkara-perkara akhirat sesuai dengan dugaan mereka.",[["أَمْ","Atau"],["عِندَهُمُ","bersama mereka"],["ٱلْغَيْبُ","(ialah) perkara ghaib"],["فَهُمْ","jadi mereka"],["يَكْتُبُونَ","menulis (ia) ke bawah"]]],"4777":["(Ataukah mereka hendak melakukan tipu daya?) terhadap dirimu dengan maksud untuk membinasakan dirimu, sewaktu mereka berkumpul di Darunnadwah. (Maka orang-orang yang kafir itu merekalah yang kena tipu daya) maksudnya, merekalah yang kalah dan binasa. Allah memelihara nabi dari ulah mereka, kemudian Dia membinasakan mereka dalam perang Badar.",[["أَمْ","Atau"],["يُرِيدُونَ","(adakah) mereka berniat"],["كَيْدًۭا ۖ","plot"],["فَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوا۟","kufur"],["هُمُ","diri mereka"],["ٱلْمَكِيدُونَ","(berada dalam) plot"]]],"4778":["(Ataukah mereka mempunyai tuhan selain Allah. Maha Suci Allah dari apa yang mereka persekutukan\") yakni berhala-berhala yang mereka persekutukan dengan-Nya. Kata tanya dengan memakai lafal Am pada ayat ini dan ayat-ayat sebelumnya mengandung makna memburuk-burukkan dan mencela perbuatan mereka.",[["أَمْ","Atau"],["لَهُمْ","bagi mereka"],["إِلَـٰهٌ","tuhan"],["غَيْرُ","selain daripada"],["ٱللَّهِ ۚ","Allah"],["سُبْحَـٰنَ","Maha Suci"],["ٱللَّهِ","(kepada) Allah"],["عَمَّا","daripada apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"4779":["(Jika mereka melihat sebagian) bagian (dari langit yang gugur) menimpa mereka, sebagaimana yang mereka minta, yaitu seperti yang dijelaskan oleh ayat lain melalui firman-Nya, \"Maka jatuhkanlah atas kami gumpalan dari langit.\" (Q.S. Asy Syu'ara, 187) sebagai azab atas mereka (mereka akan mengatakan,) \"Ini (adalah awan yang bertindih-tindih) awan yang tebal yang akan menyegarkan kami dan mereka tidak mau beriman.\"",[["وَإِن","Dan jika"],["يَرَوْا۟","mereka harus melihat"],["كِسْفًۭا","sebahagian"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["سَاقِطًۭا","jatuh"],["يَقُولُوا۟","mereka akan berkata"],["سَحَابٌۭ","awan"],["مَّرْكُومٌۭ","bertimbun-timbun"]]],"4780":["(Maka biarkanlah mereka hingga mereka menemui hari mereka yang pada hari itu mereka dibinasakan) yaitu mati semuanya.",[["فَذَرْهُمْ","Jadi tinggalkan mereka"],["حَتَّىٰ","sehingga"],["يُلَـٰقُوا۟","mereka berjumpa"],["يَوْمَهُمُ","Hari mereka"],["ٱلَّذِى","yang"],["فِيهِ","di dalamnya"],["يُصْعَقُونَ","mereka akan pengsan"]]],"4781":["(Yaitu hari ketika tidak berguna) menjadi Badal dari lafal Yaumahum (bagi mereka sedikit pun tipu daya mereka dan mereka tidak ditolong) tidak diselamatkan dari azab di akhirat.",[["يَوْمَ","(The) Hari"],["لَا","tidak"],["يُغْنِى","akan mendapat manfaat"],["عَنْهُمْ","kepada mereka"],["كَيْدُهُمْ","perancangan mereka"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنصَرُونَ","akan dibantu"]]],"4782":["(Dan sesungguhnya untuk orang-orang yang lalim) disebabkan kekafiran mereka (ada azab selain daripada itu) di dunia, sebelum kematian mereka; maka mereka disiksa oleh kelaparan dan kekeringan selama tujuh tahun, serta oleh pembunuhan dalam perang Badar. (Tetapi kebanyakan mereka tidak mengetahui) bahwasanya azab itu akan menimpa mereka.",[["وَإِنَّ","Dan sesungguhnya"],["لِلَّذِينَ","bagi mereka yang"],["ظَلَمُوا۟","buat salah"],["عَذَابًۭا","(ialah) azab"],["دُونَ","sebelum"],["ذَٰلِكَ","bahawa"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"4783":["(Dan bersabarlah dalam menunggu ketetapan Rabbmu) yaitu dengan ditangguhkannya mereka dan janganlah dadamu merasa sempit karenanya (maka sesungguhnya kamu berada dalam pengawasan-Ku) yaitu selalu dalam lindungan dan pengawasan-Ku (dan bertasbihlah) seraya (memuji Rabbmu) yaitu katakanlah, 'Subhaanallah Wa Bihamdihii' (ketika kamu bangun berdiri) dari tidurmu atau dari tempat majelismu.",[["وَٱصْبِرْ","Jadi bersabarlah"],["لِحُكْمِ","untuk (the) Perintah"],["رَبِّكَ","Tuhanmu"],["فَإِنَّكَ","kerana sesungguhnya, kamu"],["بِأَعْيُنِنَا ۖ","(ada) di Mata Kami"],["وَسَبِّحْ","Dan bertasbih"],["بِحَمْدِ","(yang) pujian"],["رَبِّكَ","Tuhanmu"],["حِينَ","apabila"],["تَقُومُ","kamu bangkit"]]],"4784":["(Dan pada beberapa saat di malam hari bertasbih pulalah) pengertian bertasbih di sini adalah tasbih hakiki yaitu membaca, 'Subhaanallaah Wa bihamdihii' (dan di waktu terbenam bintang-bintang) lafal Idbaar adalah bentuk Mashdar, yakni setelah bintang-bintang itu terbenam maka bertasbih pulalah kamu. Atau lakukanlah salat Isya'ain yaitu Magrib dan Isya, pada pengertian yang pertama, dan pada pengertian yang kedua adalah salat fajar; menurut pendapat lain salat Subuh.",[["وَمِنَ","Dan daripada"],["ٱلَّيْلِ","malam"],["فَسَبِّحْهُ","bertasbih kepadaNya"],["وَإِدْبَـٰرَ","dan selepas"],["ٱلنُّجُومِ","bintang"]]],"4785":["(Demi bintang) yaitu bintang Tsurayya (ketika terbenam) sewaktu terbenam.",[["وَٱلنَّجْمِ","Oleh bintang"],["إِذَا","apabila"],["هَوَىٰ","ia turun"]]],"4786":["(Kawanmu tidak sesat) artinya, Nabi Muhammad saw. tidak sesat dari jalan petunjuk (dan tidak pula keliru) tidak pula salah, yang dimaksud adalah dia tidak bodoh tentang akidah yang rusak.",[["مَا","Tidak"],["ضَلَّ","telah sesat"],["صَاحِبُكُمْ","teman kamu"],["وَمَا","dan bukan"],["غَوَىٰ","adakah dia tersilap"]]],"4787":["(Dan tiadalah apa yang diucapkannya itu) apa yang disampaikannya kepada kalian (menurut kemauan hawa nafsunya) menurut kehendaknya sendiri.",[["وَمَا","Dan tidak"],["يَنطِقُ","dia bercakap"],["عَنِ","daripada"],["ٱلْهَوَىٰٓ","keinginan itu"]]],"4788":["(Tiada lain) tidak lain (ucapannya itu hanyalah wahyu yang diwahyukan) kepadanya.",[["إِنْ","Tidak"],["هُوَ","ia"],["إِلَّا","(adalah) kecuali"],["وَحْىٌۭ","satu wahyu"],["يُوحَىٰ","didedahkan"]]],"4789":["(Yang diajarkan kepadanya) oleh malaikat (yang sangat kuat).",[["عَلَّمَهُۥ","Telah mengajarnya"],["شَدِيدُ","yang (satu) perkasa"],["ٱلْقُوَىٰ","(dalam) kuasa"]]],"4790":["(Yang mempunyai kecerdasan) yang mempunyai kekuatan dan keperkasaan, atau yang mempunyai pandangan yang baik, yang dimaksud adalah malaikat Jibril a.s. (maka menetaplah ia) maksudnya, menampakkan diri dengan rupa aslinya.",[["ذُو","Pemilik kesihatan"],["مِرَّةٍۢ","Pemilik kesihatan"],["فَٱسْتَوَىٰ","Dan dia bangkit"]]],"4791":["(Sedangkan dia berada di ufuk yang tinggi) berada pada tempat terbitnya matahari dalam bentuk aslinya ketika ia diciptakan. Nabi saw., melihatnya sewaktu berada di gua Hira; dan ternyata tubuh malaikat Jibril menutupi cakrawala tempat terbitnya matahari hingga sampai ke cakrawala bagian timur. Lalu Nabi saw. pingsan tidak sadarkan diri setelah melihat wujud asli malaikat Jibril itu. Nabi saw. pernah meminta kepada malaikat Jibril supaya menampakkan wujud aslinya sebagaimana ketika ia diciptakan oleh Allah, lalu malaikat Jibril menjanjikan akan memenuhi hal tersebut di gua Hira. Setelah itu baru malaikat Jibril turun untuk menemuinya dalam bentuk Bani Adam.",[["وَهُوَ","Manakala dia"],["بِٱلْأُفُقِ","(berada) di kaki langit"],["ٱلْأَعْلَىٰ","paling tinggi"]]],"4792":["(Kemudian dia mendekat) kepadanya (lalu bertambah dekat) semakin dekat dengannya.",[["ثُمَّ","Kemudian"],["دَنَا","dia menghampiri"],["فَتَدَلَّىٰ","dan turun"]]],"4793":["(Maka jadilah dia) padanya (mendekat) dalam jarak (dua ujung busur panah atau lebih dekat lagi) dari tempatnya yang semula sehingga nabi menjadi sadar kembali dan hilanglah rasa takutnya.",[["فَكَانَ","Dan adalah"],["قَابَ","(pada) jarak"],["قَوْسَيْنِ","(dari) dua busur-(panjang)"],["أَوْ","atau"],["أَدْنَىٰ","lebih dekat"]]],"4794":["(Lalu Dia menyampaikan) yakni Allah swt. (kepada hamba-Nya) yaitu malaikat Jibril (apa yang telah diwahyukan)-Nya kepada malaikat Jibril untuk disampaikan kepada Nabi saw. Di sini yang mewahyukan tidak disebutkan karena mengagungkan kedudukan-Nya.",[["فَأَوْحَىٰٓ","Jadi dia mendedahkan"],["إِلَىٰ","kepada"],["عَبْدِهِۦ","hambanya"],["مَآ","apa"],["أَوْحَىٰ","beliau mendedahkan"]]],"4795":["(Tiada mendustakan) dapat dibaca Kadzaba atau Kadzdzaba, artinya tiada mengingkari (hati) atau kalbu Nabi saw. (apa yang telah dilihatnya) dengan mata kepalanya sendiri tentang rupa malaikat Jibril.",[["مَا","Tidak"],["كَذَبَ","berbohong"],["ٱلْفُؤَادُ","hati"],["مَا","apa"],["رَأَىٰٓ","ia melihat"]]],"4796":["(Maka apakah kalian hendak membantahnya) apakah kalian hendak mendebatnya dan mengalahkannya (tentang apa yang telah dilihatnya?) khithab di sini ditujukan kepada orang-orang musyrik yang tidak mempercayai bahwa Nabi saw. melihat malaikat Jibril.",[["أَفَتُمَـٰرُونَهُۥ","Maka kamu akan berdebat dengannya"],["عَلَىٰ","tentang"],["مَا","apa"],["يَرَىٰ","dia nampak"]]],"4797":["(Dan sesungguhnya dia telah melihat Jibril itu) dalam rupa yang asli (pada waktu) pada kesempatan (yang lain).",[["وَلَقَدْ","Dan sungguh"],["رَءَاهُ","dia nampak dia"],["نَزْلَةً","(dalam) keturunan"],["أُخْرَىٰ","yang lain"]]],"4798":["(Yaitu di Sidratul Muntaha) sewaktu nabi dibawanya Isra ke langit. Sidratul Muntaha adalah nama sebuah pohon Nabaq yang terletak di sebelah kanan Arasy; tiada seorang malaikat pun dan tidak pula yang lainnya dapat melewati tempat itu.",[["عِندَ","Dekat"],["سِدْرَةِ","(the) Pokok Lote"],["ٱلْمُنتَهَىٰ","(dari) sempadan tertinggi"]]],"4799":["(Di dekatnya ada surga tempat tinggal) tempat tinggal para malaikat dan arwah-arwah para syuhada dan orang-orang yang bertakwa.",[["عِندَهَا","Berdekatan dengannya"],["جَنَّةُ","(ialah) Taman"],["ٱلْمَأْوَىٰٓ","(dari) Tempat tinggal"]]],"4800":["(Ketika) sewaktu (Sidratul Muntaha diliputi oleh sesuatu yang meliputinya) yaitu oleh burung-burung dan lain-lainnya. Lafal Idz menjadi Ma'mul dari lafal Ra-aahu.",[["إِذْ","Apabila"],["يَغْشَى","bertutup"],["ٱلسِّدْرَةَ","Pokok Lote"],["مَا","apa"],["يَغْشَىٰ","meliputi"]]],"4801":["(Penglihatannya tidak berpaling) penglihatan Nabi saw. tidak berpaling (dan tidak melampauinya) maksudnya, tidak berpaling dari apa yang dilihatnya dan tidak pula melampaui apa yang dilihatnya pada malam ketika ia diisrakkan.",[["مَا","Tidak"],["زَاغَ","melencong"],["ٱلْبَصَرُ","penglihatan itu"],["وَمَا","dan bukan"],["طَغَىٰ","ia melanggar"]]],"4802":["(Sesungguhnya dia telah melihat) pada malam itu (sebagian tanda-tanda kekuasaan Rabbnya yang paling besar) yang paling agung, dimaksud adalah sebagian dari tanda-tanda itu, maka dia melihat sebagian dari keajaiban-keajaiban alam malakut, dan Rafraf berwarna hijau menutupi cakrawala langit, dan malaikat Jibril yang memiliki enam ratus sayap.",[["لَقَدْ","Sungguh"],["رَأَىٰ","dia nampak"],["مِنْ","daripada"],["ءَايَـٰتِ","(the) Tanda-tanda"],["رَبِّهِ","(dari) Tuhannya"],["ٱلْكُبْرَىٰٓ","yang Terhebat"]]],"4803":["(Maka apakah patut kalian menganggap Laata dan Al Uzzaa).",[["أَفَرَءَيْتُمُ","Jadi adakah kamu melihat"],["ٱللَّـٰتَ","orang Lat"],["وَٱلْعُزَّىٰ","dan Uzza"]]],"4804":["(Dan Manat yang ketiga) yang ketiga dari yang telah disebutkan tadi (yang paling terkemudian) berkedudukan sebagai sifat yang mengandung makna celaan. Ketiganya adalah nama berhala-berhala yang terbuat dari batu. Orang-orang musyrik dahulu menyembahnya, karena mereka menduga, bahwa berhala-berhala itu dapat memberikan syafaat kepada diri mereka di sisi Allah. Maf'ul pertama bagi lafal Afara`aytum adalah lafal Al Laata dan lafal-lafal yang di'athafkan kepadanya. Sedangkan Maf'ul yang keduanya tidak disebutkan. Makna ayat, \"Ceritakanlah kepadaku, apakah berhala-berhala ini memiliki kemampuan untuk berbuat sesuatu yang karena itu kalian menyembahnya selain Allah Yang memiliki kemampuan untuk melakukan hal-hal yang telah disebutkan tadi.\" Ketika mereka menduga bahwa malaikat-malaikat itu adalah anak-anak perempuan Allah, sedangkan mereka sendiri tidak menyukai anak-anak perempuan, lalu turunlah firman-Nya berikut ini,",[["وَمَنَوٰةَ","Dan Manat"],["ٱلثَّالِثَةَ","yang ketiga"],["ٱلْأُخْرَىٰٓ","yang lain"]]],"4805":["(\"Apakah patut untuk kalian anak laki-laki dan untuk Allah -anak -perempuan?\").",[["أَلَكُمُ","Adalah untuk kamu"],["ٱلذَّكَرُ","lelaki itu"],["وَلَهُ","dan untuk Dia"],["ٱلْأُنثَىٰ","perempuan itu"]]],"4806":["(Yang demikian itu tentulah suatu pembagian yang tidak adil) pembagian yang lalim; berasal dari lafal Dhaazahu Yadhiizuhu, artinya berlaku aniaya dan melampaui batas.",[["تِلْكَ","Ini"],["إِذًۭا","kemudian"],["قِسْمَةٌۭ","(adalah) pembahagian"],["ضِيزَىٰٓ","tidak adil"]]],"4807":["(Itu tidak lain) apa-apa yang telah disebutkan itu (hanyalah nama-nama yang kalian adakan) kalian menamakannya (yakni oleh kalian dan bapak-bapak kalian) sebagai berhala-berhala yang kalian menyembahnya (Allah tidak menurunkan tentangnya) tentang menyembah kepada berhala-berhala itu (suatu keterangan pun) yakni bukti dan hujjah (tiada lain) (mereka hanya mengikuti) di dalam menyembah berhala-berhala itu (sangkaan saja dan apa yang diinginkan oleh hawa nafsu mereka) mengikuti apa yang dihiaskan oleh setan, ke dalam hati mereka, yaitu bahwasanya berhala-berhala itu dapat memberikan syafaat kepada diri mereka di sisi Allah swt. (dan sesungguhnya telah datang petunjuk kepada mereka dari Rabb mereka) melalui lisan Nabi saw. yang membawa bukti yang pasti, akan tetapi mereka tidak mau meninggalkan apa yang biasa mereka lakukan itu, yaitu menyembah berhala.",[["إِنْ","Tidak"],["هِىَ","mereka"],["إِلَّآ","(adalah) kecuali"],["أَسْمَآءٌۭ","nama"],["سَمَّيْتُمُوهَآ","kamu telah menamakan mereka"],["أَنتُمْ","kamu"],["وَءَابَآؤُكُم","dan nenek moyang kamu"],["مَّآ","tidak"],["أَنزَلَ","adakah Allah menurunkan"],["ٱللَّهُ","adakah Allah menurunkan"],["بِهَا","baginya"],["مِن","sebarang"],["سُلْطَـٰنٍ ۚ","pihak berkuasa"],["إِن","Tidak"],["يَتَّبِعُونَ","mereka ikut"],["إِلَّا","kecuali"],["ٱلظَّنَّ","andaian"],["وَمَا","dan apa"],["تَهْوَى","keinginan"],["ٱلْأَنفُسُ ۖ","jiwa (mereka)."],["وَلَقَدْ","Dan sungguh"],["جَآءَهُم","telah datang kepada mereka"],["مِّن","daripada"],["رَّبِّهِمُ","Tuhan mereka"],["ٱلْهُدَىٰٓ","bimbingan"]]],"4808":["(Atau apakah manusia akan mendapat) bagi masing-masing dari mereka (segala yang dicita-citakannya) yang beranggapan, bahwa berhala-berhala itu dapat memberikan syafaat kepada mereka? Padahal kenyataannya tidaklah demikian.",[["أَمْ","Atau"],["لِلْإِنسَـٰنِ","(adalah) untuk manusia"],["مَا","apa"],["تَمَنَّىٰ","dia mahu"]]],"4809":["(Maka hanya bagi Allah kehidupan akhirat dan kehidupan dunia) tiada sesuatu pun yang terjadi pada keduanya melainkan sesuai dengan apa yang dikehendaki-Nya.",[["فَلِلَّهِ","Tetapi kerana Allah"],["ٱلْـَٔاخِرَةُ","(adalah) yang terakhir"],["وَٱلْأُولَىٰ","dan yang pertama"]]],"4810":["(Dan berapa banyaknya malaikat) banyak di antara para Malaikat (di langit) yang sangat dimuliakan oleh Allah di sisi-Nya (syafaat mereka sedikit pun tidak berguna kecuali sesudah Allah mengizinkan) kepada mereka untuk memberikan syafaat (bagi orang yang dikehendaki)-Nya di antara hamba-hamba-Nya (dan diridai) ia diridai oleh-Nya, karena ada firman lainnya yang menyatakan, \".. dan mereka tiada memberi syafaat melainkan kepada orang yang diridai Allah.\" (Q.S. Al Anbiya, 28) Sudah kita maklumi bahwa syafaat para malaikat itu baru ada setelah terlebih dahulu mendapat izin dari Allah, sebagaimana yang dijelaskan dalam ayat lainnya, yaitu firman-Nya, \"Siapakah yang dapat memberi syafaat di sisi Allah tanpa izin-Nya?\" (Q.S. Al-Baqarah, 255)",[["۞ وَكَم","Dan berapa banyak"],["مِّن","daripada"],["مَّلَكٍۢ","(para) Malaikat"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["لَا","tidak"],["تُغْنِى","akan mendapat manfaat"],["شَفَـٰعَتُهُمْ","syafaat mereka"],["شَيْـًٔا","sesuatu"],["إِلَّا","kecuali"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["أَن","[bahawa]"],["يَأْذَنَ","Allah dah beri izin"],["ٱللَّهُ","Allah dah beri izin"],["لِمَن","untuk siapa"],["يَشَآءُ","Dia kehendaki"],["وَيَرْضَىٰٓ","dan meluluskan"]]],"4811":["(Sesungguhnya orang-orang yang tiada beriman kepada kehidupan akhirat, mereka benar-benar menamakan malaikat itu dengan nama perempuan) karena mereka telah mengatakan, bahwa para malaikat itu adalah anak-anak perempuan Allah.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["لَيُسَمُّونَ","pasti mereka namakan"],["ٱلْمَلَـٰٓئِكَةَ","para Malaikat"],["تَسْمِيَةَ","nama"],["ٱلْأُنثَىٰ","(dari) perempuan"]]],"4812":["(Dan mereka tidak mendasari perkataan mereka itu) ucapan mereka itu tidak didasari (dengan sesuatu pengetahuan pun tentangnya. Tiada lain) mereka hanya mengikuti) dalam hal tersebut (prasangka) yang mereka khayalkan (sedangkan sesungguhnya prasangka itu tiada berfaedah sedikit pun terhadap kebenaran) maksudnya, tiada sedikit pun pengetahuan yang bermanfaat dalam prasangka itu di dalam menelaah hal-hal yang dituntut adanya pengetahuan.",[["وَمَا","Dan tidak"],["لَهُم","bagi mereka"],["بِهِۦ","mengenainya"],["مِنْ","sebarang"],["عِلْمٍ ۖ","pengetahuan"],["إِن","Tidak"],["يَتَّبِعُونَ","mereka ikut"],["إِلَّا","tetapi"],["ٱلظَّنَّ ۖ","andaian"],["وَإِنَّ","Dan sesungguhnya"],["ٱلظَّنَّ","andaian itu"],["لَا","tidak"],["يُغْنِى","manfaat"],["مِنَ","terhadap"],["ٱلْحَقِّ","kebenaran"],["شَيْـًۭٔا","sesuatu"]]],"4813":["(Maka berpalinglah dari orang yang berpaling dari peringatan Kami) orang yang berpaling dari Alquran (dan tidak mengingini kecuali kehidupan duniawi) ayat ini diturunkan sebelum ada perintah berjihad dari Allah.",[["فَأَعْرِضْ","Jadi berpalinglah"],["عَن","daripada"],["مَّن","(dia) siapa"],["تَوَلَّىٰ","berpaling"],["عَن","daripada"],["ذِكْرِنَا","Peringatan Kami"],["وَلَمْ","dan bukan"],["يُرِدْ","dia berhajat"],["إِلَّا","kecuali"],["ٱلْحَيَوٰةَ","kehidupan"],["ٱلدُّنْيَا","dunia"]]],"4814":["(Yang demikian itu) yakni mencari keduniaan (adalah sejauh-jauh pengetahuan mereka) artinya, tujuan pengetahuan mereka ialah memilih keduniawian daripada akhirat. (Sesungguhnya Rabbmu, Dia-lah yang paling mengetahui siapa yang tersesat dari jalan-Nya dan Dia pulalah yang paling mengetahui siapa yang mendapat petunjuk) atau Dia mengetahui siapa yang mendapat petunjuk dan siapa yang tersesat, kelak Dia akan memberikan balasan-Nya kepada masing-masing.",[["ذَٰلِكَ","Itu"],["مَبْلَغُهُم","(ialah) jumlah mereka"],["مِّنَ","daripada"],["ٱلْعِلْمِ ۚ","pengetahuan"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","(ialah) Dia (Siapa)"],["أَعْلَمُ","lebih tahu"],["بِمَن","(dia) siapa"],["ضَلَّ","sesat"],["عَن","daripada"],["سَبِيلِهِۦ","Jalan-Nya"],["وَهُوَ","dan Dia"],["أَعْلَمُ","lebih tahu"],["بِمَنِ","(dia) siapa"],["ٱهْتَدَىٰ","dibimbing"]]],"4815":["(Dia hanya kepunyaan Allah-lah apa yang ada di langit dan apa yang ada di bumi) Dia-lah yang memiliki kesemuanya itu; antara lain ialah orang yang tersesat dan orang yang mendapat petunjuk; Dia menyesatkan siapa yang dikehendaki-Nya dan Dia memberikan petunjuk kepada siapa yang dikehendaki-Nya (supaya Dia memberi balasan kepada orang-orang yang berbuat jahat terhadap apa yang mereka kerjakan) berupa kemusyrikan dan perbuatan-perbuatan dosa lainnya (dan memberi balasan kepada orang-orang yang berbuat baik) maksudnya, mereka yang mengerjakan ketauhidan dan amal-amal ketaatan lainnya (dengan pahala yang lebih baik) yakni surga. Kemudian Allah menjelaskan siapakah yang disebut orang-orang yang telah berbuat baik itu melalui firman selanjutnya,",[["وَلِلَّهِ","Dan untuk Allah"],["مَا","(adalah) apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["لِيَجْزِىَ","supaya Dia membalasnya"],["ٱلَّذِينَ","orang yang"],["أَسَـٰٓـُٔوا۟","buat jahat"],["بِمَا","dengan apa"],["عَمِلُوا۟","mereka telah lakukan"],["وَيَجْزِىَ","dan balasan"],["ٱلَّذِينَ","orang yang"],["أَحْسَنُوا۟","berbuat baik"],["بِٱلْحُسْنَى","dengan yang terbaik"]]],"4816":["(\"Yaitu orang-orang yang menjauhi dosa-dosa besar dan perbuatan-perbuatan keji selain dari kesalahan-kesalahan kecil) yang dimaksud dari lafal Al Lamam adalah dosa-dosa kecil seperti, melihat wanita lain, menciumnya dan menyentuhnya. Istitsna atau pengecualian di sini bersifat Munqathi' artinya dosa-dosa kecil itu diampuni oleh sebab menjauhi dosa-dosa besar. (Sesungguhnya Rabbmu Maha Luas ampunan-Nya) disebabkan hal tersebut, sebab Dia Penerima Tobat. Ayat ini diturunkan berkenaan dengan orang-orang yang telah mengatakan, salat kami, shaum kami dan haji kami (Dia lebih mengetahui) (tentang kalian ketika Dia menjadikan kalian dari tanah) ketika Dia menciptakan bapak moyang kalian yaitu Adam dari tanah (dan ketika kalian masih berupa janin lafal Ajinnatin adalah bentuk jamak dari lafal Janiin (dalam perut ibu kalian; maka janganlah kalian mengatakan diri kalian suci) janganlah kalian memuji-muji diri kalian sendiri dengan cara ujub atau takabur, akan tetapi bila kalian melakukannya dengan cara mengakui nikmat Allah, maka hal ini dianggap baik (Dia-lah Yang paling mengetahui) Yang mengetahui (tentang orang yang bertakwa\").",[["ٱلَّذِينَ","Orang yang"],["يَجْتَنِبُونَ","elakkan"],["كَبَـٰٓئِرَ","yang besar"],["ٱلْإِثْمِ","dosa"],["وَٱلْفَوَٰحِشَ","dan maksiat"],["إِلَّا","kecuali"],["ٱللَّمَمَ ۚ","kesalahan kecil"],["إِنَّ","sesungguhnya"],["رَبَّكَ","Tuhanmu"],["وَٰسِعُ","(adalah) luas"],["ٱلْمَغْفِرَةِ ۚ","(dalam) pengampunan"],["هُوَ","Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui tentang kamu"],["بِكُمْ","(adalah) yang paling mengetahui tentang kamu"],["إِذْ","apabila"],["أَنشَأَكُم","Dia menghasilkan kamu"],["مِّنَ","daripada"],["ٱلْأَرْضِ","bumi"],["وَإِذْ","dan apabila"],["أَنتُمْ","kamu (adalah)"],["أَجِنَّةٌۭ","janin"],["فِى","dalam"],["بُطُونِ","(rahim)."],["أُمَّهَـٰتِكُمْ ۖ","(dari) ibu kamu"],["فَلَا","Jadi (jangan)"],["تُزَكُّوٓا۟","menyifatkan kesucian"],["أَنفُسَكُمْ ۖ","(kepada) dirimu sendiri"],["هُوَ","Dia"],["أَعْلَمُ","lebih tahu"],["بِمَنِ","(dia) siapa"],["ٱتَّقَىٰٓ","ketakutan"]]],"4817":["(Maka apakah kamu melihat orang yang berpaling) dari keimanan, orang tersebut murtad dari Islam, yaitu ketika ia dicela karena masuk Islam. Lalu ia menjawab, \"Sesungguhnya aku takut akan azab atau siksaan Allah\". Lalu orang yang mencelanya itu mau menanggung siksaan Allah yang akan diterimanya, bila ia kembali kepada kemusyrikan, dan orang yang menanggung itu bersedia untuk memberikan hartanya kepada dia, sejumlah sekian. Akhirnya dia mau kembali kepada kemusyrikannya.",[["أَفَرَءَيْتَ","Adakah kamu melihat"],["ٱلَّذِى","orang yang"],["تَوَلَّىٰ","berpaling"]]],"4818":["(Serta memberi sedikit) dari harta yang telah disebutkan tadi (dan tidak mau memberi lagi?) yaitu dia tidak mau memberikan sisanya. Lafal Akdaa diambil dari asal kata Al Kidyah, arti asalnya adalah tanah yang keras seperti tanah yang berbatu, sehingga penggali sumur bila sampai kepada lapisan yang berbatu itu tidak dapat melanjutkan penggaliannya.",[["وَأَعْطَىٰ","Dan memberi"],["قَلِيلًۭا","sedikit"],["وَأَكْدَىٰٓ","dan ditahan"]]],"4819":["(Apakah dia mempunyai pengetahuan tentang yang gaib sehingga dia mengetahui) sebagiannya, yaitu bahwa seseorang dapat menanggung azab akhirat yang diterima oleh orang lain? Jawabannya tentu saja tidak. Orang yang dimaksud dalam ayat ini adalah Walid ibnu Mughirah atau lainnya. Jumlah kalimat A'indahuu merupakan Maf'ul kedua dari lafal Ra-ayta, yang maknanya Akhbirnii, yakni ceritakanlah kepada-Ku.",[["أَعِندَهُۥ","Ada dengan dia"],["عِلْمُ","(yang) pengetahuan"],["ٱلْغَيْبِ","(dari) perkara ghaib"],["فَهُوَ","jadi dia"],["يَرَىٰٓ","nampak"]]],"4820":["(Ataukah) yakni sebenarnya (belum diberitakan kepadanya apa yang ada dalam lembaran-lembaran Musa) yaitu lembaran-lembaran kitab Taurat atau lembaran-lembaran kitab suci sebelumnya.",[["أَمْ","Atau"],["لَمْ","tidak"],["يُنَبَّأْ","dia dimaklumkan"],["بِمَا","dengan apa"],["فِى","(telah) masuk"],["صُحُفِ","(the) Kitab Suci"],["مُوسَىٰ","(dari) Musa"]]],"4821":["(Dan) lembaran-lembaran (Ibrahim yang selalu memenuhi janji) maksudnya Nabi Ibrahim itu selalu menepati apa yang diperintahkan kepadanya,, sebagaimana yang disebutkan dalam ayat yang lain, yaitu firman-Nya, \"Dan (ingatlah) ketika Ibrahim diuji Rabbnya dengan beberapa kalimat (perintah dan larangan), lalu Ibrahim menunaikannya dengan lengkap.\" (Q.S. Al Baqarah, 124) Kemudian pengertian yang terkandung di dalam lafal Maa pada ayat sebelumnya, dijelaskan oleh firman berikutnya,",[["وَإِبْرَٰهِيمَ","Dan Ibrahim"],["ٱلَّذِى","yang"],["وَفَّىٰٓ","dipenuhi"]]],"4822":["(\"Yaitu bahwasanya seorang yang berdosa tidak akan memikul dosa orang lain) dan seterusnya. Lafal An adalah bentuk Mukhaffafah dari Anna; artinya bahwa setiap diri itu tidak dapat menanggung dosa orang lain.",[["أَلَّا","Itu tidak"],["تَزِرُ","akan menanggung"],["وَازِرَةٌۭ","seorang pembawa beban"],["وِزْرَ","(yang) beban"],["أُخْرَىٰ","(dari) yang lain"]]],"4823":["(Dan bahwasanya) bahwasanya perkara yang sesungguhnya itu ialah (seorang manusia tiada memperoleh selain apa yang telah diusahakannya) yaitu memperoleh kebaikan dari usahanya yang baik, maka dia tidak akan memperoleh kebaikan sedikit pun dari apa yang diusahakan oleh orang lain.",[["وَأَن","Dan bahawa"],["لَّيْسَ","bukan"],["لِلْإِنسَـٰنِ","untuk lelaki"],["إِلَّا","kecuali"],["مَا","apa"],["سَعَىٰ","dia berusaha (untuk)"]]],"4824":["(Dan bahwasanya usahanya itu kelak akan diperlihatkan) kepadanya di akhirat.",[["وَأَنَّ","Dan bahawa"],["سَعْيَهُۥ","usahanya"],["سَوْفَ","akan segera"],["يُرَىٰ","dilihat"]]],"4825":["(Kemudian akan diberi balasan kepadanya dengan balasan yang paling sempurna\") pembalasan yang paling lengkap. Diambil dari asal kata, Jazaituhu Sa'yahu atau Bisa'yihi, artinya, \"Aku memberikan balasan terhadap usahanya, atau aku memberikannya balasan atas usahanya.\" Dengan kata lain lafal Jazaa ini boleh dibilang sebagai Fi'il Muta'addi atau Fi'il Lazim.",[["ثُمَّ","Kemudian"],["يُجْزَىٰهُ","dia akan diberi balasan untuknya"],["ٱلْجَزَآءَ","balasannya"],["ٱلْأَوْفَىٰ","yang paling penuh"]]],"4826":["(Dan bahwasanya) jika dibaca Anna berarti di'athafkan kepada kalimat sebelumnya, jika dibaca Inna berarti merupakan jumlah Isti-naf atau kalimat baru. Hal ini berlaku pula terhadap lafal yang sama yang jatuh sesudahnya, dengan demikian maka pengertian yang terkandung pada kalimat sesudah Anna pertama bukan termasuk ke dalam pengertian yang terkandung di dalam lembaran-lembaran Ibrahim (kepada Rabbmulah kesudahan) tempat kembali sesudah mati, lalu Dia memberikan balasan yang setimpal kepada mereka masing-masing.",[["وَأَنَّ","Dan bahawa"],["إِلَىٰ","kepada"],["رَبِّكَ","Tuhanmu"],["ٱلْمُنتَهَىٰ","(adalah) matlamat akhir"]]],"4827":["(Dan bahwasanya Dia-lah yang membuat orang tertawa) yang menjadikan gembira siapa yang dikehendaki-Nya (dan menangis) yang menjadikan sedih siapa yang dikehendaki-Nya.",[["وَأَنَّهُۥ","Dan bahawa Dia"],["هُوَ","[Dia]"],["أَضْحَكَ","membuat (seorang) ketawa"],["وَأَبْكَىٰ","dan membuat (seorang) menangis"]]],"4828":["(Dan bahwasanya Dia-lah yang mematikan dan yang menghidupkan) kembali pada hari berbangkit nanti.",[["وَأَنَّهُۥ","Dan bahawa Dia"],["هُوَ","[Dia]"],["أَمَاتَ","menyebabkan kematian"],["وَأَحْيَا","dan memberi kehidupan"]]],"4829":["(Dan bahwasanya Dia-lah yang menciptakan berpasang-pasangan) kedua jenis yang berpasangan (laki-laki dan perempuan).",[["وَأَنَّهُۥ","Dan bahawa Dia"],["خَلَقَ","dicipta"],["ٱلزَّوْجَيْنِ","pasangan itu"],["ٱلذَّكَرَ","lelaki itu"],["وَٱلْأُنثَىٰ","dan perempuan"]]],"4830":["(Dari nuthfah) yakni air mani (apabila dipancarkan) bila ditumpahkan ke dalam rahim.",[["مِن","daripada"],["نُّطْفَةٍ","titisan air mani"],["إِذَا","apabila"],["تُمْنَىٰ","ia dipancarkan"]]],"4831":["(Dan bahwasanya Dia-lah yang menetapkan kejadian) huruf Hamzah lafal An Nasy`ah boleh dibaca panjang dan boleh dibaca pendek (yang lain) kejadian yang lain untuk dibangkitkan menjadi hidup kembali, sesudah penciptaan yang pertama.",[["وَأَنَّ","Dan bahawa"],["عَلَيْهِ","atas Dia"],["ٱلنَّشْأَةَ","(ialah) melahirkan"],["ٱلْأُخْرَىٰ","yang lain"]]],"4832":["(Dan bahwasanya Dia yang memberi kekayaan) kepada manusia berupa harta benda (dan yang memberikan kecukupan) Dia memberikan harta untuk mencukupi kebutuhan orang itu.",[["وَأَنَّهُۥ","Dan bahawa Dia"],["هُوَ","[Dia]"],["أَغْنَىٰ","memperkayakan"],["وَأَقْنَىٰ","dan memadai"]]],"4833":["(Dan bahwasanya Dia-lah Rabb bintang syi'ra) nama bintang yang berada di belakang bintang Jauza; bintang itu pada zaman jahiliah disembah-sembah.",[["وَأَنَّهُۥ","Dan bahawa Dia"],["هُوَ","[Dia]"],["رَبُّ","(ialah) Tuhan"],["ٱلشِّعْرَىٰ","(daripada) Sirius"]]],"4834":["(Dan bahwasanya Dia telah membinasakan kaum 'Ad yang pertama) menurut suatu qiraat harakat Tanwinnya diidgamkan kepada huruf Lam, bila huruf Lamnya didamahkan, tanpa memakai Hamzah. Ad adalah nama suatu kaum yang dikenal dengan nama kaum 'Ad, sedangkan kaum yang lainnya adalah kaum Nabi Saleh.",[["وَأَنَّهُۥٓ","Dan bahawa Dia"],["أَهْلَكَ","musnah"],["عَادًا","Aad"],["ٱلْأُولَىٰ","yang pertama"]]],"4835":["(Dan kaum Tsamud) jika dibaca Sharf, dengan memakai Tanwin berarti nama kakek moyang, bila dibaca dengan tidak memakai Tanwin berarti nama suatu kabilah, berarti di'athafkan kepada lafal Ad. (Maka tidak seorang pun yang ditinggalkan) hidup; maksudnya tiada seorang pun di antara mereka yang dibiarkan hidup oleh-Nya.",[["وَثَمُودَا۟","Dan Thamud"],["فَمَآ","jadi tidak"],["أَبْقَىٰ","Dia selamatkan"]]],"4836":["(Dan Kaum Nuh sebelum itu) sebelum kaum Ad dan kaum Tsamud; kami binasakan mereka semuanya. (Sesungguhnya mereka adalah orang-orang yang paling lalim dan paling durhaka) yakni kaum Nabi Nuh itu jauh lebih lalim dan lebih durhaka daripada kaum 'Ad dan kaum Tsamud, karena Nabi Nuh tinggal bersama mereka dalam waktu yang lama sekali sebagaimana yang diungkapkan oleh Allah dalam firman-Nya, \"maka ia tinggal di antara mereka seribu tahun kurang lima puluh tahun.\" (Q.S. Al 'Ankabut, 14) Di samping mereka tidak mau beriman kepada Nabi Nuh, mereka juga menyakiti bahkan memukulinya.",[["وَقَوْمَ","Dan (orang-orang) itu"],["نُوحٍۢ","(daripada) Nuh"],["مِّن","sebelum"],["قَبْلُ ۖ","sebelum"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","mereka adalah"],["هُمْ","mereka adalah"],["أَظْلَمَ","lebih tidak adil"],["وَأَطْغَىٰ","dan lebih memberontak"]]],"4837":["(Dan penduduk Mu`tafikah) yaitu negeri-negeri tempat tinggal kaum Nabi Luth (yang telah dihancurkan) yaitu dijatuhkan dari atas langit sesudah diangkat dalam keadaan terbalik, lalu dijatuhkan ke bumi oleh malaikat Jibril atas perintah Allah swt.",[["وَٱلْمُؤْتَفِكَةَ","Dan kota-kota yang terbalik"],["أَهْوَىٰ","Dia menggulingkan"]]],"4838":["(Lalu Allah menimpakan atas negeri-negeri itu) batu-batu sesudah dibalikkan (azab besar yang menimpanya) di dalam ungkapan ayat azab yang dimaksud sengaja tidak disebutkan secara jelas, sebagai gambaran tentang kengeriannya yang tak terperikan, hingga tidak dapat diungkapkan oleh kata-kata. Azab ini dijelaskan pula dalam surah Hud, melalui firman-Nya, \"Kami jadikan negeri kaum Luth itu yang di atas ke bawah (Kami balikkan), dan Kami hujani mereka dengan batu dari tanah yang terbakar.\" (Q.S. Hud, 82)",[["فَغَشَّىٰهَا","Jadi meliputi mereka"],["مَا","apa"],["غَشَّىٰ","bertutup"]]],"4839":["(Maka terhadap nikmat Rabbmu yang manakah) yakni nikmat-nikmat-Nya yang menunjukkan kepada keesaan dan kekuasaan-Nya (kamu ragu-ragu) kamu meragukannya, hai manusia. Atau, kamu mendustakannya hai manusia?",[["فَبِأَىِّ","Kemudian yang mana (dari)"],["ءَالَآءِ","Nikmat"],["رَبِّكَ","Tuhanmu"],["تَتَمَارَىٰ","adakah kamu akan ragu"]]],"4840":["(Ini) Muhammad ini (adalah seorang pemberi peringatan di antara pemberi-pemberi peringatan yang terdahulu) artinya, sama dengan mereka. Maksudnya, dia adalah seorang rasul yang sama dengan rasul-rasul lain sebelumnya; ia diutus kepada kalian, sebagaimana para rasul terdahulu diutus kepada kaumnya masing-masing.",[["هَـٰذَا","Ini"],["نَذِيرٌۭ","(adalah) pemberi amaran"],["مِّنَ","daripada"],["ٱلنُّذُرِ","para pemberi amaran"],["ٱلْأُولَىٰٓ","yang dahulu"]]],"4841":["(Telah dekat terjadinya hari kiamat) kiamat telah dekat masanya.",[["أَزِفَتِ","Telah menghampiri"],["ٱلْـَٔازِفَةُ","hari yang semakin hampir"]]],"4842":["(Tiada baginya selain dari Allah) tiada seorang pun selain Allah (yang dapat menyatakan terjadinya) tiada yang mengetahui kapan terjadi dan tiada seorang pun yang dapat menyatakan kejadiannya selain Allah. Ayat ini mempunyai arti yang senada dengan ayat lainnya yaitu, firman-Nya, \"tidak ada seorang pun yang dapat menjelaskan waktu kedatangannya selain Dia.\" (Q.S. Al A'raf, 187).",[["لَيْسَ","bukan"],["لَهَا","baginya"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["كَاشِفَةٌ","sebarang penghilang"]]],"4843":["(Maka apakah terhadap pemberitaan ini) Alquran ini (kalian merasa heran?) makna yang dimaksud ialah mendustakannya.",[["أَفَمِنْ","Kemudian daripada"],["هَـٰذَا","ini"],["ٱلْحَدِيثِ","kenyataan"],["تَعْجَبُونَ","kamu tertanya-tanya"]]],"4844":["(Dan kalian menertawakan) karena memperolok-olokkannya (dan tidak menangis) sewaktu kalian mendengarkan ancaman dan peringatannya.",[["وَتَضْحَكُونَ","Dan kamu ketawa"],["وَلَا","dan jangan"],["تَبْكُونَ","menangis"]]],"4845":["(Sedangkan kalian melengahkannya) lengah dan lalai mengenai apa yang diwajibkan kepada kalian untuk mengerjakannya.",[["وَأَنتُمْ","Sedangkan kamu"],["سَـٰمِدُونَ","bergembiralah (sendiri)"]]],"4846":["(Maka bersujudlah kalian kepada Allah) Yang telah menciptakan kalian (dan sembahlah) Dia, dan janganlah kalian menyembah dan bersujud kepada berhala-berhala.",[["فَٱسْجُدُوا۟","Jadi sujud"],["لِلَّهِ","kepada Allah"],["وَٱعْبُدُوا۟ ۩","dan sembahlah (Dia)"]]],"4847":["(Telah dekat datangnya saat itu) dimaksud hari kiamat (dan telah terbelah bulan) menjadi dua bagian; yang satu di atas bukit Abu Qubais dan yang lainnya tampak di atas bukit Qaiqa'an; hal itu merupakan mukjizat bagi Nabi saw. yaitu sewaktu orang-orang Quraisy memintanya, lalu Nabi saw. bersabda, \"Saksikanlah oleh kalian.\" Demikianlah menurut keterangan hadis yang diketengahkan oleh Asy Syaikhain.",[["ٱقْتَرَبَتِ","Telah datang dekat"],["ٱلسَّاعَةُ","Jam itu"],["وَٱنشَقَّ","dan telah berpecah"],["ٱلْقَمَرُ","bulan"]]],"4848":["(Dan jika mereka melihat) yaitu orang-orang kafir Quraisy (sesuatu tanda) suatu mukjizat yang timbul dari Nabi saw. (mereka berpaling dan berkata,) \"Ini adalah (sihir yang kuat) sihir yang paling kuat\", berasal dari kata Al Mirrah; artinya kuat atau terus menerus.",[["وَإِن","Dan jika"],["يَرَوْا۟","mereka lihat"],["ءَايَةًۭ","sebuah Tanda"],["يُعْرِضُوا۟","mereka berpaling"],["وَيَقُولُوا۟","dan katakan"],["سِحْرٌۭ","Sihir"],["مُّسْتَمِرٌّۭ","berterusan"]]],"4849":["(Dan mereka mendustakan) Nabi saw. (dan mengikuti hawa nafsu mereka) dalam perkara yang batil (sedangkan tiap-tiap urusan) atau perkara yang baik dan perkara yang buruk (telah ada ketetapannya) bagi pemiliknya masing-masing, yaitu adakalanya masuk ke surga atau ke neraka.",[["وَكَذَّبُوا۟","Dan mereka menafikan"],["وَٱتَّبَعُوٓا۟","dan diikuti"],["أَهْوَآءَهُمْ ۚ","keinginan mereka"],["وَكُلُّ","tetapi (untuk) setiap"],["أَمْرٍۢ","perkara"],["مُّسْتَقِرٌّۭ","(akan menjadi) penyelesaian"]]],"4850":["(Dan sesungguhnya telah datang kepada mereka beberapa kisah) berita-berita tentang dibinasakan-Nya umat-umat yang telah mendustakan rasul-rasul mereka (yang di dalamnya terdapat cegahan) bagi mereka untuk melakukan hal yang serupa. Lafal Muzdajar adalah Mashdar atau Isim yang menunjukkan arti tempat, sedangkan huruf Dal-nya merupakan pergantian dari Ta Wazan Ifta'ala. Bila dikatakan Izdajartuhu atau Zajartuhu maka artinya, aku mencegahnya dengan keras. Huruf Maa adalah Maushulah atau Maa Maushufah.",[["وَلَقَدْ","Dan sungguh"],["جَآءَهُم","telah datang kepada mereka"],["مِّنَ","daripada"],["ٱلْأَنۢبَآءِ","maklumat tersebut"],["مَا","di mana"],["فِيهِ","di mana"],["مُزْدَجَرٌ","(adalah) pencegahan"]]],"4851":["(Itulah suatu hikmah) merupakan Khabar dari Mubtada yang tidak disebutkan, atau menjadi Badal dari lafal Maa, atau dari lafal Muzdajir (yang sempurna) maksudnya, hikmah yang lengkap (tetapi tiada berguna) tidak ada gunanya bagi mereka (peringatan-peringatan itu) lafal An Nudzur adalah bentuk jamak dari lafal Nadziirun yang bermakna Mundzirun, yakni hal-hal yang dijadikan peringatan buat mereka. Lafal Maa boleh dikatakan sebagai huruf Nafi atau Istifham Inkari; jika dianggap sebagai Istifham Inkari berarti kedudukannya sebagai Maf'ul Muqaddam.",[["حِكْمَةٌۢ","kebijaksanaan"],["بَـٰلِغَةٌۭ ۖ","sempurna"],["فَمَا","tetapi tidak"],["تُغْنِ","akan mendapat manfaat"],["ٱلنُّذُرُ","amaran"]]],"4852":["(Maka berpalinglah kamu dari mereka) menjadi pelengkap atau kesimpulan dari pembahasan sebelumnya (pada hari ketika penyeru memanggil) yaitu malaikat Israfil. Yang menashabkan lafal Yauma adalah lafal Yakhrujuuna yang disebutkan dalam ayat berikutnya, artinya, sesudah mereka keluar dari kuburnya masing-masing yaitu, ketika sang penyeru memanggil mereka (kepada sesuatu yang tidak menyenangkan) dapat dibaca Nukur atau Nukr, artinya, hal yang paling tidak disukai oleh jiwa manusia yaitu, hari penghisaban amal perbuatan.",[["فَتَوَلَّ","Jadi berpalinglah"],["عَنْهُمْ ۘ","daripada mereka"],["يَوْمَ","(The) Hari"],["يَدْعُ","akan memanggil"],["ٱلدَّاعِ","pemanggil"],["إِلَىٰ","kepada"],["شَىْءٍۢ","sesuatu perkara"],["نُّكُرٍ","dahsyat"]]],"4853":["(Sambil menundukkan) keadaan mereka pada saat itu hina Menurut suatu qiraat dibaca Khaasyi'an (pandangan-pandangan mereka) lafal Khusysya'an menjadi Hal atau kata keterangan keadaan dari Fa'il (mereka keluar) yakni manusia semuanya (dari kuburan) dari tempat-tempat mereka dikuburkan (seakan-akan mereka belalang yang beterbangan) mereka tidak mengetahui hendak ke manakah tujuan mereka, karena tercekam oleh rasa takut dan bimbang yang amat sangat. Jumlah kalimat Ka annahum dan seterusnya menjadi Hal dari Fa'il yang terkandung di dalam lafal Yakhrujuna, demikian pula firman selanjutnya, yaitu,",[["خُشَّعًا","(Akan) direndahkan"],["أَبْصَـٰرُهُمْ","mata mereka"],["يَخْرُجُونَ","mereka akan keluar"],["مِنَ","daripada"],["ٱلْأَجْدَاثِ","kubur"],["كَأَنَّهُمْ","seolah-olah mereka (adalah)"],["جَرَادٌۭ","belalang"],["مُّنتَشِرٌۭ","merebak"]]],"4854":["(Mereka datang dengan cepat) seraya menjulurkan leher-leher mereka (kepada penyeru itu. Orang-orang kafir berkata) orang-orang kafir di antara mereka mengatakan, (\"Ini adalah hari yang berat\") atau sulit bagi orang-orang kafir, sebagaimana yang telah dijelaskan dalam surah Al Muddatstsir melalui firman-Nya, \"Hari yang sulit bagi orang-orang kafir.\" (Q.S. Al-Muddatstsir 9-10)",[["مُّهْطِعِينَ","Berlumba ke hadapan"],["إِلَى","ke arah"],["ٱلدَّاعِ ۖ","pemanggil"],["يَقُولُ","Akan berkata"],["ٱلْكَـٰفِرُونَ","orang kafir"],["هَـٰذَا","Ini"],["يَوْمٌ","(adalah) sehari"],["عَسِرٌۭ","susah"]]],"4855":["(Sebelum mereka telah mendustakan -pula -) yakni sebelum orang-orang Quraisy (kaum Nuh) dita`nits kannya lafal Kadzdzabat karena memandang segi makna yang terkandung dalam lafal Qaumun (maka mereka mendustakan hamba Kami) yakni Nabi Nuh (dan mereka mengatakan, \"Dia seorang gila dan dia sudah pernah diberi ancaman\") pernah diperingatkan oleh mereka dengan caci-maki dan lain sebagainya.",[["۞ كَذَّبَتْ","dinafikan"],["قَبْلَهُمْ","sebelum mereka"],["قَوْمُ","kaum"],["نُوحٍۢ","(daripada) Nuh"],["فَكَذَّبُوا۟","dan mereka menafikan"],["عَبْدَنَا","hamba kita"],["وَقَالُوا۟","dan berkata"],["مَجْنُونٌۭ","Orang gila"],["وَٱزْدُجِرَ","dan dia telah ditolak"]]],"4856":["(Maka dia mengadu kepada Rabbnya, \"Bahwasanya aku ini) dibaca Annii artinya, bahwa aku ini (adalah orang yang dikalahkan, oleh karena itu menangkanlah aku\")",[["فَدَعَا","Jadi dia menelefon"],["رَبَّهُۥٓ","Tuhannya"],["أَنِّى","aku"],["مَغْلُوبٌۭ","satu dikuasai"],["فَٱنتَصِرْ","jadi tolong"]]],"4857":["(Maka Kami bukakan) dapat dibaca Fafatahnaa atau Fafattahnaa (pintu-pintu langit dengan menurunkan air yang tercurah) air yang ditumpahkan dari langit dengan sangat derasnya.",[["فَفَتَحْنَآ","Jadi Kami buka"],["أَبْوَٰبَ","(the) pintu gerbang"],["ٱلسَّمَآءِ","(dari) syurga"],["بِمَآءٍۢ","dengan air"],["مُّنْهَمِرٍۢ","mencurah-curah"]]],"4858":["(Dan Kami jadikan bumi memancarkan mata air-mata air) yang menyumber dengan derasnya (maka bertemulah air-air itu) yaitu air yang ditumpahkan dari langit dan air yang disemburkan dari bumi (untuk suatu urusan) berkedudukan menjadi Hal (yang sungguh telah ditetapkan) yang telah dipastikan di zaman Azali, yaitu bahwa mereka dibinasakan dengan ditenggelamkan.",[["وَفَجَّرْنَا","Dan Kami jadikan pecah"],["ٱلْأَرْضَ","bumi"],["عُيُونًۭا","(dengan) mata air"],["فَٱلْتَقَى","jadi bertemu"],["ٱلْمَآءُ","air (s)"],["عَلَىٰٓ","bagi"],["أَمْرٍۢ","sesuatu perkara"],["قَدْ","sudah"],["قُدِرَ","ditakdirkan"]]],"4859":["(Dan Kami angkut dia) yakni Nabi Nuh (ke atas) bahtera (yang terbuat dari papan dan paku) lafal Dusur artinya benda-benda yang dipakai untuk menyambung kayu-kayu, baik berupa paku atau benda-benda lainnya, bentuk tunggalnya adalah Disaarun yang wazannya sama dengan lafal Kitaabun",[["وَحَمَلْنَـٰهُ","Dan Kami angkat dia"],["عَلَىٰ","pada"],["ذَاتِ","(bahtera) diperbuat daripada papan"],["أَلْوَٰحٍۢ","(bahtera) diperbuat daripada papan"],["وَدُسُرٍۢ","dan kuku"]]],"4860":["(Yang berlayar dengan pemeliharaan Kami) atau dalam pengawasan Kami (sebagai balasan) dinashabkan oleh Fi'il yang diperkirakan keberadaannya, yakni mereka ditenggelamkan sebagai pertanda kemenangan (bagi orang yang diingkari) yaitu bagi Nabi Nuh a.s. Dan menurut suatu qiraat lafal Kufira dibaca Kafar, artinya, mereka ditenggelamkan sebagai hukuman bagi mereka yang kafir.",[["تَجْرِى","belayar"],["بِأَعْيُنِنَا","depan mata Kami"],["جَزَآءًۭ","ganjaran"],["لِّمَن","untuk (dia) yang"],["كَانَ","adalah"],["كُفِرَ","dinafikan"]]],"4861":["(Dan sesungguhnya telah Kami tinggalkan) telah Kami biarkan perbuatan Kami itu (sebagai tanda) bagi orang yang mau mengambilnya sebagai pelajaran buat dirinya. Makna yang dimaksud ialah, berita mengenai banjir besar ini telah tersiar dan tetap lestari ketenarannya (maka adakah orang yang mau mengambil pelajaran?) untuk menasihati dirinya. Asal lafal Muddakir adalah Mudztakir, lalu huruf Ta diganti menjadi Dal, demikian pula huruf Dzal diganti menjadi Dal, lalu keduanya diidgamkan menjadi satu sehingga jadilah Muddakir.",[["وَلَقَد","Dan sungguh"],["تَّرَكْنَـٰهَآ","Kami meninggalkannya"],["ءَايَةًۭ","(sebagai) Tanda"],["فَهَلْ","begitu juga (ada)"],["مِن","sebarang"],["مُّدَّكِرٍۢ","yang akan menerima teguran"]]],"4862":["(Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku) peringatan-Ku, Istifham atau kata tanya di sini mengandung makna Taqrir. Lafal Kaifa adalah Khabar dari lafal Kaana, menunjukkan makna pertanyaan tentang keadaan. Pengertiannya ialah menganggap orang-orang yang diajak berbicara telah mengakui terjadinya. azab Allah swt. yang telah menimpa orang-orang yang mendustakan Nabi Nuh.",[["فَكَيْفَ","Jadi bagaimana"],["كَانَ","adalah"],["عَذَابِى","hukuman aku"],["وَنُذُرِ","dan amaran-Ku"]]],"4863":["(Dan sesungguhnya telah Kami mudahkan Alquran untuk pelajaran) Kami telah memudahkannya untuk dihafal dan Kami telah mempersiapkannya untuk mudah diingat (maka adakah orang yang mengambil pelajaran?) yang mau mengambilnya sebagai pelajaran dan menghafalnya. Istifham di sini mengandung makna perintah yakni, hafalkanlah Alquran itu oleh kalian dan ambillah sebagai nasihat buat diri kalian. Sebab tidak ada orang yang lebih hafal tentang Alquran selain daripada orang yang mengambilnya sebagai nasihat buat dirinya.",[["وَلَقَدْ","Dan sungguh"],["يَسَّرْنَا","Kami telah memudahkan"],["ٱلْقُرْءَانَ","al-Quran"],["لِلذِّكْرِ","untuk ingatan"],["فَهَلْ","begitu juga (ada)"],["مِن","sebarang"],["مُّدَّكِرٍۢ","yang akan menerima teguran"]]],"4864":["(Kaum Ad pun telah mendustakan) nabi mereka yaitu Nabi Hud, karena itu mereka diazab. (Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku) peringatan-Ku kepada mereka, bahwa mereka akan Kami azab sebelum azab itu turun menimpa mereka. Kemudian dijelaskan oleh firman berikutnya.",[["كَذَّبَتْ","dinafikan"],["عَادٌۭ","Aad"],["فَكَيْفَ","jadi bagaimana"],["كَانَ","adalah"],["عَذَابِى","hukuman aku"],["وَنُذُرِ","dan amaran-Ku"]]],"4865":["(Sesungguhnya Kami telah menghembuskan kepada mereka angin yang sangat kencang) sangat keras suaranya dan kuat sekali (pada hari nahas) atau pada hari yang sial (yang terus-menerus) yakin kesialannya terus-menerus. Atau sangat kuat sialnya, hal itu terjadi pada hari Rabu di penghujung bulan.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَا","[Kami] hantar"],["عَلَيْهِمْ","ke atas mereka"],["رِيحًۭا","angin"],["صَرْصَرًۭا","geram"],["فِى","pada"],["يَوْمِ","sehari"],["نَحْسٍۢ","(dari) kemalangan"],["مُّسْتَمِرٍّۢ","berterusan"]]],"4866":["(Yang mencabut manusia) yang menghempaskan mereka dari tempat perlindungannya di bawah tanah, kemudian angin itu menjatuhkannya ke kepala mereka sehingga matilah mereka semua dan terpisahlah kepala dari tubuh mereka (seakan-akan mereka) yakni keadaan mereka pada waktu itu sebagaimana yang telah disebutkan tadi (pokok-pokok) atau batang-batang (kurma yang tumbang) maksudnya, keadaan mereka ketika itu bagaikan pokok-pokok kurma yang tumbang ke bumi. Mereka diserupakan dengan pokok kurma karena keadaan tubuh mereka yang tinggi-tinggi. Lafal Munqa'ir disebutkan ayat ini dalam bentuk Mudzakkar, sedangkan di dalam surah Al Haaqqah kata sifatnya disebutkan dalam bentuk Ta`nits yaitu, di dalam firman-Nya, \"batang-batang pohon kurma yang telah kosong (lapuk).\" (Q.S. Al-Haaqqah, 7) Demikian itu karena demi memelihara kesamaan bunyi pada akhir ayat pada kedua tempat tersebut.",[["تَنزِعُ","Mencabut"],["ٱلنَّاسَ","lelaki"],["كَأَنَّهُمْ","seolah-olah mereka (adalah)"],["أَعْجَازُ","batang"],["نَخْلٍۢ","(daripada) kurma"],["مُّنقَعِرٍۢ","tercabut"]]],"4867":["(Maka betapa dahsyatnya azab-Ku dan ancaman-ancaman-Ku)",[["فَكَيْفَ","Jadi bagaimana"],["كَانَ","adalah"],["عَذَابِى","hukuman aku"],["وَنُذُرِ","dan amaran-Ku"]]],"4868":["(Dan sesungguhnya telah kami mudahkan Alquran untuk pelajaran, maka adakah orang yang mengambil pelajaran?)",[["وَلَقَدْ","Dan sungguh"],["يَسَّرْنَا","Kami telah memudahkan"],["ٱلْقُرْءَانَ","al-Quran"],["لِلذِّكْرِ","untuk ingatan"],["فَهَلْ","begitu juga (ada)"],["مِن","sebarang"],["مُّدَّكِرٍۢ","yang akan menerima teguran"]]],"4869":["(Kaum Tsamud pun telah mendustakan ancaman-ancaman itu) lafal An Nudzur adalah bentuk jamak dari lafal Nadziirun yang bermakna Mundzirun, yaitu perkara-perkara yang dijadikan peringatan oleh nabi mereka (Nabi Saleh) jika mereka tidak mau beriman dan tidak mau mengikutinya.",[["كَذَّبَتْ","dinafikan"],["ثَمُودُ","kaum Thamud"],["بِٱلنُّذُرِ","amaran"]]],"4870":["(Maka mereka berkata, \"Apakah kepada manusia) lafal Basyaran dinashabkan karena Isytighal (yakni seseorang di antara kami) kedua lafal ini menjadi sifat bagi lafal Basyaran (kami harus mengikutinya) merupakan penafsir dari Fi'il yang menashabkan lafal Basyaran. Istifham atau kata tanya di sini mengandung makna Nafi atau negatif. Maksudnya, bagaimana kami harus mengikutinya sedangkan kami adalah golongan mayoritas dan dia adalah seseorang di antara kami, lagi dia bukanlah seorang raja. Maksud mereka ialah bahwa mereka tidak mau mengikutinya. (Sesungguhnya kami kalau demikian) jika kami mengikutinya (benar-benar berada dalam kesesatan) atau menyimpang dari kebenaran (dan gila) atau tidak berakal waras.",[["فَقَالُوٓا۟","Dan berkata"],["أَبَشَرًۭا","Adakah (ia) seorang manusia"],["مِّنَّا","antara kita"],["وَٰحِدًۭا","satu"],["نَّتَّبِعُهُۥٓ","(bahawa) kita hendaklah mengikutnya"],["إِنَّآ","Sesungguhnya kami"],["إِذًۭا","kemudian"],["لَّفِى","(akan) pasti masuk"],["ضَلَـٰلٍۢ","ralat"],["وَسُعُرٍ","dan kegilaan"]]],"4871":["(Apakah diturunkan) boleh dibaca Tahqiq dan boleh pula dibaca Tas-hil (wahyu itu) peringatan itu (kepadanya di antara kita) maksudnya, tidak pantas wahyu diturunkan kepadanya. (Sebenarnya dia adalah seorang yang amat pendusta) di dalam pengakuannya itu yang menyatakan bahwa hal tersebut telah diwahyukan kepadanya (lagi sombong\") congkak dan takabur. Lalu Allah berfirman,",[["أَءُلْقِىَ","Telah dihantar"],["ٱلذِّكْرُ","Peringatan itu"],["عَلَيْهِ","kepadanya"],["مِنۢ","daripada"],["بَيْنِنَا","antara kita"],["بَلْ","Bahkan"],["هُوَ","dia"],["كَذَّابٌ","(adalah) pembohong"],["أَشِرٌۭ","kurang ajar"]]],"4872":["(\"Kelak mereka akan mengetahui) di akhirat nanti (siapakah yang sebenarnya amat pendusta lagi sombong\") dia ataukah mereka? Kelak Allah pasti akan mengazab mereka yang telah mendustakan nabinya yakni, Nabi Saleh.",[["سَيَعْلَمُونَ","Mereka akan tahu"],["غَدًۭا","esok"],["مَّنِ","yang"],["ٱلْكَذَّابُ","(adalah) pembohong"],["ٱلْأَشِرُ","yang kurang ajar"]]],"4873":["(Sesungguhnya Kami akan mengirimkan unta betina) yaitu mengeluarkan unta dari batu besar yang terdapat di lembah tempat mereka sebagaimana yang mereka minta (sebagai cobaan) ujian (bagi mereka) Kami lakukan hal itu guna mencoba mereka (maka tunggulah mereka) hai Saleh apa yang akan mereka kerjakan dan apa yang akan ditimpakan kepada mereka (dan bersabarlah) atas perlakuan mereka yang menyakitkan itu terhadap dirimu. Lafal Ishthabir pada asalnya adalah Ishtabir, kemudian huruf Ta diganti menjadi huruf Tha sehingga jadilah Ishthabir, maknanya bersabarlah kamu.",[["إِنَّا","Sesungguhnya Kami"],["مُرْسِلُوا۟","(sedang) menghantar"],["ٱلنَّاقَةِ","unta betina itu"],["فِتْنَةًۭ","(sebagai) percubaan"],["لَّهُمْ","bagi mereka"],["فَٱرْتَقِبْهُمْ","jadi perhatikan mereka"],["وَٱصْطَبِرْ","dan bersabarlah"]]],"4874":["(Dan beritakanlah kepada mereka bahwa sesungguhnya air itu terbagi) dibagi-bagi (antara mereka) dengan unta betina itu; yakni sehari buat mereka dan hari yang lainnya buat unta betina, demikianlah seterusnya (tiap-tiap minum) bagian air (dihadiri) oleh yang punya giliran, yakni kaum Nabi Saleh dan unta betina. Akhirnya lama kelamaan mereka merasa bosan dengan adanya pembagian ini, lalu mereka bersepakat untuk membunuh unta betina itu.",[["وَنَبِّئْهُمْ","Dan maklumkan kepada mereka"],["أَنَّ","bahawa"],["ٱلْمَآءَ","air itu"],["قِسْمَةٌۢ","(adalah) untuk dikongsi"],["بَيْنَهُمْ ۖ","antara mereka"],["كُلُّ","setiap satu"],["شِرْبٍۢ","minum"],["مُّحْتَضَرٌۭ","dihadiri"]]],"4875":["(Maka mereka memanggil kawannya) yaitu seorang yang gagah perkasa untuk membunuh unta betina itu (lalu kawannya itu menangkap) unta itu seraya menghunus pedangnya (dan menyembelihnya) menyembelih unta betina itu dengan pedangnya dan membunuhnya sesuai dengan apa yang diinginkan oleh mereka.",[["فَنَادَوْا۟","Tetapi mereka memanggil"],["صَاحِبَهُمْ","teman mereka"],["فَتَعَاطَىٰ","dan dia mengambil"],["فَعَقَرَ","dan hamstrung"]]],"4876":["(Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku) yakni peringatan-Ku terhadap mereka sebelum azab diturunkan kepada mereka. Lalu Allah menjelaskan hal ini melalui firman selanjutnya,",[["فَكَيْفَ","Jadi bagaimana"],["كَانَ","adalah"],["عَذَابِى","hukuman aku"],["وَنُذُرِ","dan amaran-Ku"]]],"4877":["(\"Sesungguhnya Kami menimpakan atas mereka satu suara yang keras mengguntur, maka jadilah mereka seperti kayu-kayu kering yang dijadikan sebagai kandang kambing\") Al Muhtazhar artinya pohon dan duri-duri yang kering kemudian dijadikan sebagai kandang kambing untuk menjaga kambing-kambing dari sergapan binatang buas seperti serigala dan binatang pemangsa lainnya. Dan kayu-kayu atau duri-duri kering yang terjatuh dari kandang tersebut lalu diinjak-injak oleh kambing dinamakan Al Hasyiim.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَا","[Kami] hantar"],["عَلَيْهِمْ","ke atas mereka"],["صَيْحَةًۭ","letupan gemuruh"],["وَٰحِدَةًۭ","bujang"],["فَكَانُوا۟","dan mereka menjadi"],["كَهَشِيمِ","seperti serpihan ranting kering"],["ٱلْمُحْتَظِرِ","(digunakan oleh) pembina pagar"]]],"4878":["(Dan sesungguhnya telah Kami mudahkan Alquran untuk pelajaran, maka adakah orang yang mau mengambil pelajaran?)",[["وَلَقَدْ","Dan sungguh"],["يَسَّرْنَا","Kami telah memudahkan"],["ٱلْقُرْءَانَ","al-Quran"],["لِلذِّكْرِ","untuk ingatan"],["فَهَلْ","begitu juga (ada)"],["مِن","sebarang"],["مُّدَّكِرٍۢ","yang akan menerima teguran"]]],"4879":["(Kaum Luth pun telah mendustakan ancaman-ancaman itu) mendustakan hal-hal yang diancamkan kepada mereka melalui lisan Nabi Luth.",[["كَذَّبَتْ","dinafikan"],["قَوْمُ","kaum"],["لُوطٍۭ","(dari) Lut"],["بِٱلنُّذُرِ","amaran"]]],"4880":["(Sesungguhnya Kami telah mengembuskan kepada mereka angin yang membawa terbang batu-batu) yakni angin yang melempari mereka dengan batu-batu yang diterbangkannya. Al Hashbaa adalah batu-batu kecil yang besarnya lebih kecil dari genggaman tangan; akhirnya binasalah mereka karenanya (kecuali keluarga Luth) mereka adalah Nabi Luth dan kedua orang putrinya. (Mereka Kami selamatkan di waktu sebelum fajar menyingsing) berasal dari lafal As-haar artinya, waktu menjelang subuh dari hari yang tidak ditentukan. Dan seandainya hari yang dimaksud adalah hari yang ditentukan, niscaya ungkapannya tidak memakai harakat Tanwin karena termasuk Isim yang Ma'rifat dan dima'dul dari lafal As Sahar. Karena, bila dimaksud sebagai hari yang ditentukan pasti memakai Alif dan Lam. Apakah batu kerikil itu dihembuskan kepada keluarga Nabi Luth atau tidak? Sehubungan dengan hal ini ada dua pendapat. Menurut pendapat pertama yakni dihembuskan juga, berarti Istisna di sini bersifat Muttashil. Menurut pendapat kedua yakni, tidak dihembuskan berarti Istitsnanya bersifat Munqathi'. Akan tetapi pada akhirnya keluarga Nabi Luth diselamatkan dari azab itu.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَا","[Kami] hantar"],["عَلَيْهِمْ","ke atas mereka"],["حَاصِبًا","ribut batu"],["إِلَّآ","kecuali"],["ءَالَ","(keluarga)."],["لُوطٍۢ ۖ","(dari) Lut"],["نَّجَّيْنَـٰهُم","Kami menyelamatkan mereka"],["بِسَحَرٍۢ","menjelang subuh"]]],"4881":["(sebagai nikmat) menjadi mashdar, artinya sebagai pemberian nikmat. (dari sisi Kami. Demikianlah) sebagaimana pembalasan tersebut (Kami memberi balasan kepada orang-orang yang bersyukur) terhadap nikmat-nikmat Kami; dia adalah orang mukmin atau orang yang beriman kepada Allah dan Rasul-Nya serta menaati keduanya.",[["نِّعْمَةًۭ","(Sebagai) nikmat"],["مِّنْ","daripada"],["عِندِنَا ۚ","Kami"],["كَذَٰلِكَ","Demikianlah"],["نَجْزِى","Kami memberi ganjaran"],["مَن","(satu) siapa"],["شَكَرَ","(adalah) bersyukur"]]],"4882":["(Dan sesungguhnya dia telah memperingatkan kepada mereka) yaitu Nabi Luth telah memberi peringatan kepada mereka (akan azab Kami) akan pembalasan Kami kepada mereka melalui azab-Nya (maka mereka mendustakan) mereka membantah dan mendustakan (ancaman-ancaman itu) ancaman-ancaman Nabi Luth.",[["وَلَقَدْ","Dan sungguh"],["أَنذَرَهُم","dia memberi amaran kepada mereka"],["بَطْشَتَنَا","(dari) rampasan kami"],["فَتَمَارَوْا۟","tetapi mereka mempertikaikan"],["بِٱلنُّذُرِ","amaran"]]],"4883":["(Dan sesungguhnya mereka telah membujuknya agar menyerahkan tamunya) mereka membujuknya supaya dia membiarkan mereka dengan orang-orang yang datang kepadanya sebagai tamu. Mereka bermaksud akan berbuat homosex dengan para tamunya itu, padahal para tamunya itu adalah malaikat-malaikat yang menjelma menjadi manusia (lalu Kami butakan mata mereka) Kami jadikan buta mata mereka dan Kami jadikan mata mereka tertutup rapat atau rata, sama rata dengan bagian muka yang lainnya. Yaitu, setelah malaikat Jibril menampar mereka dengan sayapnya (maka rasakanlah) maksudnya, Kami berkata kepada mereka, \"Rasakanlah oleh kalian (azab-Ku dan ancaman-ancaman-Ku) ini\". Yakni, ancaman dan peringatan-Ku ini; makna yang dimaksud adalah buah dan akibat daripada ancaman-Ku.",[["وَلَقَدْ","Dan sungguh"],["رَٰوَدُوهُ","mereka menuntut daripadanya"],["عَن","mereka menuntut daripadanya"],["ضَيْفِهِۦ","tetamunya"],["فَطَمَسْنَآ","jadi Kami buta"],["أَعْيُنَهُمْ","mata mereka"],["فَذُوقُوا۟","Jadi rasa"],["عَذَابِى","hukuman aku"],["وَنُذُرِ","dan amaran-Ku"]]],"4884":["(Dan sesungguhnya pada esok harinya mereka ditimpa) yaitu, di waktu subuh dari hari yang tidak ditentukan itu (azab yang kekal) azab yang terus-menerus hingga sampai kepada saatnya azab akhirat.",[["وَلَقَدْ","Dan sungguh"],["صَبَّحَهُم","menangkap mereka pada waktu pagi"],["بُكْرَةً","awal"],["عَذَابٌۭ","azab"],["مُّسْتَقِرٌّۭ","berkekalan"]]],"4885":["(Maka rasakanlah azab-Ku dan ancaman-ancaman-Ku)",[["فَذُوقُوا۟","Jadi rasa"],["عَذَابِى","hukuman aku"],["وَنُذُرِ","dan amaran-Ku"]]],"4886":["(Dan sesungguhnya telah Kami mudahkan Alquran untuk pelajaran, maka sudah adakah orang yang mengambil pelajaran?).",[["وَلَقَدْ","Dan sungguh"],["يَسَّرْنَا","Kami telah memudahkan"],["ٱلْقُرْءَانَ","al-Quran"],["لِلذِّكْرِ","untuk ingatan"],["فَهَلْ","begitu juga (ada)"],["مِن","sebarang"],["مُّدَّكِرٍۢ","yang akan menerima teguran"]]],"4887":["(Dan sesungguhnya telah datang kepada kaum Firaun) kepada Firaun dan kaumnya (ancaman-ancaman itu) ancaman-Ku melalui lisan Nabi Musa dan Nabi Harun, tetapi mereka masih tetap tidak mau beriman. Bahkan,",[["وَلَقَدْ","Dan sungguh"],["جَآءَ","datang"],["ءَالَ","(kepada) orang ramai"],["فِرْعَوْنَ","(daripada) Firaun"],["ٱلنُّذُرُ","amaran"]]],"4888":["(mereka mendustakan ayat-ayat Kami kesemuanya) yakni sembilan ayat yang diberikan kepada Nabi Musa (lalu Kami azab mereka) yakni, Kami turunkan azab kepada mereka (sebagai azab dari Yang Maha Perkasa) Yang Maha Kuat (lagi Maha Kuasa) tiada sesuatu pun yang dapat melemahkan dan menghalang-halangi-Nya.",[["كَذَّبُوا۟","Mereka menafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["كُلِّهَا","kesemuanya"],["فَأَخَذْنَـٰهُمْ","maka Kami siksa mereka"],["أَخْذَ","(dengan) sawan"],["عَزِيزٍۢ","(dari) Yang Maha Perkasa"],["مُّقْتَدِرٍ","(yang) Yang Maha Kuasa"]]],"4889":["(Apakah orang-orang kafir kalian) hai orang-orang Quraisy (lebih baik daripada mereka itu) yang telah disebutkan yaitu, mulai dari kaum Nabi Nuh hingga sampai kepada Firaun dan kaumnya yang tidak mendapatkan ampunan (atau apakah kalian telah mempunyai) hai orang-orang kafir Quraisy (jaminan kebebasan) dari azab (dalam kitab-kitab) yang terdahulu. Istifham yang terdapat pada dua tempat ini mengandung makna Nafi artinya, kenyataannya tidaklah demikian.",[["أَكُفَّارُكُمْ","Adakah kamu kafir"],["خَيْرٌۭ","lebih baik"],["مِّنْ","daripada"],["أُو۟لَـٰٓئِكُمْ","mereka"],["أَمْ","atau"],["لَكُم","bagi kamu"],["بَرَآءَةٌۭ","(adalah) pengecualian"],["فِى","dalam"],["ٱلزُّبُرِ","Kitab Suci"]]],"4890":["(Atau apakah mereka mengatakan) yakni orang-orang kafir Quraisy, (\"Kami adalah suatu golongan yang bersatu) orang-orang yang bersatu dalam satu golongan (yang pasti menang\") atas Muhammad. Sewaktu Abu Jahal mengatakan dalam perang Badar, bahwa sesungguhnya kami adalah golongan yang bersatu yang pasti menang. Maka turunlah firman-Nya,",[["أَمْ","Atau"],["يَقُولُونَ","(lakukan) mereka berkata"],["نَحْنُ","Kami"],["جَمِيعٌۭ","(adalah) perhimpunan"],["مُّنتَصِرٌۭ","tolong menolong (antara satu sama lain)"]]],"4891":["(\"Golongan Itu pasti akan dikalahkan dan mereka akan mundur ke belakang\") akhirnya mereka dikalahkan oleh Nabi Muhammad saw. dalam perang Badar, dan Nabi Muhammad saw. mendapat kemenangan yang gemilang atas mereka.",[["سَيُهْزَمُ","Tidak lama lagi akan dikalahkan"],["ٱلْجَمْعُ","perhimpunan (mereka)."],["وَيُوَلُّونَ","dan mereka akan berpaling"],["ٱلدُّبُرَ","(mereka) belakang"]]],"4892":["(Sebenarnya hari kiamat itulah hari yang dijanjikan kepada mereka) yaitu azab akan ditimpakan kepada mereka (dan kiamat itu) azab hari kiamat itu (lebih dahsyat) lebih besar bencananya (lagi lebih pahit) jauh lebih pahit daripada azab di dunia.",[["بَلِ","Bahkan"],["ٱلسَّاعَةُ","Jam itu"],["مَوْعِدُهُمْ","(adalah) masa yang mereka janjikan"],["وَٱلسَّاعَةُ","dan hari kiamat"],["أَدْهَىٰ","(akan) lebih pedih"],["وَأَمَرُّ","dan lebih pahit"]]],"4893":["(Sesungguhnya orang-orang yang berdosa berada dalam kesesatan) dalam kebinasaan, mereka akan terbunuh di dunia (dan dalam neraka) neraka yang besar nyalanya. Maksudnya, kelak di akhirat mereka akan dimasukkan ke dalam neraka yang apinya menyala-nyala.",[["إِنَّ","Sesungguhnya"],["ٱلْمُجْرِمِينَ","penjenayah"],["فِى","(ada) dalam"],["ضَلَـٰلٍۢ","satu kesilapan"],["وَسُعُرٍۢ","dan kegilaan"]]],"4894":["(Pada hari mereka diseret ke neraka atas muka mereka) di akhirat kelak, lalu dikatakan kepada mereka (\"Rasakanlah sentuhan api neraka\") rasakanlah panasnya api neraka Jahanam ini oleh kalian.",[["يَوْمَ","(The) Hari"],["يُسْحَبُونَ","mereka akan diseret"],["فِى","ke dalam"],["ٱلنَّارِ","neraka"],["عَلَىٰ","pada"],["وُجُوهِهِمْ","muka mereka"],["ذُوقُوا۟","rasa"],["مَسَّ","(the) sentuhan"],["سَقَرَ","(dari) Neraka"]]],"4895":["(Sesungguhnya segala sesuatu itu Kami) dinashabkan oleh Fi'il yang terdapat pada firman selanjutnya yang berfungsi menafsirkannya (ciptakan menurut ukuran) masing-masing. Menurut suatu qiraat lafal Kulla dibaca KuIlu dan dianggap sebagai Mubtada, sedangkan Khabarnya adalah lafal Khalaqnaahu.",[["إِنَّا","Sesungguhnya, [Kami]"],["كُلَّ","setiap"],["شَىْءٍ","perkara"],["خَلَقْنَـٰهُ","Kami menciptanya"],["بِقَدَرٍۢ","dengan ukuran"]]],"4896":["(Dan tiada lain perintah Kami) terhadap sesuatu yang Kami kehendaki ada (hanyalah) sekali (satu firman seperti kejapan mata) dalam hal kecepatannya, yaitu melalui firman-Nya 'Kun' yakni adalah kamu, maka sesuatu yang dikehendaki itu langsung ada dengan seketika; pengertian ini diungkapkan pula oleh firman lainnya, yaitu, \"Sesungguhnya keadaan-Nya apabila Dia menghendaki sesuatu hanyalah berkata kepadanya, 'Jadilah', maka terjadilah ia.\" (Q.S. Yaasin, 82)",[["وَمَآ","Dan tidak"],["أَمْرُنَآ","(ialah) Perintah Kami"],["إِلَّا","tetapi"],["وَٰحِدَةٌۭ","satu"],["كَلَمْحٍۭ","seperti kerdipan"],["بِٱلْبَصَرِ","(dari) mata"]]],"4897":["(Dan sesungguhnya telah Kami binasakan orang yang serupa dengan kalian) dalam kekafirannya dari umat-umat terdahulu. (Maka adakah orang yang mau mengambil pelajaran?) Istifham atau kata tanya di sini mengandung makna perintah yakni, ingatlah kalian dan ambillah hal ini sebagai pelajaran buat kalian!",[["وَلَقَدْ","Dan sungguh"],["أَهْلَكْنَآ","Kami musnahkan"],["أَشْيَاعَكُمْ","jenis kamu"],["فَهَلْ","begitu juga (ada)"],["مِن","sebarang"],["مُّدَّكِرٍۢ","yang akan menerima teguran"]]],"4898":["(Dan segala sesuatu yang telah mereka perbuat) apa yang telah dikerjakan oleh semua hamba-hamba Allah telah tercatat (di dalam buku-buku) catatan amal perbuatan.",[["وَكُلُّ","Dan setiap"],["شَىْءٍۢ","perkara"],["فَعَلُوهُ","mereka lakukan"],["فِى","(berada) dalam"],["ٱلزُّبُرِ","rekod bertulis"]]],"4899":["(Dan segala urusan yang kecil maupun besar) berupa dosa atau amal perbuatan (adalah tertulis) tercatat di Lohmahfuz.",[["وَكُلُّ","Dan setiap"],["صَغِيرٍۢ","kecil"],["وَكَبِيرٍۢ","dan besar"],["مُّسْتَطَرٌ","(adalah) ditulis"]]],"4900":["(Sesungguhnya orang-orang yang bertakwa itu di dalam surga-surga) taman-taman (dan sungai-sungai makna yang dimaksud adalah jenisnya. Menurut suatu qiraat lafal Nahar dibaca Nuhur dalam bentuk jamak, yang wazannya sama dengan lafal Asadun bila dijamakkan menjadi Usudun. Makna yang dimaksud ialah, bahwa mereka meminum dari sungai-sungai surga itu air, susu, madu dan khamar.",[["إِنَّ","Sesungguhnya"],["ٱلْمُتَّقِينَ","orang yang soleh"],["فِى","(akan) masuk"],["جَنَّـٰتٍۢ","taman-taman"],["وَنَهَرٍۢ","dan sungai"]]],"4901":["(Di tempat yang benar) di majelis yang benar, karena tidak ada perkataan yang tidak berguna dan tidak pula ada perkataan yang berdosa di dalamnya; pengertian Maq'ad di sini adalah ditinjau dari segi jenisnya. Menurut qiraat yang lain lafal Maq'ad dibaca dalam bentuk jamak yaitu Maqaa'id. Makna yang dimaksud ialah bahwa ahli surga itu berada di dalam majelis-majelis surga dalam keadaan bebas dari perkataan yang tidak ada gunanya dan bebas pula dari hal-hal yang berdosa, keadaan mereka berbeda dengan keadaan majelis-majelis di dunia. Karena sesungguhnya majelis-majelis di dunia itu jarang sekali bebas dari hal-hal tersebut. Lafal ayat ini berkedudukan sebagai Khabar yang kedua, dan lafal Shidqin menjadi Badal dari lafal Shaadiqin, yakni Badal Ba'dh atau lainnya (di sisi Yang Maha Raja) merupakan perumpamaan yang mengandung makna Mubalaghah, yakni Maha Raja Yang Maha Perkasa lagi Maha Luas (lagi Maha Berkuasa) tiada sesuatu pun yang melemahkan-Nya, Dia adalah Allah swt. Lafal 'Inda menunjukkan isyarat yang mengandung makna derajat dan kedudukan mereka yang dekat di sisi-Nya, sebagai anugerah dari Allah swt. kepada para penghuni surga.",[["فِى","Dalam"],["مَقْعَدِ","tempat duduk"],["صِدْقٍ","(dari) kehormatan"],["عِندَ","dekat"],["مَلِيكٍۢ","seorang Raja"],["مُّقْتَدِرٍۭ","Maha Kuasa"]]],"4902":["(Yang Maha Pemurah) yakni Allah swt.",[["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"]]],"4903":["(Telah mengajarkan) kepada siapa yang dikehendaki-Nya (Alquran).",[["عَلَّمَ","Dia mengajar"],["ٱلْقُرْءَانَ","al-Quran"]]],"4904":["(Dia menciptakan manusia) jenis manusia.",[["خَلَقَ","Dia cipta"],["ٱلْإِنسَـٰنَ","lelaki itu"]]],"4905":["(Mengajarinya pandai berbicara) atau dapat berbicara.",[["عَلَّمَهُ","Dia mengajarnya"],["ٱلْبَيَانَ","[the] ucapan"]]],"4906":["(Matahari dan bulan menurut perhitungan) maksudnya, keduanya beredar menurut perhitungan.",[["ٱلشَّمْسُ","matahari"],["وَٱلْقَمَرُ","dan bulan"],["بِحُسْبَانٍۢ","dengan pengiraan (tepat)."]]],"4907":["(Dan tumbuh-tumbuhan) jenis tumbuh-tumbuhan yang tidak mempunyai batang (dan pohon-pohonan) jenis tumbuh-tumbuhan yang memiliki batang (kedua-duanya tunduk kepada-Nya) keduanya tunduk kepada apa yang dikehendaki-Nya.",[["وَٱلنَّجْمُ","Dan bintang"],["وَٱلشَّجَرُ","dan pokok-pokok"],["يَسْجُدَانِ","sama-sama sujud"]]],"4908":["(Dan Dia telah meninggikan langit dan meletakkan neraca) yaitu menetapkan keadilan.",[["وَٱلسَّمَآءَ","Dan syurga"],["رَفَعَهَا","Dia menaikkannya"],["وَوَضَعَ","dan Dia telah menetapkan"],["ٱلْمِيزَانَ","bakinya"]]],"4909":["(Supaya kalian jangan melampaui batas) agar kalian jangan berbuat curang (dalam timbangan itu) maksudnya dalam menimbang sesuatu dengan mempergunakan timbangan itu.",[["أَلَّا","Itu tidak"],["تَطْغَوْا۟","kamu boleh melanggar"],["فِى","dalam"],["ٱلْمِيزَانِ","bakinya"]]],"4910":["(Dan tegakkanlah timbangan itu dengan adil) artinya tidak curang (dan janganlah kalian mengurangi timbangan itu) maksudnya mengurangi barang yang ditimbang itu.",[["وَأَقِيمُوا۟","Dan dirikanlah"],["ٱلْوَزْنَ","beratnya"],["بِٱلْقِسْطِ","dalam keadilan"],["وَلَا","dan jangan"],["تُخْسِرُوا۟","membuat kekurangan"],["ٱلْمِيزَانَ","bakinya"]]],"4911":["(Dan bumi telah diletakkan-Nya) telah dimantapkan-Nya (untuk semua makhluk) untuk manusia, jin, dan lain-lainnya.",[["وَٱلْأَرْضَ","Dan bumi"],["وَضَعَهَا","Dia meletakkannya"],["لِلْأَنَامِ","untuk makhluk"]]],"4912":["(Di bumi itu ada buah-buahan dan pohon kurma) yang ditanam dan dipelihara (yang mempunyai kelopak mayang) memiliki kelopak-kelopak di bagian atasnya.",[["فِيهَا","Di dalamnya"],["فَـٰكِهَةٌۭ","(adalah) buah"],["وَٱلنَّخْلُ","dan kurma"],["ذَاتُ","mempunyai"],["ٱلْأَكْمَامِ","sarung"]]],"4913":["(Dan biji-bijian) seperti gandum dan jawawut (yang berbulir) yang ada merangnya (dan daun-daunan yang harum baunya) wangi baunya.",[["وَٱلْحَبُّ","Dan bijirin"],["ذُو","mempunyai"],["ٱلْعَصْفِ","sekam"],["وَٱلرَّيْحَانُ","dan tumbuhan wangi"]]],"4914":["(Maka manakah nikmat-nikmat) atau karunia-karunia (Rabb kamu berdua) hai manusia dan jin (yang kamu dustakan?) ayat ini disebutkan di dalam surah ini sebanyak tiga puluh satu kali. Istifham atau kata tanya yang terdapat dalam ayat ini mengandung makna taqrir atau menetapkan, demikian itu karena ada sebuah hadis yang diriwayatkan oleh Imam Hakim melalui Jabir r.a. yang telah menceritakan, bahwa Rasulullah saw. membacakan kepada kami surah Ar Rahman hingga selesai. Kemudian beliau bersabda, \"Mengapa kalian ini diam saja?\" Sungguh jin lebih baik jawabannya daripada kalian. Karena sesungguhnya tiada sekali-kali aku bacakan kepada mereka ayat ini, \"Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?\" (Q.S. Ar Rahman, 13) melainkan mereka menjawabnya, \"Wahai Rabb kami, tiada satu pun nikmat-Mu yang kami dustakan, bagi-Mu segala puji.\"",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4915":["(Dia menciptakan manusia) yakni Nabi Adam (dari tanah kering) tanah kering yang apabila diketuk akan mengeluarkan suara berdenting (seperti tembikar) seperti tanah liat yang dibakar.",[["خَلَقَ","Dia cipta"],["ٱلْإِنسَـٰنَ","lelaki itu"],["مِن","daripada"],["صَلْصَـٰلٍۢ","tanah liat"],["كَٱلْفَخَّارِ","seperti tembikar"]]],"4916":["(Dan Dia menciptakan jin) yakni bapak moyang jin, yaitu iblis (dari nyala api) yaitu nyala api yang tidak berasap",[["وَخَلَقَ","Dan Dia menciptakan"],["ٱلْجَآنَّ","jin"],["مِن","daripada"],["مَّارِجٍۢ","nyalaan tanpa asap"],["مِّن","daripada"],["نَّارٍۢ","kebakaran"]]],"4917":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4918":["(Rabb yang memelihara kedua tempat terbit matahari) yaitu tempat terbitnya di waktu musim dingin dan tempat terbitnya di waktu musim panas (dan Rabb yang memelihara kedua tempat terbenamnya) penafsirannya seperti pada yang pertama tadi.",[["رَبُّ","Tuhan"],["ٱلْمَشْرِقَيْنِ","(dari) dua Timur"],["وَرَبُّ","dan Tuhan"],["ٱلْمَغْرِبَيْنِ","(dari) dua Barat"]]],"4919":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4920":["(Dia membiarkan) atau melepaskan (dua laut) yang airnya tawar dan yang asin (saling bertemu) menurut pandangan mata.",[["مَرَجَ","Dia melepaskan"],["ٱلْبَحْرَيْنِ","dua lautan itu"],["يَلْتَقِيَانِ","mesyuarat"]]],"4921":["(Antara keduanya ada batas) ada penghalang yang membatasi keduanya dari kekuasaan Allah swt. (yang tidak dilampaui oleh masing-masing) yang satu melampaui yang lainnya sehingga bercampur.",[["بَيْنَهُمَا","Antara mereka berdua"],["بَرْزَخٌۭ","(adalah) penghalang"],["لَّا","tidak"],["يَبْغِيَانِ","mereka melampaui batas"]]],"4922":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4923":["(Keluarlah) dapat dibaca Yakhruju. dan Yukhraju (daripada keduanya) dari pertemuan di antara keduanya, yakni dari bagian yang airnya asin (mutiara dan marjan) marjan artinya batu yang berwarna merah atau yang dimaksud adalah mutiara yang kecil.",[["يَخْرُجُ","Keluarlah"],["مِنْهُمَا","daripada mereka berdua"],["ٱللُّؤْلُؤُ","mutiara itu"],["وَٱلْمَرْجَانُ","dan batu karang"]]],"4924":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4925":["(Dan kepunyaan-Nyalah bahtera-bahtera) perahu-perahu (yang dibangun) yang dibuat (di lautan laksana gunung-gunung) lautan besar yang tingginya bagaikan gunung-gunung.",[["وَلَهُ","Dan untuk Dia"],["ٱلْجَوَارِ","(adalah) kapal-kapal itu"],["ٱلْمُنشَـَٔاتُ","dinaikkan"],["فِى","dalam"],["ٱلْبَحْرِ","laut"],["كَٱلْأَعْلَـٰمِ","seperti gunung"]]],"4926":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4927":["(Semua yang ada di bumi itu) yakni semua makhluk hidup yang ada padanya (akan binasa) akan mati; di sini diungkapkan semua makhluk hidup dengan memakai kata Man, karena memprioritaskan makhluk yang berakal.",[["كُلُّ","Semua orang"],["مَنْ","yang"],["عَلَيْهَا","(ada) di atasnya"],["فَانٍۢ","(akan) binasa"]]],"4928":["(Dan tetap kekal Zat Rabbmu) yakni Zat-Nya (Yang mempunyai kebesaran) atau keagungan (dan kemuliaan) Yang Maha Dermawan kepada orang-orang mukmin dengan melimpahkan nikmat-nikmat-Nya kepada mereka.",[["وَيَبْقَىٰ","Tetapi akan kekal"],["وَجْهُ","(the) Muka"],["رَبِّكَ","Tuhanmu"],["ذُو","(the) Pemilik"],["ٱلْجَلَـٰلِ","(dari) Yang Mulia"],["وَٱلْإِكْرَامِ","dan Honor"]]],"4929":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4930":["(Semua yang ada di langit dan di bumi selalu meminta kepada-Nya) baik melalui ucapan mereka atau pun perbuatan mereka, yaitu meminta apa-apa yang mereka perlukan berupa kekuatan untuk menjalankan ibadah, rezeki, ampunan dan lain sebagainya. (Setiap hari) setiap waktu (Dia dalam suatu perkara) yaitu perkara yang hendak dilahirkan-Nya sesuai dengan apa yang telah ditentukan-Nya sejak zaman Azali antara lain, menghidupkan, mematikan, memuliakan, menghinakan, memberikan kecukupan, memiskinkan, mengabulkan doa dan memenuhi yang meminta.",[["يَسْـَٔلُهُۥ","Tanya Dia"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["كُلَّ","Setiap"],["يَوْمٍ","hari"],["هُوَ","Dia"],["فِى","(berada) dalam"],["شَأْنٍۢ","sesuatu perkara"]]],"4931":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4932":["(Kami akan menyelesaikan kamu sekalian) artinya, Kami hendak menghisab kalian semuanya (hai manusia dan jin) hai jenis manusia dan jenis jin.",[["سَنَفْرُغُ","Tidak lama lagi Kami akan hadir"],["لَكُمْ","kepada kamu"],["أَيُّهَ","Wahai"],["ٱلثَّقَلَانِ","dua kelas"]]],"4933":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4934":["(Hai semua jin dan manusia, jika kalian sanggup menembus) melintasi (penjuru) atau kawasan-kawasan (langit dan bumi, maka lintasilah) perintah di sini mengandung makna yang menunjukkan ketidakmampuan mereka untuk melakukan hal tersebut (kalian tidak dapat menembusnya melainkan dengan kekuatan) dan kalian tidak akan mempunyai kekuatan untuk itu.",[["يَـٰمَعْشَرَ","Wahai perhimpunan"],["ٱلْجِنِّ","(dari) jin"],["وَٱلْإِنسِ","dan lelaki"],["إِنِ","Jika"],["ٱسْتَطَعْتُمْ","kamu mampu"],["أَن","kepada"],["تَنفُذُوا۟","melepasi"],["مِنْ","[daripada]"],["أَقْطَارِ","(the) wilayah"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["فَٱنفُذُوا۟ ۚ","kemudian lulus"],["لَا","Tidak"],["تَنفُذُونَ","kamu (boleh) lulus"],["إِلَّا","kecuali"],["بِسُلْطَـٰنٍۢ","dengan kuasa"]]],"4935":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4936":["(Kepada kamu berdua akan dilepaskan nyala api) yakni nyala api yang tidak berasap atau nyala api yang berasap (dan asap) yaitu asap murni yang tidak ada nyala apinya (maka kamu berdua tidak akan dapat menyelamatkan diri) daripadanya, bahkan kalian kelak akan digiring ke padang Mahsyar.",[["يُرْسَلُ","Akan dihantar"],["عَلَيْكُمَا","terhadap kamu berdua"],["شُوَاظٌۭ","api"],["مِّن","daripada"],["نَّارٍۢ","kebakaran"],["وَنُحَاسٌۭ","dan asap"],["فَلَا","dan bukan"],["تَنتَصِرَانِ","kamu akan (dapat) mempertahankan diri kamu"]]],"4937":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4938":["(Maka apabila langit telah terbelah) artinya, terbuka pintu-pintunya karena turunnya malaikat-malaikat (dan menjadi merah mawar) memerah seperti warna bunga mawar (seakan-akan kilapan minyak) bagaikan minyak yang berwarna merah berbeda keadaannya dengan yang biasa. Di dalam ungkapan ayat ini terkandung jawabannya, yakni apabila saat itu datang, betapa dahsyatnya kengerian dan ketakutan melihatnya.",[["فَإِذَا","Kemudian apabila"],["ٱنشَقَّتِ","terbelah"],["ٱلسَّمَآءُ","syurga itu"],["فَكَانَتْ","dan ia menjadi"],["وَرْدَةًۭ","berwarna mawar"],["كَٱلدِّهَانِ","seperti minyak keruh"]]],"4939":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?).",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4940":["(Pada waktu itu manusia dan jin tidak ditanya tentang dosanya) tetapi mereka akan ditanya mengenai dosanya di lain waktu, karena ini merupakan suatu janji sebagaimana yang diungkapkan di dalam firman lainnya, yaitu, \"Maka demi Rabbmu, Kami pasti akan menanyai mereka semua.\" (Q.S. Al Hijr, 92) Lafal Al Jaan di sini sebagaimana yang akan dijelaskan nanti adalah bermakna jin, dan lafal Al Insu artinya manusia.",[["فَيَوْمَئِذٍۢ","Kemudian (pada) hari itu"],["لَّا","tidak"],["يُسْـَٔلُ","akan ditanya"],["عَن","tentang"],["ذَنۢبِهِۦٓ","dosanya"],["إِنسٌۭ","mana-mana lelaki"],["وَلَا","dan bukan"],["جَآنٌّۭ","mana-mana jin"]]],"4941":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4942":["(Orang-orang yang berdosa dikenal dengan tanda-tandanya) yakni, mukanya berwarna hitam dan matanya berwarna biru (lalu dipegang ubun-ubun dan kaki mereka).",[["يُعْرَفُ","Akan diketahui"],["ٱلْمُجْرِمُونَ","penjenayah"],["بِسِيمَـٰهُمْ","dengan markah mereka"],["فَيُؤْخَذُ","dan akan disita"],["بِٱلنَّوَٰصِى","oleh ubun-ubun"],["وَٱلْأَقْدَامِ","dan kaki"]]],"4943":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?) Keadaan orang-orang yang berdosa pada saat itu, kedua telapak kaki mereka disatukan dengan ubun-ubunnya dari arah belakang, yaitu dilipat lalu mereka dilemparkan ke dalam neraka dan dikatakan kepada mereka,",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4944":["(\"Inilah neraka Jahanam yang didustakan oleh orang-orang yang berdosa\").",[["هَـٰذِهِۦ","Ini"],["جَهَنَّمُ","(ialah) Neraka"],["ٱلَّتِى","yang"],["يُكَذِّبُ","menafikan"],["بِهَا","[daripadanya]"],["ٱلْمُجْرِمُونَ","penjenayah"]]],"4945":["(Mereka berkeliling) yakni berjalan dengan cepat (di antaranya dan di antara air yang mendidih yaitu air panas (yang memuncak panasnya) panasnya tak terperikan, lalu mereka diberi minum air panas tersebut apabila mereka meminta tolong karena panasnya api neraka; lafal Anin termasuk Isim Manqush, sama halnya dengan lafal Qaadhin.",[["يَطُوفُونَ","Mereka akan berkeliling"],["بَيْنَهَا","antaranya"],["وَبَيْنَ","dan antara"],["حَمِيمٍ","air panas"],["ءَانٍۢ","dipanaskan"]]],"4946":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4947":["(Dan bagi orang yang takut) bagi masing-masing dari mereka atau bagi mereka semuanya (akan saat menghadap Rabbnya) yaitu takut manakala ia berdiri di hadapan Rabbnya untuk menjalani hisab. Oleh karena itu, maka ia tidak mau berbuat durhaka kepada-Nya (ada dua taman).",[["وَلِمَنْ","Tetapi untuk (dia) yang"],["خَافَ","ketakutan"],["مَقَامَ","(yang) berdiri"],["رَبِّهِۦ","(di hadapan) Tuhannya"],["جَنَّتَانِ","(adalah) dua taman"]]],"4948":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4949":["(Kedua taman itu mempunyai) lafal Dzawaata adalah bentuk Tatsniyah dari lafal Dzawaat sesuai dengan bentuk asalnya; dan Lam fi'ilnya pada asalnya adalah huruf Ya (pohon-pohon yang rindang) banyak tangkainya; merupakan bentuk jamak dari lafal Fananun yang wazannya sama dengan lafal Thalalun.",[["ذَوَاتَآ","mempunyai"],["أَفْنَانٍۢ","cawangan"]]],"4950":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4951":["(Di dalam kedua taman surga itu ada dua buah mata air yang mengalir).",[["فِيهِمَا","Dalam kedua-duanya"],["عَيْنَانِ","(adalah) dua mata air"],["تَجْرِيَانِ","mengalir"]]],"4952":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4953":["(Di dalam kedua taman surga itu terdapat segala macam buah-buahan) di dunia atau semua yang dianggap sebagai buah-buahan (yang berpasang-pasangan) yakni dua jenis-dua jenis, ada yang basah dan ada yang kering. Buah Hanzhal yang di dunia terasa amat pahit, tetapi di surga akan terasa manis.",[["فِيهِمَا","Dalam kedua-duanya"],["مِن","[daripada]"],["كُلِّ","(adalah) setiap"],["فَـٰكِهَةٍۢ","buah-buahan"],["زَوْجَانِ","(dalam) berpasangan"]]],"4954":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4955":["(Mereka bersandarkan) menjadi Hal atau kata keterangan keadaan dari 'Amilnya yang tidak disebutkan, yakni mereka bersenang-senang seraya bersandarkan (di atas permadani yang bagian dalamnya terbuat dari sutera) yaitu sutera yang tebal lagi kasar, sedangkan bagian luarnya yang diduduki terbuat dari sutera yang halus sekali. (Dan buah-buahan kedua surga itu) semua buah-buahannya (dapat dipetik dari dekat) artinya, dekat sekali letaknya sehingga mudah dipetik, baik oleh orang yang sedang berdiri maupun yang duduk dan yang sedang berbaring.",[["مُتَّكِـِٔينَ","Berbaring"],["عَلَىٰ","pada"],["فُرُشٍۭ","pelamin"],["بَطَآئِنُهَا","(yang) lapisan dalam"],["مِنْ","(adalah) daripada"],["إِسْتَبْرَقٍۢ ۚ","brokat"],["وَجَنَى","dan buah-buahan"],["ٱلْجَنَّتَيْنِ","(dari) kedua-dua taman itu"],["دَانٍۢ","(ada) dekat"]]],"4956":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4957":["(Di dalam surga itu) maksudnya, dalam kedua surga itu dan pada gedung-gedung dan istana-istana yang ada di dalamnya (ada bidadari-bidadari yang selalu menundukkan pandangan matanya) artinya, pandangan mereka terbatas hanya kepada suami-suami mereka saja yang terdiri dari manusia dan jin (tidak pernah disentuh) mereka belum pernah digauli; mereka terdiri dari bidadari-bidadari atau wanita-wanita dunia yang masuk surga (oleh manusia sebelum mereka -penghuni-penghuni surga yang menjadi suami mereka dan tidak pula oleh jin).",[["فِيهِنَّ","Dalam mereka"],["قَـٰصِرَٰتُ","(akan menjadi) teman yang memandang rendah"],["ٱلطَّرْفِ","(akan menjadi) teman yang memandang rendah"],["لَمْ","tidak"],["يَطْمِثْهُنَّ","telah menyentuh mereka"],["إِنسٌۭ","mana-mana lelaki"],["قَبْلَهُمْ","sebelum mereka"],["وَلَا","dan bukan"],["جَآنٌّۭ","mana-mana jin"]]],"4958":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4959":["(Seakan-akan bidadari-bidadari itu permata yaqut) dalam hal beningnya (dan marjan) maksudnya, putihnya bagaikan permata.",[["كَأَنَّهُنَّ","Seolah-olah mereka"],["ٱلْيَاقُوتُ","batu delima"],["وَٱلْمَرْجَانُ","dan batu karang"]]],"4960":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4961":["(Tidak ada) tiada (balasan kebaikan) atau ketaatan (kecuali kebaikan pula) atau kenikmatan.",[["هَلْ","Adakah"],["جَزَآءُ","(i) ganjaran"],["ٱلْإِحْسَـٰنِ","untuk kebaikan"],["إِلَّا","tetapi"],["ٱلْإِحْسَـٰنُ","kebaikan"]]],"4962":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4963":["(Dan selain dari kedua surga itu) yakni kedua surga yang telah disebutkan tadi (ada dua surga lagi) yaitu bagi orang yang takut akan saat menghadap kepada Rabbnya.",[["وَمِن","Selain dua ini"],["دُونِهِمَا","Selain dua ini"],["جَنَّتَانِ","(adalah) dua taman"]]],"4964":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4965":["(Kedua surga itu hijau tua warnanya) kelihatan hijau pekat karena sangat hijaunya.",[["مُدْهَآمَّتَانِ","Hijau gelap"]]],"4966":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4967":["(Di dalam kedua surga itu ada dua mata air yang memancar) bagaikan air mancur.",[["فِيهِمَا","Dalam kedua-duanya"],["عَيْنَانِ","(adalah) dua mata air"],["نَضَّاخَتَانِ","terpancut keluar"]]],"4968":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4969":["(Di dalam keduanya ada buah-buahan dan kurma serta delima) buah kurma dan delima itu menurut suatu pendapat adalah sebagaimana aslinya, tetapi menurut pendapat yang lain tidak seperti bentuk aslinya.",[["فِيهِمَا","Dalam kedua-duanya"],["فَـٰكِهَةٌۭ","(adalah) buah-buahan"],["وَنَخْلٌۭ","dan kurma"],["وَرُمَّانٌۭ","dan buah delima"]]],"4970":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4971":["(Di dalam surga-surga itu) di kedua surga dan apa-apa yang ada di dalamnya itu (ada bidadari-bidadari yang baik-baik) akhlaknya (lagi cantik-cantik) rupanya.",[["فِيهِنَّ","Dalam mereka"],["خَيْرَٰتٌ","(adalah) baik"],["حِسَانٌۭ","dan yang cantik"]]],"4972":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4973":["(Bidadari-bidadari itu-sangat jelita) mata mereka sangat jelita (mereka dipingit) tertutup (di dalam kemah-kemah) yang terbuat dari permata yang dilubangi, keadaan mereka diserupakan dengan gadis-gadis yang dipingit di dalam kemahnya.",[["حُورٌۭ","yang adil"],["مَّقْصُورَٰتٌۭ","dihalang"],["فِى","dalam"],["ٱلْخِيَامِ","astaka"]]],"4974":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4975":["(Mereka tidak pernah disentuh oleh manusia sebelum mereka) sebelum oleh suami-suami mereka (dan tidak pula oleh jin).",[["لَمْ","Tidak"],["يَطْمِثْهُنَّ","telah menyentuh mereka"],["إِنسٌۭ","mana-mana lelaki"],["قَبْلَهُمْ","sebelum mereka"],["وَلَا","dan bukan"],["جَآنٌّۭ","mana-mana jin"]]],"4976":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4977":["(Mereka bersandarkan) suami-suami mereka bertelekan; I'rab lafal ayat ini sama dengan sebelumnya (pada bantal-bantal yang hijau) merupakan bentuk jamak dari lafal Rafrafatun, artinya permadani atau bantal (dan bergelarkan pada permadani-permadani yang indah) merupakan bentuk jamak dari lafal 'Abqariyyah, artinya permadani.",[["مُتَّكِـِٔينَ","Berbaring"],["عَلَىٰ","pada"],["رَفْرَفٍ","kusyen"],["خُضْرٍۢ","hijau"],["وَعَبْقَرِىٍّ","dan permaidani"],["حِسَانٍۢ","cantik"]]],"4978":["(Maka manakah nikmat-nikmat Rabb kamu berdua yang kamu dustakan?)",[["فَبِأَىِّ","Jadi yang mana"],["ءَالَآءِ","(daripada) nikmat"],["رَبِّكُمَا","Tuhanmu"],["تُكَذِّبَانِ","adakah kamu berdua akan menafikan"]]],"4979":["(Maha Agung nama Rabbmu Yang mempunyai kebesaran dan Karunia) penafsirannya sebagaimana sebelumnya, dan lafal Ismi pada ayat ini merupakan Isim Zaaid atau Isim yang ditambahkan.",[["تَبَـٰرَكَ","Berbahagialah"],["ٱسْمُ","(nama)"],["رَبِّكَ","Tuhanmu"],["ذِى","Pemilik"],["ٱلْجَلَـٰلِ","(dari) Yang Mulia"],["وَٱلْإِكْرَامِ","dan Honor"]]],"4980":["(Apabila hari kiamat terjadi) bilamana hari terakhir tiba.",[["إِذَا","Apabila"],["وَقَعَتِ","berlaku"],["ٱلْوَاقِعَةُ","Peristiwa itu"]]],"4981":["(Tidak ada seorang pun dapat berdusta tentang kejadiannya) maksudnya, tiada seorang pun yang tidak mempercayai kejadiannya sebagaimana ia tidak mempercayainya sewaktu di dunia.",[["لَيْسَ","Tidak"],["لِوَقْعَتِهَا","pada kejadiannya"],["كَاذِبَةٌ","penafian"]]],"4982":["(Ia merendahkan dan meninggikan) artinya, kejadian hari kiamat itu menampakkan siapa di antara mereka yang terhina karena dimasukkan ke dalam neraka, dan siapa di antara mereka yang ditinggikan derajatnya karena dimasukkan ke dalam surga.",[["خَافِضَةٌۭ","Menurunkan"],["رَّافِعَةٌ","membangkitkan"]]],"4983":["(Apabila bumi diguncangkan dengan se dahsyat-dahsyatnya) yakni bilamana bumi mengalami gempa yang amat dahsyat.",[["إِذَا","Apabila"],["رُجَّتِ","akan digoncang"],["ٱلْأَرْضُ","bumi"],["رَجًّۭا","(dengan) gegaran"]]],"4984":["(Dan gunung-gunung dihancurluluhkan sehancur-hancurnya) atau apabila gunung-gunung dihancurleburkan.",[["وَبُسَّتِ","Dan akan hancur"],["ٱلْجِبَالُ","pergunungan"],["بَسًّۭا","(dengan dahsyat) runtuh"]]],"4985":["(Maka jadilah dua debu) yaitu berupa debu (yang beterbangan) yang menyebar ke mana-mana. Lafal Idzaa kedua menjadi Badal dari lafal Idza pertama.",[["فَكَانَتْ","Jadi mereka menjadi"],["هَبَآءًۭ","zarah habuk"],["مُّنۢبَثًّۭا","bersurai"]]],"4986":["(Dan kalian menjadi) pada hari kiamat itu (bergolong-golongan) terdiri dari golongan-golongan (yang terbagi tiga).",[["وَكُنتُمْ","Dan kamu akan menjadi"],["أَزْوَٰجًۭا","macam-macam"],["ثَلَـٰثَةًۭ","tiga"]]],"4987":["(Yaitu golongan kanan) mereka adalah orang-orang yang kitab catatan amal perbuatan mereka diberikan kepadanya dari sebelah kanan. Kalimat ayat ini menjadi Mubtada sedangkan Khabarnya ialah, (Alangkah mulianya golongan kanan itu) kalimat ayat ini mengandung makna yang mengagungkan dan memuliakan kedudukan mereka, karena mereka dimasukkan ke dalam surga.",[["فَأَصْحَـٰبُ","Kemudian (para) sahabat"],["ٱلْمَيْمَنَةِ","(dari) hak"],["مَآ","apa"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْمَيْمَنَةِ","(dari) hak"]]],"4988":["(Dan golongan kiri) yakni mereka yang kitab catatan amalnya diberikan kepadanya dari sebelah kiri. (Alangkah sengsaranya golongan kiri itu) ungkapan ini mengandung makna yang menghinakan kedudukan mereka, karena mereka dimasukkan ke dalam neraka.",[["وَأَصْحَـٰبُ","Dan (para) sahabat"],["ٱلْمَشْـَٔمَةِ","(dari) kiri"],["مَآ","apa"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْمَشْـَٔمَةِ","(dari) kiri"]]],"4989":["(Dan orang-orang yang paling dahulu) dalam kebaikan, mereka adalah para nabi; ayat ini berkedudukan menjadi Mubtada (yaitu orang-orang yang paling dahulu) lafal ayat ini mengukuhkan makna ayat pertama, dimaksud sebagai ungkapan tentang keagungan kedudukan mereka.",[["وَٱلسَّـٰبِقُونَ","Dan yang paling utama"],["ٱلسَّـٰبِقُونَ","(adalah) yang paling utama"]]],"4990":["(Mereka itulah orang yang didekatkan).",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلْمُقَرَّبُونَ","(adalah) yang terdekat"]]],"4991":["(Berada di dalam surga-surga yang penuh dengan kenikmatan).",[["فِى","Dalam"],["جَنَّـٰتِ","Taman-taman"],["ٱلنَّعِيمِ","(dari) Keseronokan"]]],"4992":["(Segolongan besar dari orang-orang yang terdahulu) menjadi Mubtada, artinya golongan mayoritas dari umat-umat terdahulu.",[["ثُلَّةٌۭ","Sebuah syarikat"],["مِّنَ","daripada"],["ٱلْأَوَّلِينَ","bekas (orang)"]]],"4993":["(Dan segolongan kecil dari orang-orang yang kemudian) yakni dari kalangan umat Nabi Muhammad saw. Mereka terdiri dari bagian besar umat-umat terdahulu dan umat Nabi Muhammad adalah orang-orang yang paling dahulu masuk surga.",[["وَقَلِيلٌۭ","Dan beberapa"],["مِّنَ","daripada"],["ٱلْـَٔاخِرِينَ","kemudian (orang)"]]],"4994":["(Mereka berada di atas dipan-dipan yang bertahtakan emas dan permata) yaitu singgasana-singgasana yang terbuat dari emas dan permata.",[["عَلَىٰ","hidup"],["سُرُرٍۢ","takhta"],["مَّوْضُونَةٍۢ","berhias"]]],"4995":["(Seraya bersandarkan di atasnya berhadap-hadapan) kedua lafal ayat ini berkedudukan menjadi Hal atau kata keterangan keadaan bagi Dhamir yang terkandung di dalam Khabar.",[["مُّتَّكِـِٔينَ","Berbaring"],["عَلَيْهَا","ke atas mereka"],["مُتَقَـٰبِلِينَ","berdepan antara satu sama lain"]]],"4996":["(Mereka dikelilingi) oleh para pelayan (yang terdiri dari anak-anak muda yang tetap muda) maksudnya, mereka tetap muda untuk selama-lamanya.",[["يَطُوفُ","Akan beredar"],["عَلَيْهِمْ","antara mereka"],["وِلْدَٰنٌۭ","budak lelaki"],["مُّخَلَّدُونَ","abadi"]]],"4997":["(Dengan membawa gelas-gelas) atau tempat-tempat minum yang tidak ada ikatan atau pegangannya (dan cerek) yakni tempat untuk menuangkan minuman yang mempunyai pegangan dan ada pipa penuangannya (dan guci) yaitu, tempat untuk meminum khamar (yang isinya diambil dari air yang mengalir) yaitu dari khamar yang mengalir dari sumbernya yang tidak pernah kering untuk selama-lamanya.",[["بِأَكْوَابٍۢ","Dengan kapal"],["وَأَبَارِيقَ","dan kendi"],["وَكَأْسٍۢ","dan secawan"],["مِّن","daripada"],["مَّعِينٍۢ","aliran yang mengalir"]]],"4998":["(Mereka tidak pernah merasa pening karenanya dan tidak pula mabuk) dapat dibaca Yanzafuuna atau Yanzifuuna, berasal dari lafal Nazafasy Syaaribu, dan Anzafasy Syaaribu. Artinya mereka tidak merasa pening dan tidak pula merasa mabuk karena meminumnya, berbeda dengan khamar di dunia.",[["لَّا","Tidak"],["يُصَدَّعُونَ","mereka akan sakit kepala"],["عَنْهَا","daripadanya"],["وَلَا","dan bukan"],["يُنزِفُونَ","mereka akan mabuk"]]],"4999":["(Dan buah-buahan dari apa yang mereka pilih).",[["وَفَـٰكِهَةٍۢ","Dan buah-buahan"],["مِّمَّا","tentang apa"],["يَتَخَيَّرُونَ","mereka pilih"]]],"5000":["(Dan daging burung dari apa yang mereka inginkan) untuk mereka nikmati sepuas-puasnya.",[["وَلَحْمِ","Dan (yang) daging"],["طَيْرٍۢ","(daripada) unggas"],["مِّمَّا","tentang apa"],["يَشْتَهُونَ","mereka inginkan"]]],"5001":["(Dan bidadari-bidadari) yakni wanita-wanita yang memiliki mata hitam pekat pada bagian yang hitamnya dan putih bersih pada bagian yang putihnya (yang bermata jeli) artinya, matanya lebar tetapi cantik. Harakat huruf 'Ainnya dikasrahkan sebagai pengganti dari harakat fatahnya demi untuk menyesuaikan diri dengan huruf Ya sesudahnya. Bentuk tunggalnya adalah 'Ainaa wazannya sama dengan Hamraa. Tetapi menurut suatu qiraat dibaca Huurin 'Inin yakni dibaca Jarr.",[["وَحُورٌ","Dan yang adil"],["عِينٌۭ","(dengan) mata yang besar"]]],"5002":["(Laksana mutiara yang tersimpan) yang disimpan dan terpelihara.",[["كَأَمْثَـٰلِ","Suka"],["ٱللُّؤْلُؤِ","mutiara"],["ٱلْمَكْنُونِ","terlindung dengan baik"]]],"5003":["(Sebagai balasan) menjadi Maf'ul Lah, atau Mashdar, sedangkan 'Amilnya diperkirakan keberadaannya, yaitu, Kami jadikan hal-hal yang telah disebutkan itu buat mereka sebagai pembalasan. Atau, Kami memberikan balasan kepada mereka (bagi apa yang telah mereka kerjakan).",[["جَزَآءًۢ","Satu ganjaran"],["بِمَا","bagi apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"5004":["(Mereka tidak mendengar di dalamnya) di dalam surga itu (perkataan yang tidak ada gunanya) yakni perkataan jorok (dan tidak pula perkataan yang menimbulkan dosa) maksudnya perkataan yang berdosa.",[["لَا","Tidak"],["يَسْمَعُونَ","mereka akan mendengar"],["فِيهَا","di dalamnya"],["لَغْوًۭا","cakap kosong"],["وَلَا","dan bukan"],["تَأْثِيمًا","berdosa (ucapan)"]]],"5005":["(Akan tetapi) (dikatakan) kepada mereka ucapan (Salam, Salam) lafal ayat ini menjadi Badal dari lafal Qiilan; mereka benar-benar mendengarnya.",[["إِلَّا","Kecuali"],["قِيلًۭا","sebuah pepatah"],["سَلَـٰمًۭا","Damai"],["سَلَـٰمًۭا","Damai"]]],"5006":["(Dan golongan kanan, alangkah bahagianya golongan kanan itu).",[["وَأَصْحَـٰبُ","Dan (para) sahabat"],["ٱلْيَمِينِ","(dari) hak"],["مَآ","apa"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْيَمِينِ","(dari) hak"]]],"5007":["(Berada di antara pohon bidara) atau dikenal dengan nama pohon Nabaq (yang tidak berduri) tidak ada durinya.",[["فِى","Antara"],["سِدْرٍۢ","pokok lote"],["مَّخْضُودٍۢ","tanpa duri"]]],"5008":["(Dan pohon pisang) yang juga dikenal dengan nama pohon muz (yang bersusun-susun) buahnya mulai dari bagian atas hingga bagian bawahnya.",[["وَطَلْحٍۢ","Dan pokok pisang"],["مَّنضُودٍۢ","berlapis-lapis"]]],"5009":["(Dan naungan yang terbentang luas) untuk selama-lamanya.",[["وَظِلٍّۢ","Dan teduh"],["مَّمْدُودٍۢ","dipanjangkan"]]],"5010":["(Dan air yang tercurah) maksudnya air yang mengalir terus selama-lamanya.",[["وَمَآءٍۢ","Dan air"],["مَّسْكُوبٍۢ","dicurahkan"]]],"5011":["(Dan buah-buahan yang banyak).",[["وَفَـٰكِهَةٍۢ","Dan buah-buahan"],["كَثِيرَةٍۢ","melimpah ruah"]]],"5012":["(Yang tidak berhenti) buahnya. karena musim-musiman (dan tidak terlarang mengambilnya) artinya, ia boleh diambil tanpa harus membayarnya.",[["لَّا","Tidak"],["مَقْطُوعَةٍۢ","terhad"],["وَلَا","dan bukan"],["مَمْنُوعَةٍۢ","dilarang"]]],"5013":["(Dan kasur-kasur yang tebal lagi empuk) yang diletakkan di atas dipan-dipan.",[["وَفُرُشٍۢ","Dan (di) dipan"],["مَّرْفُوعَةٍ","dinaikkan"]]],"5014":["(Sesungguhnya Kami menciptakan mereka dengan langsung) maksudnya, bidadari-bidadari yang jelita lagi cantik itu Kami ciptakan tanpa melalui proses kelahiran terlebih dahulu.",[["إِنَّآ","Sesungguhnya Kami"],["أَنشَأْنَـٰهُنَّ","[Kami] telah menghasilkannya"],["إِنشَآءًۭ","(menjadi) ciptaan"]]],"5015":["(Dan Kami jadikan mereka gadis-gadis perawan) yakni perawan semuanya; setiap kali suami-suami mereka menggaulinya, para suami itu menjumpai mereka dalam keadaan perawan kembali; dan tidak ada rasa sakit dikala menggaulinya.",[["فَجَعَلْنَـٰهُنَّ","Dan Kami telah menjadikan mereka"],["أَبْكَارًا","anak dara"]]],"5016":["(Penuh cinta) dapat dibaca 'Uruban atau 'Urban, bentuk jamak dari lafal 'Aruubun, artinya wanita yang sangat mencintai suaminya dan sangat merindukannya (lagi sebaya umurnya) setara umurnya; bentuk jamak dari lafal Turbun.",[["عُرُبًا","berbakti"],["أَتْرَابًۭا","sama umur"]]],"5017":["(Untuk golongan kanan) menjadi Shilah dari lafal Ansya-naahunna, atau dari lafal Ja'alnaahunna. Yakni Kami ciptakan atau Kami jadikan mereka untuk golongan kanan. Golongan kanan itu adalah,",[["لِّأَصْحَـٰبِ","Untuk (para) sahabat"],["ٱلْيَمِينِ","(dari) hak"]]],"5018":["(segolongan besar dari orang-orang yang terdahulu).",[["ثُلَّةٌۭ","Sebuah syarikat"],["مِّنَ","daripada"],["ٱلْأَوَّلِينَ","orang dahulu"]]],"5019":["(Dan segolongan besar pula dari orang-orang yang kemudian).",[["وَثُلَّةٌۭ","Dan sebuah syarikat"],["مِّنَ","daripada"],["ٱلْـَٔاخِرِينَ","orang-orang kemudian"]]],"5020":["(Dan golongan kiri, alangkah celakanya golongan kiri itu).",[["وَأَصْحَـٰبُ","Dan (para) sahabat"],["ٱلشِّمَالِ","(dari) kiri"],["مَآ","apa"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلشِّمَالِ","(dari) kiri"]]],"5021":["(Dalam angin yang amat panas) yaitu angin panas dari neraka, panas angin itu dapat menembus sampai ke pori-pori (dan air panas yang mendidih) yang panasnya tak terperikan.",[["فِى","Dalam"],["سَمُومٍۢ","api yang membara"],["وَحَمِيمٍۢ","dan air panas"]]],"5022":["(Dan dalam naungan asap yang hitam) mereka diliputi oleh asap yang sangat hitam.",[["وَظِلٍّۢ","Dan teduh"],["مِّن","daripada"],["يَحْمُومٍۢ","asap hitam"]]],"5023":["(Tidak sejuk) tidak sebagaimana naungan yang biasanya (dan tidak menyenangkan) tidak baik pemandangannya.",[["لَّا","Tidak"],["بَارِدٍۢ","sejuk"],["وَلَا","dan bukan"],["كَرِيمٍ","menyenangkan"]]],"5024":["(Sesungguhnya mereka sebelum itu) yakni sewaktu-waktu berada di dunia (hidup bermewah-mewah) mereka selalu hidup bersenang-senang dan tidak mau melelahkan diri mereka dalam ketaatan.",[["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["قَبْلَ","sebelum"],["ذَٰلِكَ","bahawa"],["مُتْرَفِينَ","menikmati kemewahan"]]],"5025":["(Dan mereka terus menerus mengerjakan dosa) melakukan perbuatan dosa (yang besar) yaitu perbuatan menyekutukan Allah.",[["وَكَانُوا۟","Dan telah"],["يُصِرُّونَ","berterusan"],["عَلَى","dalam"],["ٱلْحِنثِ","dosa itu"],["ٱلْعَظِيمِ","yang hebat"]]],"5026":["(Dan mereka selalu mengatakan, \"Apabila kami mati dan menjadi tanah dan tulang belulang, apakah sesungguhnya kami benar-benar akan dibangkitkan?) kedua huruf Hamzah pada dua tempat dapat dibaca Tahqiq dan dapat pula dibaca Tas-hil.",[["وَكَانُوا۟","Dan mereka dahulu (untuk)"],["يَقُولُونَ","berkata"],["أَئِذَا","Apabila"],["مِتْنَا","kita mati"],["وَكُنَّا","dan menjadi"],["تُرَابًۭا","habuk"],["وَعِظَـٰمًا","dan tulang"],["أَءِنَّا","akan kita"],["لَمَبْعُوثُونَ","pasti dibangkitkan"]]],"5027":["(Apakah bapak-bapak kami yang terdahulu dibangkitkan pula?\") lafal Awa huruf Wawunya dibaca Fat-hah, sedangkan huruf Hamzahnya menunjukkan kata tanya, Hamzah atau kata tanya pada ayat ini dan pada ayat sebelumnya mengandung arti Istib'ad, artinya jauh dari kemungkinan; ini berdasarkan keyakinan mereka yang tidak mempercayainya. Tetapi menurut suatu qiraat huruf Wawu dibaca Sukun sehingga bacaannya menjadi Au karena di'athafkan kepada Inna dan Isimnya secara Mahall.",[["أَوَءَابَآؤُنَا","Dan juga bapa kita"],["ٱلْأَوَّلُونَ","bekas"]]],"5028":["(Katakanlah, \"Sesungguhnya orang-orang yang terdahulu dan orang-orang yang terkemudian,)",[["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱلْأَوَّلِينَ","yang dahulu"],["وَٱلْـَٔاخِرِينَ","dan orang-orang yang kemudian"]]],"5029":["(benar-benar akan dikumpulkan di waktu tertentu) atau waktu yang tertentu (pada hari yang dikenal) yaitu pada hari kiamat.",[["لَمَجْمُوعُونَ","Pasti, akan dikumpulkan"],["إِلَىٰ","bagi"],["مِيقَـٰتِ","(the) pelantikan"],["يَوْمٍۢ","(dari) sehari"],["مَّعْلُومٍۢ","terkenal"]]],"5030":["(Kemudian sesungguhnya kalian, hai orang-orang yang sesat lagi mendustakan!)",[["ثُمَّ","Kemudian"],["إِنَّكُمْ","sesungguhnya kamu"],["أَيُّهَا","Wahai mereka yang sesat"],["ٱلضَّآلُّونَ","Wahai mereka yang sesat"],["ٱلْمُكَذِّبُونَ","orang yang menafikan"]]],"5031":["(Benar-benar akan memakan pohon zaqqum) lafal Min zaqquum menjadi Bayan dari lafal Min Syajarin.",[["لَـَٔاكِلُونَ","Pasti akan makan"],["مِن","daripada"],["شَجَرٍۢ","(the) pokok"],["مِّن","daripada"],["زَقُّومٍۢ","Zaqqum"]]],"5032":["(Maka kalian akan memenuhi dengannya) dengan pohon zaqqum itu (perut-perut kalian).",[["فَمَالِـُٔونَ","Kemudian akan mengisi"],["مِنْهَا","dengannya"],["ٱلْبُطُونَ","perut"]]],"5033":["(Sesudah itu kalian minum) yakni sesudah memakan buah pohon zaqqum itu (air yang sangat panas).",[["فَشَـٰرِبُونَ","Dan minum"],["عَلَيْهِ","atasnya"],["مِنَ","[dari]"],["ٱلْحَمِيمِ","air panas itu"]]],"5034":["(Maka kalian minum seperti minumnya) dapat dibaca Syarba, atau Syurba, dalam keadaan Nashab karena menjadi Mashdar (unta yang kehausan) maksudnya, bagaikan unta yang sedang kehausan. Lafal Al Hiim adalah bentuk jamak dari lafal Haiman untuk jenis jantan, dan untuk jenis betina dikatakan Haimaa; wazannya sama dengan lafal 'Athsyaan dan 'Athsyaa.",[["فَشَـٰرِبُونَ","Dan akan minum"],["شُرْبَ","(sebagai) minum"],["ٱلْهِيمِ","(dari) unta-unta yang kehausan"]]],"5035":["(Itulah hidangan untuk mereka) apa yang disediakan untuk mereka (pada hari pembalasan\") yakni di hari kiamat nanti.",[["هَـٰذَا","Ini"],["نُزُلُهُمْ","(adalah) keramahan mereka"],["يَوْمَ","(pada) hari"],["ٱلدِّينِ","(dari) Penghakiman"]]],"5036":["(Kami telah menciptakan kalian) dari tiada (maka mengapa tidak) kenapa tidak (kalian membenarkan) atau mempercayai adanya hari berbangkit, karena sesungguhnya Allah yang mampu menciptakan mereka. Dia mampu pula untuk menghidupkan mereka kembali.",[["نَحْنُ","Kami"],["خَلَقْنَـٰكُمْ","[Kami] mencipta kamu"],["فَلَوْلَا","jadi mengapa (tidak) tidak"],["تُصَدِّقُونَ","kamu mengaku kebenaran"]]],"5037":["(Maka terangkanlah kepada-Ku nuthfah yang kalian tumpahkan) yakni air mani yang kalian tumpahkan ke dalam rahim wanita.",[["أَفَرَءَيْتُم","Adakah kamu melihat"],["مَّا","apa"],["تُمْنُونَ","kamu memancarkan"]]],"5038":["(Kamukah) dapat dibaca Tahqiq dan dapat pula dibaca Tas-hil (yang menciptakannya) yakni air mani itu kemudian menjadi manusia (atau Kami kah yang menciptakannya?)",[["ءَأَنتُمْ","Adakah kamu"],["تَخْلُقُونَهُۥٓ","yang menciptanya"],["أَمْ","atau"],["نَحْنُ","(adalah) Kami"],["ٱلْخَـٰلِقُونَ","para Pencipta"]]],"5039":["(Kami telah menentukan) dapat dibaca Qaddarnaa atau Qadarnaa (kematian di antara kalian dan Kami sekali-kali tidak dapat dikalahkan) dibuat tak berdaya.",[["نَحْنُ","Kami"],["قَدَّرْنَا","[Kami] telah menetapkan"],["بَيْنَكُمُ","antara kamu"],["ٱلْمَوْتَ","kematian itu"],["وَمَا","dan bukan"],["نَحْنُ","Kami"],["بِمَسْبُوقِينَ","(sedang) berlari lebih cepat"]]],"5040":["(Untuk) maksudnya, supaya Kami (menggantikan) menjadikan (orang-orang yang seperti kalian) sebagai pengganti dari kalian (dan menciptakan kalian kelak) di akhirat (dalam keadaan yang tidak kalian ketahui) maksudnya, dalam bentuk yang belum kalian ketahui, seperti dalam bentuk kera atau babi, umpamanya.",[["عَلَىٰٓ","Dalam"],["أَن","bahawa"],["نُّبَدِّلَ","Kami (akan) berubah"],["أَمْثَـٰلَكُمْ","rupa kamu[es]"],["وَنُنشِئَكُمْ","dan menghasilkan kamu"],["فِى","dalam"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"5041":["(Dan sesungguhnya kalian telah mengetahui penciptaan yang pertama) menurut suatu qiraat lafal An Nasy`ata boleh dibaca An-Nasya`ata (maka mengapa kalian tidak mengambil pelajaran?) lafal Tadzakkaruuna asalnya adalah Tatadzakkaruuna, lalu huruf Ta yang kedua diidgamkan kepada huruf Dzal.",[["وَلَقَدْ","Dan sungguh"],["عَلِمْتُمُ","kamu tahu"],["ٱلنَّشْأَةَ","penciptaan"],["ٱلْأُولَىٰ","yang pertama"],["فَلَوْلَا","jadi kenapa tidak"],["تَذَكَّرُونَ","kamu ambil iktibar"]]],"5042":["(Maka terangkanlah kepada-Ku tentang yang kalian tanam?) yaitu tentang tanah yang kalian bajak lalu kalian semaikan benih-benih di atasnya.",[["أَفَرَءَيْتُم","Dan adakah kamu melihat"],["مَّا","apa"],["تَحْرُثُونَ","kamu tabur"]]],"5043":["(Kaliankah yang menumbuhkannya) suatu pertanyaan, apakah kalian yang telah menumbuhkannya (ataukah Kami yang menumbuhkannya?)",[["ءَأَنتُمْ","Adakah kamu (yang)"],["تَزْرَعُونَهُۥٓ","menyebabkan ia berkembang"],["أَمْ","atau"],["نَحْنُ","(adalah) Kami"],["ٱلزَّٰرِعُونَ","Yang berkembang"]]],"5044":["(Kalau Kami kehendaki, benar-benar Kami jadikan dia kering lagi keropos) maksudnya, tumbuhan yang kalian tanam itu menjadi kering tak ada biji dan isinya (maka jadilah kalian) pada asalnya lafal Zhaltum adalah Zhaliltum, lalu huruf Lam yang berharakat dibuang demi untuk meringankan bunyi sehingga jadilah Zhaltum, yakni jadilah kalian pada keesokan harinya (heran tercengang) keheranan karena melihat hal tersebut. Lafal Tafakkahuuna asalnya Tatafakkahuuna, lalu salah satu dari kedua huruf Ta dibuang sehingga menjadi Tafakkahuuna.",[["لَوْ","Jika"],["نَشَآءُ","Kami berkehendak"],["لَجَعَلْنَـٰهُ","Kami (akan) pasti, berjaya"],["حُطَـٰمًۭا","serpihan"],["فَظَلْتُمْ","maka kamu akan kekal"],["تَفَكَّهُونَ","tertanya-tanya"]]],"5045":["(-Seraya mengatakan-, \"Sesungguhnya kami benar-benar menderita kerugian,) biaya yang telah kami tanamkan buat tanaman kami.",[["إِنَّا","Sesungguhnya kami"],["لَمُغْرَمُونَ","pastinya sarat dengan hutang"]]],"5046":["(Bahkan kami menjadi orang-orang yang tidak mendapat hasil apa-apa\") kami tidak mendapatkan rezeki apa-apa.",[["بَلْ","Bahkan"],["نَحْنُ","kita"],["مَحْرُومُونَ","(adalah) dilucutkan"]]],"5047":["(Maka terangkanlah kepada-Ku tentang air yang kalian minum.)",[["أَفَرَءَيْتُمُ","Adakah kamu melihat"],["ٱلْمَآءَ","air itu"],["ٱلَّذِى","yang"],["تَشْرَبُونَ","kamu minum"]]],"5048":["(Kaliankah yang menurunkannya dari awan) lafal Muzni adalah bentuk jamak dari lafal Muznatun, artinya awan yang membawa air hujan (ataukah Kami yang menurunkannya).",[["ءَأَنتُمْ","Adakah kamu"],["أَنزَلْتُمُوهُ","yang menurunkannya"],["مِنَ","daripada"],["ٱلْمُزْنِ","awan hujan"],["أَمْ","atau"],["نَحْنُ","Kami"],["ٱلْمُنزِلُونَ","(adalah) yang diutus"]]],"5049":["(Kalau Kami kehendaki niscaya Kami jadikan dia asin) berasa asin hingga tidak dapat diminum (maka mengapa tidak) kenapa tidak (kalian bersyukur?",[["لَوْ","Jika"],["نَشَآءُ","Kami berkehendak"],["جَعَلْنَـٰهُ","Kami (boleh) berjaya"],["أُجَاجًۭا","masin"],["فَلَوْلَا","maka mengapa kamu tidak bersyukur"],["تَشْكُرُونَ","maka mengapa kamu tidak bersyukur"]]],"5050":["(Maka terangkanlah kepada-Ku tentang api yang kalian nyalakan) yang kalian keluarkan dari gosokan-gosokan kayu yang hijau.",[["أَفَرَءَيْتُمُ","Adakah kamu melihat"],["ٱلنَّارَ","neraka"],["ٱلَّتِى","yang"],["تُورُونَ","kamu menyala"]]],"5051":["(Kaliankah yang menjadikan kayu itu) yang dimaksud adalah pohon Marakh dan pohon 'Affar yang kayunya dapat dijadikan sebagai pemantik api (atau Kamikah yang menjadikannya?).",[["ءَأَنتُمْ","Adakah kamu"],["أَنشَأْتُمْ","yang menghasilkan"],["شَجَرَتَهَآ","pokoknya"],["أَمْ","atau"],["نَحْنُ","Kami"],["ٱلْمُنشِـُٔونَ","(adalah) Pengeluar"]]],"5052":["(Kami menjadikan api itu untuk peringatan) yakni mengingatkan tentang neraka Jahanam (dan sebagai bekal) dalam perjalanan (bagi orang-orang yang mengadakan perjalanan) diambil dari lafal Aqwal Qaumu, yakni kaum itu kini berada di padang pasir yang tandus, tiada tumbuh-tumbuhan dan air padanya.",[["نَحْنُ","Kami"],["جَعَلْنَـٰهَا","telah berjaya"],["تَذْكِرَةًۭ","peringatan"],["وَمَتَـٰعًۭا","dan peruntukan"],["لِّلْمُقْوِينَ","untuk pengembara di padang pasir"]]],"5053":["(Maka bertasbihlah) artinya, Maha Sucikanlah (dengan menyebut nama) huruf Ba di sini adalah Zaidah (Rabbmu Yang Maha Besar) yakni Allah Yang Maha Besar.",[["فَسَبِّحْ","Maka bertasbihlah"],["بِٱسْمِ","(nama)"],["رَبِّكَ","Tuhanmu"],["ٱلْعَظِيمِ","yang Maha Agung"]]],"5054":["(Maka Aku bersumpah) huruf Laa di sini adalah Zaidah (dengan nama tempat-tempat terbenamnya bintang-bintang) tempat-tempat bintang-bintang tenggelam.",[["۞ فَلَآ","Tetapi tidak"],["أُقْسِمُ","aku bersumpah"],["بِمَوَٰقِعِ","dengan menetapkan"],["ٱلنُّجُومِ","(dari) bintang"]]],"5055":["(Sesungguhnya sumpah itu) sumpah dengan memakai namanya ita (adalah sumpah yang besar kalau kalian mengetahui) jika kalian termasuk orang-orang yang memiliki ilmu pengetahuan niscaya kalian mengetahui besarnya sumpah ini.",[["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["لَقَسَمٌۭ","(adalah) sesungguhnya sumpah"],["لَّوْ","jika"],["تَعْلَمُونَ","kamu tahu"],["عَظِيمٌ","yang besar"]]],"5056":["(Sesungguhnya ini) yakni yang dibacakan kepada kalian (adalah Alquran yang sangat mulia).",[["إِنَّهُۥ","Sesungguhnya, ia"],["لَقُرْءَانٌۭ","(adalah) sesungguhnya Al-Quran"],["كَرِيمٌۭ","mulia"]]],"5057":["(Pada Kitab) yang tertulis dalam Kitab (yang terpelihara) yang dijaga, maksudnya Mushhaf Alquran.",[["فِى","Dalam"],["كِتَـٰبٍۢ","sebuah Buku"],["مَّكْنُونٍۢ","terjaga dengan baik"]]],"5058":["(Tidak menyentuhnya) adalah kalimat berita, tetapi mengandung makna perintah, yakni jangan menyentuhnya (kecuali orang-orang yang telah bersuci) yakni orang-orang yang telah menyucikan dirinya dari hadas-hadas.",[["لَّا","tiada"],["يَمَسُّهُۥٓ","menyentuhnya"],["إِلَّا","kecuali"],["ٱلْمُطَهَّرُونَ","yang disucikan"]]],"5059":["(Diturunkan) ia diturunkan (dari Rabb semesta alam).",[["تَنزِيلٌۭ","Sebuah Wahyu"],["مِّن","daripada"],["رَّبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"5060":["(Maka apakah terhadap firman ini) Alquran ini (kalian menganggapnya remeh?) meremehkan dan mendustakannya",[["أَفَبِهَـٰذَا","Kemudian adakah ini"],["ٱلْحَدِيثِ","kenyataan"],["أَنتُم","bahawa kamu"],["مُّدْهِنُونَ","(adalah) acuh tak acuh"]]],"5061":["(Kalian menjadikan rezeki yang diberikan kepada kalian) yaitu berupa air hujan; kalian membalasnya (dengan mendustakan) rezeki yang diberikan Allah kepada kalian berupa air hujan itu karena kalian telah mengatakan, \"Kami di beri hujan oleh bintang anu\".",[["وَتَجْعَلُونَ","Dan kamu buat"],["رِزْقَكُمْ","rezeki kamu"],["أَنَّكُمْ","bahawa kamu"],["تُكَذِّبُونَ","menafikan"]]],"5062":["(Maka mengapa tidak) kenapa tidak (sewaktu nyawa sampai) pada saat menjelang kematian (di tenggorokan) yakni pada saat nyawa sampai pada kerongkongan.",[["فَلَوْلَآ","Lalu kenapa tidak"],["إِذَا","apabila"],["بَلَغَتِ","ia sampai"],["ٱلْحُلْقُومَ","tekak"]]],"5063":["(Padahal kalian) hai orang-orang yang menghadiri saat kematian (ketika itu melihat) kapada orang yang sedang mengalami kematiannya.",[["وَأَنتُمْ","Dan kamu"],["حِينَئِذٍۢ","(pada) masa itu"],["تَنظُرُونَ","lihatlah"]]],"5064":["(Dan Kami lebih dekat kepadanya daripada kalian) yakni melalui pengetahuan-Ku. (Tetapi kalian tidak melihat) kalian tidak mengetahui hal tersebut, lafal Tubshiruuna ini diambil dari lafal Bashiirah yang artinya melihat.",[["وَنَحْنُ","Dan Kami"],["أَقْرَبُ","(ada) lebih dekat"],["إِلَيْهِ","kepadanya"],["مِنكُمْ","daripada kamu"],["وَلَـٰكِن","tetapi"],["لَّا","kamu (tidak) nampak"],["تُبْصِرُونَ","kamu (tidak) nampak"]]],"5065":["(Maka mengapa tidak) kenapa tidak (jika kalian merasa tidak akan dibalas) merasa tidak akan dibangkitkan nanti, sesuai dengan dugaan kalian.",[["فَلَوْلَآ","Lalu kenapa tidak"],["إِن","jika"],["كُنتُمْ","kamu"],["غَيْرَ","tidak"],["مَدِينِينَ","untuk dibalas"]]],"5066":["(Kalian mengembalikan nyawa itu) maksudnya, mengembalikannya ke dalam tubuh kalian sendiri sesudah nyawa itu mencapai kerongkongan? (jika kalian adalah orang-orang yang benar) di dalam pengakuan kalian itu. Lafal Falaulaa yang kedua mengukuhkan makna lafal Laulaa pertama. Sedangkan lafal Idzaa yang terkandung di dalam lafal Hiinaidzin menjadi Zharaf bagi lafal Tarji'uuna yang bergantung kepadanya kedua Syarat tersebut. Makna ayat, mengapa kalian tidak mengembalikan nyawa kalian sendiri ke dalam tubuh kalian, jika kalian tidak mempercayai adanya hari berbangkit dan kalian benar-benar meniadakannya? Yakni hendaknya kalian meniadakan pula kematian itu sebagai pengganti dari ketidakpercayaan kalian kepada adanya hari berbangkit.",[["تَرْجِعُونَهَآ","Bawa balik"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"5067":["(Adapun jika dia) orang yang mati itu (termasuk orang-orang yang didekatkan-kepada Allah-).",[["فَأَمَّآ","Kemudian"],["إِن","jika"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلْمُقَرَّبِينَ","yang dibawa dekat"]]],"5068":["(Maka dia memperoleh ketenteraman) dia mendapatkan ketenangan (dan rezeki) yang baik (serta surga yang penuh dengan kenikmatan) apakah jawab ini bagi lafal Amma ataukah bagi In, ataukah menjadi Jawab bagi kedua-duanya?, sehubungan dengan masalah ini ada beberapa pendapat.",[["فَرَوْحٌۭ","Kemudian berehat"],["وَرَيْحَانٌۭ","dan limpah kurnia"],["وَجَنَّتُ","dan sebuah Taman"],["نَعِيمٍۢ","(dari) Keseronokan"]]],"5069":["(Dan adapun jika dia termasuk golongan kanan).",[["وَأَمَّآ","Dan"],["إِن","jika"],["كَانَ","dia adalah"],["مِنْ","daripada"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلْيَمِينِ","(dari) hak"]]],"5070":["(Maka keselamatan bagi kamu) yakni baginya keselamatan dari siksaan (karena kamu termasuk golongan kanan) karena dia termasuk di antara mereka.",[["فَسَلَـٰمٌۭ","Kemudian, damai"],["لَّكَ","bagi kamu"],["مِنْ","[dari]"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلْيَمِينِ","(dari) hak"]]],"5071":["(Dan adapun jika dia termasuk golongan orang-orang yang mendustakan lagi sesat).",[["وَأَمَّآ","Tetapi"],["إِن","jika"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلْمُكَذِّبِينَ","orang yang menafikan"],["ٱلضَّآلِّينَ","yang sesat"]]],"5072":["(Maka dia mendapat hidangan air yang sangat panas).",[["فَنُزُلٌۭ","Kemudian, keramahan"],["مِّنْ","daripada"],["حَمِيمٍۢ","(the) air mendidih"]]],"5073":["(Dan dibakar di dalam neraka Jahim).",[["وَتَصْلِيَةُ","Dan terbakar"],["جَحِيمٍ","(dalam) api Neraka"]]],"5074":["(Sesungguhnya yang disebutkan ini adalah suatu keyakinan yang benar) lafal Haqqul Yaqiin termasuk ungkapan dengan memakai cara mengidhafahkan Maushuf kepada sifatnya.",[["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَهُوَ","pasti, ia"],["حَقُّ","(adalah) kebenaran"],["ٱلْيَقِينِ","pasti"]]],"5075":["(Maka bertasbihlah kamu dengan menyebut nama Rabbmu Yang Maha Besar) penafsirannya sebagaimana yang telah lalu.",[["فَسَبِّحْ","Maka bertasbihlah"],["بِٱسْمِ","(nama)"],["رَبِّكَ","Tuhanmu"],["ٱلْعَظِيمِ","yang Maha Agung"]]],"5076":["(Semua yang berada di langit dan yang berada di bumi bertasbih kepada Allah) memahasucikan-Nya dari semua yang tidak layak bagi-Nya. Huruf Lam adalah Zaidah, dan dipakai lafal Ma bukannya Man karena memandang dari segi mayoritasnya. (Dan Dia-lah Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["سَبَّحَ","Memuliakan"],["لِلَّهِ","[kepada] Allah"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["وَهُوَ","dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5077":["(Kepunyaan-Nyalah kerajaan langit dan bumi, Dia menghidupkan) melalui penciptaan (dan mematikan) sesudah itu (dan Dia Maha Kuasa atas segala sesuatu).",[["لَهُۥ","Untuk Dia"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["يُحْىِۦ","Dia memberi kehidupan"],["وَيُمِيتُ ۖ","dan menyebabkan kematian"],["وَهُوَ","dan Dia"],["عَلَىٰ","(sudah) tamat"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["قَدِيرٌ","Maha Berkuasa"]]],"5078":["(Dialah Yang Awal) sebelum segala sesuatu ada, keawalan Dia tidak ada permulaannya (dan Yang Akhir) sesudah segala sesuatu berakhir, keakhiran-Nya tanpa batas (dan Yang Maha Zahir) melalui bukti-bukti yang menunjukkan kezahiran Nya (dan Yang Batin) yakni tidak dapat dilihat dan ditemukan oleh panca indra (dan Dia Maha Mengetahui atas segala sesuatu).",[["هُوَ","Dia"],["ٱلْأَوَّلُ","(ialah) Yang Pertama"],["وَٱلْـَٔاخِرُ","dan Yang Terakhir"],["وَٱلظَّـٰهِرُ","dan Yang Zahir"],["وَٱلْبَاطِنُ ۖ","dan Yang Tidak Nampak"],["وَهُوَ","dan Dia"],["بِكُلِّ","(adalah) setiap"],["شَىْءٍ","perkara"],["عَلِيمٌ","Maha Mengetahui"]]],"5079":["(Dialah yang menciptakan langit dan bumi dalam enam hari) yakni sebagaimana hari-hari di dunia; dimulai dari hari Ahad dan berakhir pada hari Jumat. (Kemudian Dia bersemayam/berkuasa di atas Arasy) di atas Al Kursiy sesuai dengan keagungan dan kebesaran-Nya (Dia mengetahui apa yang masuk) semua yang masuk (ke dalam bumi) seperti air hujan dan orang-orang yang mati (dan apa yang keluar daripadanya) seperti tumbuh-tumbuhan dan mineral (dan apa yang turun dari langit) seperti rahmat/hujan dan azab (dan apa yang naik kepada-Nya) seperti amal-amal saleh dan amal-amal yang buruk. (Dan Dia bersama kalian) melalui ilmu-Nya (di mana saja kalian berada. Dan Allah Maha Melihat apa yang kalian kerjakan).",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["فِى","dalam"],["سِتَّةِ","enam"],["أَيَّامٍۢ","tempoh"],["ثُمَّ","kemudian"],["ٱسْتَوَىٰ","Dia bangkit"],["عَلَى","atas"],["ٱلْعَرْشِ ۚ","takhta"],["يَعْلَمُ","Dia tahu"],["مَا","apa"],["يَلِجُ","menembusi"],["فِى","dalam (ke)"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan apa"],["يَخْرُجُ","keluar"],["مِنْهَا","daripadanya"],["وَمَا","dan apa"],["يَنزِلُ","turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","syurga itu"],["وَمَا","dan apa"],["يَعْرُجُ","naik"],["فِيهَا ۖ","di dalamnya"],["وَهُوَ","dan Dia"],["مَعَكُمْ","(ada) bersama kamu"],["أَيْنَ","di mana sahaja"],["مَا","di mana sahaja"],["كُنتُمْ ۚ","kamu"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌۭ","(ialah) Maha Melihat"]]],"5080":["(Kepunyaan-Nyalah kerajaan langit dan bumi. Dan kepada Allah-lah dikembalikan segala sesuatu) yakni semua yang ada ini.",[["لَّهُۥ","Untuk Dia"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَإِلَى","dan kepada"],["ٱللَّهِ","Allah"],["تُرْجَعُ","akan dikembalikan"],["ٱلْأُمُورُ","perkara-perkara"]]],"5081":["(Dialah Yang memasukkan malam) yang memasukkannya (ke dalam siang) sehingga bertambah panjanglah waktu siang dan berkuranglah waktu malam (dan memasukkan siang ke dalam malam) sehingga waktu malam bertambah panjang sedangkan waktu siang semakin berkurang. (Dan Dia Maha Mengetahui segala isi hati) maksudnya, Dia Maha Mengetahui akan rahasia-rahasia dan keyakinan-keyakinan yang terkandung di dalam kalbu.",[["يُولِجُ","Dia bergabung"],["ٱلَّيْلَ","malam"],["فِى","ke dalam"],["ٱلنَّهَارِ","hari itu"],["وَيُولِجُ","dan Dia bergabung"],["ٱلنَّهَارَ","hari itu"],["فِى","ke dalam"],["ٱلَّيْلِ ۚ","malam"],["وَهُوَ","dan Dia"],["عَلِيمٌۢ","Maha Mengetahui"],["بِذَاتِ","daripada apa yang ada di dalam payudara"],["ٱلصُّدُورِ","daripada apa yang ada di dalam payudara"]]],"5082":["(Berimanlah kalian) artinya, tetaplah kalian beriman (kepada Allah dan Rasul-Nya dan nafkahkanlah) di jalan Allah (sebagian dari harta kalian yang Allah telah menjadikan kalian menguasainya) yakni dari harta orang-orang yang sebelum kalian dan kelak Dia akan menguasakannya kepada orang-orang yang sesudah kalian. Ayat ini diturunkan sewaktu perang 'Ursah atau dikenal dengan nama perang Tabuk. (Maka orang-orang yang beriman di antara kalian dan menafkahkan hartanya) ayat ini mengisyaratkan kepada apa yang telah dilakukan oleh sahabat Usman r.a. (mereka akan memperoleh pahala yang besar).",[["ءَامِنُوا۟","Percayalah"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["وَأَنفِقُوا۟","dan berbelanja"],["مِمَّا","tentang apa"],["جَعَلَكُم","Dia telah menjadikan kamu"],["مُّسْتَخْلَفِينَ","pemegang amanah"],["فِيهِ ۖ","di dalamnya"],["فَٱلَّذِينَ","Dan mereka"],["ءَامَنُوا۟","yang beriman"],["مِنكُمْ","antara kamu"],["وَأَنفَقُوا۟","dan berbelanja"],["لَهُمْ","bagi mereka"],["أَجْرٌۭ","(adalah) ganjaran"],["كَبِيرٌۭ","yang besar"]]],"5083":["(Dan mengapa kalian tidak beriman) khitab pada ayat ini ditujukan kepada orang-orang kafir, yakni tidak ada halangan bagi kalian untuk beriman (kepada Allah padahal Rasul menyeru kalian supaya kalian beriman kepada Rabb kalian. Dan sesungguhnya Dia telah mengambil) ia dapat dibaca Ukhidza dan Akhadza, kalau dibaca Akhadza maka lafal sesudahnya dibaca Nashab (perjanjian kalian) terhadap-Nya; yakni Allah telah mengambil janji itu di alam arwah, yaitu ketika Allah mengambil kesaksian terhadap jiwa mereka, Allah adalah Rabb mereka, sebagaimana yang diungkapkan di dalam ayat lain, yaitu firman-Nya, \"Bukankah Aku ini Rabb kalian?\" Mereka menjawab, \"Betul (Engkau Rabb kami), kami menjadi saksi\". (Q.S. Al A'raf, 172) (Jika kalian adalah orang-orang yang beriman) maksudnya, jika kalian hendak beriman kepada-Nya maka bersegeralah iman kepada-Nya.",[["وَمَا","Dan apa"],["لَكُمْ","(adalah) untuk kamu"],["لَا","(itu) tidak"],["تُؤْمِنُونَ","kamu beriman"],["بِٱللَّهِ ۙ","kepada Allah"],["وَٱلرَّسُولُ","manakala Rasul"],["يَدْعُوكُمْ","memanggil kamu"],["لِتُؤْمِنُوا۟","yang kamu percayai"],["بِرَبِّكُمْ","pada Tuhanmu"],["وَقَدْ","dan sesungguhnya"],["أَخَذَ","Dia telah mengambil"],["مِيثَـٰقَكُمْ","perjanjian kamu"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"5084":["(Dialah yang menurunkan kepada hamba-Nya ayat-ayat yang terang) ayat-ayat Alquran yang jelas (supaya Dia mengeluarkan kalian dari kegelapan) dari kekafiran (kepada cahaya) kepada keimanan. (Dan sesungguhnya Allah benar-benar terhadap kalian) karena Dia telah mengeluarkan kalian dari kekafiran kepada iman (Maha Penyantun lagi Maha Penyayang).",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["يُنَزِّلُ","menghantar turun"],["عَلَىٰ","ke atas"],["عَبْدِهِۦٓ","hambanya"],["ءَايَـٰتٍۭ","ayat-ayat"],["بَيِّنَـٰتٍۢ","yang nyata"],["لِّيُخْرِجَكُم","supaya Dia mengeluarkan kamu"],["مِّنَ","daripada"],["ٱلظُّلُمَـٰتِ","kegelapan[es]"],["إِلَى","ke dalam"],["ٱلنُّورِ ۚ","cahaya itu"],["وَإِنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["بِكُمْ","kepada kamu"],["لَرَءُوفٌۭ","(adalah) Maha Pemurah"],["رَّحِيمٌۭ","(yang) Maha Penyayang"]]],"5085":["(Dan mengapa kalian) sesudah beriman (tidak) lafal Allaa pada asalnya terdiri dari An dan Laa kemudian keduanya diidgamkan menjadi satu sehingga jadilah Allaa (menafkahkan sebagian harta kalian di jalan Allah, padahal Allah-lah yang mempusakai mempunyai langit dan bumi) berikut semua yang ada pada keduanya; maka sampailah kepada-Nya harta kalian tanpa membawa sedikit pun pahala infak kalian, berbeda halnya seandainya kalian menafkahkannya di jalan Allah, maka kalian akan mendapatkan pahala di sisi-Nya. (Tidak sama di antara kalian orang yang menafkahkan hartanya sebelum penaklukan) kota Mekah (dan ikut berperang sebelumnya -. Mereka lebih tinggi derajatnya daripada orang-orang yang menafkahkan hartanya dan berperang sesudah itu. Kepada masing-masing) dari dua golongan itu. Menurut suatu qiraat ia dibaca Kullun karena dianggap sebagai Mubtada (Allah telah menjanjikan balasan yang lebih baik) yaitu surga (Dan Allah mengetahui apa yang kalian kerjakan) maka kelak Dia akan membalasnya untuk kalian.",[["وَمَا","Dan apa"],["لَكُمْ","(adalah) untuk kamu"],["أَلَّا","itu tidak"],["تُنفِقُوا۟","kamu belanjakan"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["وَلِلَّهِ","sedangkan untuk Allah"],["مِيرَٰثُ","(adalah) warisan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["لَا","Tidak"],["يَسْتَوِى","adalah sama"],["مِنكُم","antara kamu"],["مَّنْ","(mereka) yang"],["أَنفَقَ","dibelanjakan"],["مِن","sebelum"],["قَبْلِ","sebelum"],["ٱلْفَتْحِ","kemenangan itu"],["وَقَـٰتَلَ ۚ","dan berperang"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["أَعْظَمُ","(adalah) lebih besar"],["دَرَجَةًۭ","(dalam) ijazah"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["أَنفَقُوا۟","dibelanjakan"],["مِنۢ","selepas itu"],["بَعْدُ","selepas itu"],["وَقَـٰتَلُوا۟ ۚ","dan berperang"],["وَكُلًّۭا","Tetapi kepada semua"],["وَعَدَ","Allah dah janji"],["ٱللَّهُ","Allah dah janji"],["ٱلْحُسْنَىٰ ۚ","yang terbaik"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["خَبِيرٌۭ","(adalah) Maha Mengetahui"]]],"5086":["(Siapakah yang mau meminjamkan kepada Allah) dengan cara menafkahkan hartanya di jalan Allah (pinjaman yang baik) seumpamanya hartanya itu dinafkahkan demi karena Allah (maka Allah akan melipatgandakan balasan pinjaman itu) menurut suatu qiraat dibaca Fayudha' 'ifahu (untuknya) mulai dari sepuluh kali lipat hingga tujuh ratus kali lipat, sebagaimana keterangan yang telah disebutkan di dalam surah Al Baqarah (dan baginya) di samping pahala yang dilipatgandakan itu (pahala yang banyak) juga disertai mendapat keridaan dari Allah dan disambut dengan baik.",[["مَّن","siapakah"],["ذَا","orang yang"],["ٱلَّذِى","orang yang"],["يُقْرِضُ","akan pinjaman"],["ٱللَّهَ","(kepada) Allah"],["قَرْضًا","pinjaman"],["حَسَنًۭا","dengan baik"],["فَيُضَـٰعِفَهُۥ","maka Dia akan melipatgandakannya"],["لَهُۥ","baginya"],["وَلَهُۥٓ","dan untuk dia"],["أَجْرٌۭ","(adalah) ganjaran"],["كَرِيمٌۭ","mulia"]]],"5087":["Ingatlah (pada hari ketika kamu melihat orang-orang mukmin laki-laki dan perempuan, sedangkan cahaya mereka bersinar di hadapan mereka) artinya bersinar menerangi bagian depan mereka (dan) cahaya itu pun (bersinar di sebelah kanan mereka) kemudian dikatakan kepada mereka, (\"Pada hari ini ada berita gembira untuk kalian, yaitu surga-surga) masuklah kalian ke dalam surga-surga itu (yang di bawahnya mengalir sungai-sungai, yang kalian kekal di dalamnya. Itulah keberuntungan yang besar\").",[["يَوْمَ","(Pada) Hari"],["تَرَى","kamu akan melihat"],["ٱلْمُؤْمِنِينَ","lelaki yang beriman"],["وَٱلْمُؤْمِنَـٰتِ","dan wanita yang beriman"],["يَسْعَىٰ","berlari"],["نُورُهُم","cahaya mereka"],["بَيْنَ","sebelum mereka"],["أَيْدِيهِمْ","sebelum mereka"],["وَبِأَيْمَـٰنِهِم","dan di sebelah kanan mereka"],["بُشْرَىٰكُمُ","Berita gembira untuk kamu"],["ٱلْيَوْمَ","Hari ini"],["جَنَّـٰتٌۭ","taman-taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","kekal selama-lamanya"],["فِيهَا ۚ","di dalamnya"],["ذَٰلِكَ","Itu"],["هُوَ","[ia] (ialah)"],["ٱلْفَوْزُ","kejayaan itu"],["ٱلْعَظِيمُ","yang hebat"]]],"5088":["(Pada hari ketika orang-orang munafik laki-laki dan perempuan berkata kepada orang-orang yang beriman, \"Perhatikanlah kami) lihatlah kami. Menurut suatu qiraat dibaca Anzhiruunaa, tunggulah kami (supaya kami dapat mengambil) maksudnya supaya kami kebagian cahaya dan sinar (sebagian dari cahaya kalian.\" Dikatakan) kepada mereka dengan nada yang memperolok-olokkan mereka, (\"Kembalilah kalian ke belakang dan carilah sendiri cahaya untuk kalian\") mereka mundur. (Lalu diadakan di antara mereka) dan antara orang-orang yang beriman (dinding) menurut suatu pendapat dinding itu dinamakan Al A'raaf (yang mempunyai pintu. Di sebelah dalamnya ada rahmat) ada bagian yang menghadap orang-orang yang beriman (dan di sebelah luarnya) ada bagian yang menghadap orang-orang munafik (dari situ ada azab).",[["يَوْمَ","(Pada) Hari"],["يَقُولُ","akan berkata"],["ٱلْمُنَـٰفِقُونَ","lelaki munafik"],["وَٱلْمُنَـٰفِقَـٰتُ","dan perempuan-perempuan munafik"],["لِلَّذِينَ","kepada mereka yang"],["ءَامَنُوا۟","beriman"],["ٱنظُرُونَا","Tunggu kami"],["نَقْتَبِسْ","kita mungkin memperoleh"],["مِن","daripada"],["نُّورِكُمْ","cahaya kamu"],["قِيلَ","Ia akan dikatakan"],["ٱرْجِعُوا۟","pergi balik"],["وَرَآءَكُمْ","belakang kamu"],["فَٱلْتَمِسُوا۟","dan cari"],["نُورًۭا","ringan"],["فَضُرِبَ","Kemudian akan diletakkan"],["بَيْنَهُم","antara mereka"],["بِسُورٍۢ","sebuah dinding"],["لَّهُۥ","baginya"],["بَابٌۢ","sebuah pintu pagar"],["بَاطِنُهُۥ","dalamannya"],["فِيهِ","di dalamnya"],["ٱلرَّحْمَةُ","(adalah) belas kasihan"],["وَظَـٰهِرُهُۥ","tetapi luarannya"],["مِن","menghadap ke arah [itu]"],["قِبَلِهِ","menghadap ke arah [itu]"],["ٱلْعَذَابُ","azab"]]],"5089":["(Orang-orang munafik itu memanggil mereka orang-orang mukmin, \"Bukankah kami dahulu bersama-sama kalian?\") dalam ketaatan kepada Allah. (mereka menjawab, \"Benar, tetapi kalian mencelakakan diri kalian sendiri) disebabkan kemunafikan kalian (dan kalian selalu mengincar) kehancuran orang-orang mukmin (dan kalian ragu-ragu) masih ragu terhadap agama Islam (serta kalian ditipu oleh angan-angan kosong) yakni ketamakan (sehingga datanglah ketetapan Allah) yaitu kematian (dan kalian telah ditipu terhadap Allah oleh yang amat penipu) yakni oleh setan.",[["يُنَادُونَهُمْ","Mereka akan memanggil mereka"],["أَلَمْ","tidak"],["نَكُن","kita"],["مَّعَكُمْ ۖ","bersama kamu"],["قَالُوا۟","Mereka akan berkata"],["بَلَىٰ","ya"],["وَلَـٰكِنَّكُمْ","tapi kamu"],["فَتَنتُمْ","membawa kepada godaan"],["أَنفُسَكُمْ","kamu sendiri"],["وَتَرَبَّصْتُمْ","dan kamu menunggu"],["وَٱرْتَبْتُمْ","dan kamu ragu-ragu"],["وَغَرَّتْكُمُ","dan menipu kamu"],["ٱلْأَمَانِىُّ","angan-angan"],["حَتَّىٰ","sehingga"],["جَآءَ","datang"],["أَمْرُ","(the) Perintah"],["ٱللَّهِ","(milik) Allah"],["وَغَرَّكُم","Dan menipu kamu"],["بِٱللَّهِ","tentang Allah"],["ٱلْغَرُورُ","si penipu"]]],"5090":["(Maka pada hari ini tidak diterima) dapat dibaca Yu`khadzu dan Tu`khadzu (tebusan dari kalian dan tidak pula dari orang-orang kafir. Tempat kalian ialah neraka. Neraka itulah tempat yang layak buat kalian) tempat yang utama bagi kalian. (Dan neraka itu adalah seburuk-buruk tempat kembali\") tempat kembali yang paling buruk adalah neraka.",[["فَٱلْيَوْمَ","Jadi hari ini"],["لَا","tidak"],["يُؤْخَذُ","akan diterima"],["مِنكُمْ","daripada kamu"],["فِدْيَةٌۭ","sebarang wang tebusan"],["وَلَا","dan bukan"],["مِنَ","daripada"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟ ۚ","kufur"],["مَأْوَىٰكُمُ","tempat tinggal kamu"],["ٱلنَّارُ ۖ","(ialah) Api"],["هِىَ","ia (adalah)"],["مَوْلَىٰكُمْ ۖ","pelindungmu"],["وَبِئْسَ","dan celaka adalah"],["ٱلْمَصِيرُ","destinasi"]]],"5091":["(Belumkah datang) maksudnya apakah belum tiba saatnya (bagi orang-orang yang beriman) ayat ini diturunkan berkenaan dengan kelakuan para sahabat, yaitu sewaktu mereka banyak bergurau (untuk tunduk hati mereka mengingat Allah dan mengingat apa yang telah diturunkan kepada mereka) dapat dibaca Nazzala dan Nazala (berupa kebenaran) yakni Alquran (dan janganlah mereka) di'athafkan kepada lafal Takhsya'a (seperti orang-orang yang sebelumnya telah diturunkan Alkitab kepadanya) mereka adalah orang-orang Yahudi dan orang-orang Nasrani (kemudian berlalulah masa yang panjang atas mereka) yaitu zaman antara mereka dan nabi-nabi mereka telah berlalu sangat lama (lalu hati mereka menjadi keras) tidak lunak lagi untuk mengingat Allah. (Dan kebanyakan di antara mereka adalah orang-orang fasik).",[["۞ أَلَمْ","belum"],["يَأْنِ","tiba masanya"],["لِلَّذِينَ","bagi mereka yang"],["ءَامَنُوٓا۟","beriman"],["أَن","bahawa"],["تَخْشَعَ","menjadi rendah hati"],["قُلُوبُهُمْ","hati mereka"],["لِذِكْرِ","dengan mengingati Allah"],["ٱللَّهِ","dengan mengingati Allah"],["وَمَا","dan apa"],["نَزَلَ","telah turun"],["مِنَ","daripada"],["ٱلْحَقِّ","kebenaran"],["وَلَا","Dan tidak"],["يَكُونُوا۟","mereka menjadi"],["كَٱلَّذِينَ","seperti mereka yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab"],["مِن","sebelum"],["قَبْلُ","sebelum"],["فَطَالَ","(dan) telah berpanjangan"],["عَلَيْهِمُ","bagi mereka"],["ٱلْأَمَدُ","istilah tersebut"],["فَقَسَتْ","jadi keras"],["قُلُوبُهُمْ ۖ","hati mereka"],["وَكَثِيرٌۭ","dan banyak"],["مِّنْهُمْ","daripada mereka"],["فَـٰسِقُونَ","(adalah) durhaka"]]],"5092":["(Ketahuilah oleh kalian) khithab ayat ini ditujukan kepada orang-orang mukmin yang telah disebutkan di atas tadi (bahwa sesungguhnya Allah menghidupkan bumi sesudah matinya) dengan menumbuhkan tumbuh-tumbuhan padanya, demikianlah Allah menjadikan hati kalian untuk taat dan khusuk kembali dalam mengingat Allah. (Sesungguhnya Kami telah menjelaskan kepada kalian tanda-tanda) yang menunjukkan akan kekuasaan Kami terhadap hal ini dan hal-hal lainnya (supaya kalian memikirkannya).",[["ٱعْلَمُوٓا۟","Tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يُحْىِ","memberi kehidupan"],["ٱلْأَرْضَ","(ke) bumi"],["بَعْدَ","selepas"],["مَوْتِهَا ۚ","kematiannya"],["قَدْ","Sesungguhnya"],["بَيَّنَّا","Kami telah menjelaskan"],["لَكُمُ","kepada kamu"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لَعَلَّكُمْ","supaya kamu"],["تَعْقِلُونَ","faham"]]],"5093":["(Sesungguhnya orang-orang yang membenarkan, baik laki-laki) mushshaddiqiina berasal dari mashdar tashadduq, kemudian huruf ta diidghamkan kepada huruf shad sehingga jadilah mushshaddiqiina, bentuk asalnya adalah mutashaddiqiina (maupun perempuan) yang percaya kepada Allah dan Rasul-Nya. Menurut qiraat lain kedua lafal tersebut dibaca tanpa tasydid, sehingga bacaannya menjadi innal mushaddiqiina wal mushaddiqaati, karena dianggap berasal dari tashdiq, sehingga artinya menjadi: Sesungguhnya orang-orang yang beriman, baik laki-laki maupun perempuan (dan meminjamkan kepada Allah pinjaman yang baik) dhamir yang ada pada lafal `aqradhuu kembali pada laki-laki dan perempuan, karena memprioritaskan kaum laki-laki. Fi'il atau kata kerja di sini diathafkan kepada isim, yaitu kepada shilah alif dan lam, karena sesungguhnya lafal al-mushshaddiqiina wal mushshaddiqaati yang dimasuki alif dan lam sama kedudukannya dengan fi'il yang berada sesudah shilah. Disebutkannya lafal al-qardhu berikut sifatnya sesudah pengertian tashadduq, hal ini memberikan pengertian adanya ikatan di antara lafal-lafal tersebut. Atau dengan kata lain, bahwa orang-orang yang membenarkan Allah dan Rasul-Nya itu adalah orang-orang yang mau meminjamkan kepada Allah pinjaman yang baik (maka Allah akan melipatgandakan) menurut suatu qiraat dibaca yudha`'af dengan memakai tasydid pada huruf 'ainnya, artinya balasan pinjaman mereka itu akan dilipatgandakan pahalanya (kepada mereka; dan bagi mereka pahala yang banyak).",[["إِنَّ","Sesungguhnya"],["ٱلْمُصَّدِّقِينَ","lelaki yang bersedekah"],["وَٱلْمُصَّدِّقَـٰتِ","dan wanita yang bersedekah"],["وَأَقْرَضُوا۟","dan siapa yang memberi pinjaman"],["ٱللَّهَ","(kepada) Allah"],["قَرْضًا","pinjaman"],["حَسَنًۭا","dengan baik"],["يُضَـٰعَفُ","ia akan berlipat ganda"],["لَهُمْ","bagi mereka"],["وَلَهُمْ","dan untuk mereka"],["أَجْرٌۭ","(adalah) ganjaran"],["كَرِيمٌۭ","mulia"]]],"5094":["(Dan orang-orang yang beriman kepada Allah dan Rasul-Nya, mereka itu adalah orang-orang shiddiqin) orang-orang yang sangat beriman kepada Allah dan Rasul-Nya (dan orang-orang yang menjadi saksi di sisi Rabb mereka) atas kedustaan umat-umat yang terdahulu terhadap nabi-nabi mereka. (Bagi mereka pahala dan cahaya mereka. Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami) yang menunjukkan kepada keesaan Kami (mereka itulah penghuni-penghuni Jahim) yakni neraka.",[["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["بِٱللَّهِ","kepada Allah"],["وَرُسُلِهِۦٓ","dan Rasul-rasulNya"],["أُو۟لَـٰٓئِكَ","[itu]"],["هُمُ","mereka"],["ٱلصِّدِّيقُونَ ۖ","(adalah) orang-orang yang benar"],["وَٱلشُّهَدَآءُ","dan para syuhada"],["عِندَ","(ada) dengan"],["رَبِّهِمْ","Tuhan mereka"],["لَهُمْ","Untuk mereka"],["أَجْرُهُمْ","(ialah) pahala mereka"],["وَنُورُهُمْ ۖ","dan cahaya mereka"],["وَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوا۟","kufur"],["وَكَذَّبُوا۟","dan menafikan"],["بِـَٔايَـٰتِنَآ","Ayat Kami"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"5095":["(Ketahuilah, bahwa sesungguhnya kehidupan dunia itu hanyalah permainan dan suatu yang melalaikan, perhiasan) sebagai perhiasan (dan bermegah-megahan antara kalian serta berbangga-bangga tentang banyaknya harta dan anak) artinya, menyibukkan diri di dalamnya. Adapun mengenai ketaatan dan hal-hal yang membantu menuju kepadanya termasuk perkara-perkara akhirat (seperti) kehidupan dunia yang menyilaukan kalian dan kepunahannya sesudah itu bagaikan (hujan) bagaikan air hujan (yang membuat orang-orang yang bertani merasa kagum) merasa takjub (akan tanam-tanamannya) yang tumbuh disebabkan turunnya hujan itu (kemudian tanaman itu menjadi kering) lapuk dan kering (dan kamu lihat warnanya yang kuning itu kemudian menjadi hancur) menjadi keropos dan berjatuhan ditiup angin. (Dan di akhirat ada azab yang keras) bagi orang-orang yang lebih memilih keduniaan (dan ampunan dari Allah serta keridaan-Nya) bagi orang-orang yang lebih memilih akhirat daripada dunia. (Dan kehidupan dunia ini tidak lain) maksudnya bersenang-senang dalam dunia ini tiada lain (hanyalah kesenangan yang menipu).",[["ٱعْلَمُوٓا۟","Tahu"],["أَنَّمَا","bahawa"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا","dunia"],["لَعِبٌۭ","(adalah) bermain"],["وَلَهْوٌۭ","dan keseronokan"],["وَزِينَةٌۭ","dan perhiasan"],["وَتَفَاخُرٌۢ","dan bermegah-megah"],["بَيْنَكُمْ","antara kamu"],["وَتَكَاثُرٌۭ","dan persaingan semakin meningkat"],["فِى","daripada"],["ٱلْأَمْوَٰلِ","kekayaan itu"],["وَٱلْأَوْلَـٰدِ ۖ","dan kanak-kanak"],["كَمَثَلِ","seperti (contohnya)."],["غَيْثٍ","(dari) hujan"],["أَعْجَبَ","berkenan"],["ٱلْكُفَّارَ","penggarap"],["نَبَاتُهُۥ","pertumbuhannya"],["ثُمَّ","kemudian"],["يَهِيجُ","ia kering"],["فَتَرَىٰهُ","dan kamu melihatnya"],["مُصْفَرًّۭا","bertukar kuning"],["ثُمَّ","kemudian"],["يَكُونُ","menjadi"],["حُطَـٰمًۭا ۖ","serpihan"],["وَفِى","Dan dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["عَذَابٌۭ","(ialah) azab"],["شَدِيدٌۭ","teruk"],["وَمَغْفِرَةٌۭ","dan pengampunan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَرِضْوَٰنٌۭ ۚ","dan Keseronokan"],["وَمَا","Tetapi tidak"],["ٱلْحَيَوٰةُ","(ialah) kehidupan"],["ٱلدُّنْيَآ","dunia"],["إِلَّا","kecuali"],["مَتَـٰعُ","(the) kenikmatan"],["ٱلْغُرُورِ","(dari) khayalan"]]],"5096":["(Berlomba-lombalah kalian kepada ampunan dari Rabb kalian dan surga yang luasnya seluas langit dan bumi) seandainya jarak di antara keduanya dapat diukur; lafal al-'ardh artinya luas (yang disediakan bagi orang-orang yang beriman kepada Allah dan Rasul-Nya. Itulah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya. Dan Allah mempunyai karunia yang besar).",[["سَابِقُوٓا۟","Perlumbaan"],["إِلَىٰ","kepada"],["مَغْفِرَةٍۢ","(yang) pengampunan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["وَجَنَّةٍ","dan sebuah Taman"],["عَرْضُهَا","lebarnya"],["كَعَرْضِ","(adalah) seperti (the) lebar"],["ٱلسَّمَآءِ","(dari) syurga"],["وَٱلْأَرْضِ","dan bumi"],["أُعِدَّتْ","disediakan"],["لِلَّذِينَ","bagi mereka yang"],["ءَامَنُوا۟","beriman"],["بِٱللَّهِ","kepada Allah"],["وَرُسُلِهِۦ ۚ","dan Rasul-rasulNya"],["ذَٰلِكَ","Itu"],["فَضْلُ","(ialah) Bounty"],["ٱللَّهِ","(milik) Allah"],["يُؤْتِيهِ","Dia memberi"],["مَن","(kepada) siapa"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["ذُو","(ialah) Pemilik Karunia"],["ٱلْفَضْلِ","(ialah) Pemilik Karunia"],["ٱلْعَظِيمِ","yang Agung"]]],"5097":["(Tiada suatu bencana pun yang menimpa di bumi) seperti kekeringan (dan tidak pula pada diri kalian sendiri) seperti sakit dan kematian anak (melainkan telah tertulis dalam Kitab) di Lohmahfuz (sebelum Kami menciptakannya) sebelum Kami menciptakan semuanya. Demikian pula mengenai hal yang menyangkut nikmat dikatakan seperti itu. (Sesungguhnya yang demikian itu adalah mudah bagi Allah).",[["مَآ","Tidak"],["أَصَابَ","mogok"],["مِن","sebarang"],["مُّصِيبَةٍۢ","bencana"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَا","dan bukan"],["فِىٓ","dalam"],["أَنفُسِكُمْ","kamu sendiri"],["إِلَّا","tetapi"],["فِى","dalam"],["كِتَـٰبٍۢ","a Daftar"],["مِّن","sebelum"],["قَبْلِ","sebelum"],["أَن","bahawa"],["نَّبْرَأَهَآ ۚ","Kami mewujudkannya"],["إِنَّ","Sesungguhnya"],["ذَٰلِكَ","bahawa"],["عَلَى","bagi"],["ٱللَّهِ","Allah"],["يَسِيرٌۭ","(adalah) mudah"]]],"5098":["(Supaya janganlah) lafal kay di sini menashabkan fi'il yang jatuh sesudahnya, maknanya sama dengan lafal an. Allah swt. menjelaskan yang demikian itu supaya janganlah (kalian berduka cita) bersedih hati (terhadap apa yang luput dari kalian, dan supaya kalian jangan terlalu gembira) artinya gembira yang dibarengi dengan rasa takabur, berbeda halnya dengan gembira yang dibarengi dengan rasa syukur atas nikmat (terhadap apa yang diberikan-Nya kepada kalian) jika lafal aataakum dibaca panjang berarti maknanya sama dengan lafal a`thaakum, artinya apa yang diberikan-Nya kepada kalian. Jika dibaca pendek, yaitu ataakum artinya, apa yang didatangkan-Nya kepada kalian. (Dan Allah tidak menyukai setiap orang yang sombong) dengan apa yang telah diberikan oleh Allah kepadanya (lagi membanggakan diri) membangga-banggakannya terhadap orang lain.",[["لِّكَيْلَا","Supaya kamu tidak boleh"],["تَأْسَوْا۟","bersedih"],["عَلَىٰ","atas"],["مَا","apa"],["فَاتَكُمْ","telah melarikan diri kamu"],["وَلَا","dan jangan"],["تَفْرَحُوا۟","bergembira"],["بِمَآ","pada apa"],["ءَاتَىٰكُمْ ۗ","Dia telah memberi kamu"],["وَٱللَّهُ","Dan Allah"],["لَا","tidak"],["يُحِبُّ","cinta"],["كُلَّ","setiap"],["مُخْتَالٍۢ","menipu diri sendiri"],["فَخُورٍ","sombong"]]],"5099":["(Orang-orang yang kikir) tidak mau menunaikan apa yang telah diwajibkan atas mereka (dan menyuruh manusia berbuat kikir) supaya jangan menunaikan kewajiban itu, maka bagi mereka ancaman yang keras dari Allah. (Dan barang siapa yang berpaling) dari menunaikan apa yang telah diwajibkan atasnya (maka sesungguhnya Allah Dialah) lafal huwa adalah dhamir fashl, sedangkan menurut suatu qiraat tanpa memakainya (Yang Maha Kaya) artinya tidak membutuhkan orang lain (lagi Maha Terpuji) terhadap kekasih-kekasih-Nya.",[["ٱلَّذِينَ","Orang yang"],["يَبْخَلُونَ","adalah kedekut"],["وَيَأْمُرُونَ","dan menyuruh"],["ٱلنَّاسَ","(pada) rakyat"],["بِٱلْبُخْلِ ۗ","kedekut"],["وَمَن","Dan sesiapa"],["يَتَوَلَّ","berpaling"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْغَنِىُّ","(adalah) Bebas daripada keperluan"],["ٱلْحَمِيدُ","yang Terpuji"]]],"5100":["(Sesungguhnya Kami telah mengutus rasul-rasul Kami) yaitu malaikat-malaikat-Nya kepada nabi-nabi (dengan membawa bukti-bukti yang nyata) hujah-hujah yang jelas dan akurat (dan telah Kami turunkan bersama mereka Alkitab) lafal Alkitab ini sekalipun bentuknya mufrad tetapi makna yang dimaksud adalah jamak, yakni al-kutub (dan neraca) yakni keadilan (supaya manusia dapat melaksanakan keadilan. Dan Kami ciptakan besi) maksudnya Kami keluarkan besi dari tempat-tempat penambangannya (yang padanya terdapat kekuatan yang hebat) yakni dapat dipakai sebagai alat untuk berperang (dan berbagai manfaat bagi manusia, dan supaya Allah mengetahui) supaya Allah menampilkan; lafal waliya'lamallaahu diathafkan pada lafal liyaquman-naaasu (siapa yang menolong-Nya) maksudnya siapakah yang menolong agama-Nya dengan memakai alat-alat perang yang terbuat dari besi dan lain-lainnya itu (dan rasul-rasul-Nya padahal Allah tidak dilihatnya) lafal bil-ghaibi menjadi hal atau kata keterangan keadaan dari dhamir ha yang terdapat pada lafal yanshuruhu. Yakni sekalipun Allah tidak terlihat oleh mereka di dunia ini. Ibnu Abbas r.a. memberikan penakwilannya, mereka menolong agama-Nya padahal mereka tidak melihat-Nya. (Sesungguhnya Allah Maha Kuat lagi Maha Perkasa) artinya Dia tidak memerlukan pertolongan siapa pun, akan tetapi perbuatan itu manfaatnya akan dirasakan sendiri oleh orang yang mengerjakannya.",[["لَقَدْ","Sungguh"],["أَرْسَلْنَا","Kami utus"],["رُسُلَنَا","Rasul-rasul Kami"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["وَأَنزَلْنَا","dan Kami turunkan"],["مَعَهُمُ","bersama mereka"],["ٱلْكِتَـٰبَ","Kitab Suci"],["وَٱلْمِيزَانَ","dan Baki"],["لِيَقُومَ","yang boleh mendirikan"],["ٱلنَّاسُ","manusia"],["بِٱلْقِسْطِ ۖ","keadilan"],["وَأَنزَلْنَا","Dan Kami turunkan"],["ٱلْحَدِيدَ","besi"],["فِيهِ","di mana"],["بَأْسٌۭ","(adalah) kuasa"],["شَدِيدٌۭ","perkasa"],["وَمَنَـٰفِعُ","dan faedah"],["لِلنَّاسِ","untuk rakyat"],["وَلِيَعْلَمَ","dan supaya Allah nyatakan"],["ٱللَّهُ","dan supaya Allah nyatakan"],["مَن","(dia) siapa"],["يَنصُرُهُۥ","menolong Dia"],["وَرُسُلَهُۥ","dan Rasul-rasulNya"],["بِٱلْغَيْبِ ۚ","perkara ghaib"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["قَوِىٌّ","(adalah) Maha Kuat"],["عَزِيزٌۭ","Maha Perkasa"]]],"5101":["(Dan sesungguhnya Kami telah mengutus Nuh dan Ibrahim dan Kami jadikan pada keturunan keduanya kenabian dan Alkitab) yaitu kitab yang empat; Taurat, Injil, Zabur dan Al-Furqan. Kitab-kitab tersebut diturunkan kepada anak cucu Nabi Ibrahim (maka di antara mereka ada yang menerima petunjuk dan kebanyakan di antara mereka adalah orang-orang fasik).",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَا","Kami utus"],["نُوحًۭا","Nuh"],["وَإِبْرَٰهِيمَ","dan Ibrahim"],["وَجَعَلْنَا","dan Kami letakkan"],["فِى","dalam"],["ذُرِّيَّتِهِمَا","keturunan mereka"],["ٱلنُّبُوَّةَ","kenabian"],["وَٱلْكِتَـٰبَ ۖ","dan Kitab Suci"],["فَمِنْهُم","dan antara mereka"],["مُّهْتَدٍۢ ۖ","(adalah) seorang yang mendapat petunjuk"],["وَكَثِيرٌۭ","tetapi kebanyakannya"],["مِّنْهُمْ","daripada mereka"],["فَـٰسِقُونَ","(adalah) durhaka dengan durhaka"]]],"5102":["(Kemudian Kami iringi di belakang mereka dengan rasul-rasul Kami dan Kami iringi pula dengan Isa putra Maryam; dan Kami berikan kepadanya Injil dan Kami jadikan dalam hati orang-orang yang mengikutinya rasa santun dan kasih sayang. Dan kerahbaniyahan) yakni tidak mau kawin dan hidup membaktikan diri di dalam gereja-gereja (yang mereka ada-adakan) oleh diri mereka sendiri (padahal Kami tidak mewajibkannya kepada mereka) Kami tidak memerintahkan hal itu kepada mereka (tetapi) melainkan mereka mengerjakannya (untuk mencari keridaan) demi mencari kerelaan (Allah, lalu mereka tidak memeliharanya dengan pemeliharaan yang semestinya) karena kebanyakan di antara mereka meninggalkannya dan kafir kepada agama Nabi Isa, lalu mereka memasuki agama raja mereka. Akan tetapi masih banyak pula di antara mereka yang berpegang teguh kepada ajaran Nabi Isa, lalu mereka beriman kepada Nabi Muhammad. (Maka Kami berikan kepada orang-orang yang beriman) kepada Nabi Isa (di antara mereka pahalanya dan banyak di antara mereka orang-orang fasik).",[["ثُمَّ","Kemudian"],["قَفَّيْنَا","Kami utus"],["عَلَىٰٓ","pada"],["ءَاثَـٰرِهِم","jejak kaki mereka"],["بِرُسُلِنَا","Rasul-rasul Kami"],["وَقَفَّيْنَا","dan Kami mengikutinya"],["بِعِيسَى","dengan Isa"],["ٱبْنِ","nak"],["مَرْيَمَ","(dari) Maryam"],["وَءَاتَيْنَـٰهُ","dan Kami berikan kepadanya"],["ٱلْإِنجِيلَ","Injeel"],["وَجَعَلْنَا","Dan Kami letakkan"],["فِى","dalam"],["قُلُوبِ","(the) hati"],["ٱلَّذِينَ","orang yang"],["ٱتَّبَعُوهُ","mengikutinya"],["رَأْفَةًۭ","belas kasihan"],["وَرَحْمَةًۭ","dan belas kasihan"],["وَرَهْبَانِيَّةً","Tetapi monastik"],["ٱبْتَدَعُوهَا","mereka berinovasi"],["مَا","tidak"],["كَتَبْنَـٰهَا","Kami menetapkannya"],["عَلَيْهِمْ","untuk mereka"],["إِلَّا","sahaja"],["ٱبْتِغَآءَ","mencari"],["رِضْوَٰنِ","(the) kesenangan"],["ٱللَّهِ","(milik) Allah"],["فَمَا","tetapi tidak"],["رَعَوْهَا","mereka memerhatikannya"],["حَقَّ","(dengan) betul"],["رِعَايَتِهَا ۖ","ketaatan"],["فَـَٔاتَيْنَا","Maka Kami berikan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["مِنْهُمْ","antara mereka"],["أَجْرَهُمْ ۖ","ganjaran mereka"],["وَكَثِيرٌۭ","tetapi kebanyakannya"],["مِّنْهُمْ","daripada mereka"],["فَـٰسِقُونَ","(adalah) durhaka dengan durhaka"]]],"5103":["(Hai orang-orang yang beriman) kepada Nabi Isa (bertakwalah kepada Allah dan berimanlah kepada Rasul-Nya) kepada Nabi Muhammad saw. dan Nabi Isa (niscaya Allah memberikan kepada kalian dua bagian) dua kali bagian (dari rahmat-Nya) karena kalian telah beriman kepada dua nabi (dan menjadikan untuk kalian cahaya yang dengan cahaya itu kalian dapat berjalan) di atas shirath/jembatan (dan Dia mengampuni kalian. Dan Allah Maha Pengampun lagi Maha Penyayang).",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["ٱتَّقُوا۟","Takut"],["ٱللَّهَ","Allah"],["وَءَامِنُوا۟","dan beriman"],["بِرَسُولِهِۦ","dalam RasulNya"],["يُؤْتِكُمْ","Dia akan memberi kamu"],["كِفْلَيْنِ","bahagian berganda"],["مِن","daripada"],["رَّحْمَتِهِۦ","KerahimanNya"],["وَيَجْعَل","dan Dia akan menjadikan"],["لَّكُمْ","bagi kamu"],["نُورًۭا","sebuah cahaya"],["تَمْشُونَ","kamu akan berjalan"],["بِهِۦ","dengannya"],["وَيَغْفِرْ","dan Dia akan mengampuni"],["لَكُمْ ۚ","kamu"],["وَٱللَّهُ","Dan Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"5104":["(Supaya diketahui) maksudnya Allah menerangkan hal tersebut kepada kalian, supaya diketahui (oleh ahli kitab) Taurat yang tidak beriman kepada Nabi Muhammad (bahwa) an di sini adalah bentuk takhfif dari anna yang ditasydidkan, artinya bahwasanya mereka (mereka tiada mendapat sedikit pun akan karunia Allah) berbeda dengan apa yang mereka duga, yaitu bahwasanya mereka adalah kekasih-kekasih Allah dan orang-orang yang mendapat keridaan-Nya (dan bahwasanya karunia itu berada di tangan kekuasaan Allah. Dia berikan karunia itu) yakni Dia memberikannya (kepada siapa yang dikehendaki-Nya) maka Dia memberikan karunia-Nya kepada orang-orang yang beriman di antara mereka, berupa pahala yang mereka terima sebanyak dua kali lipat, sebagaimana keterangan yang telah lalu. Yaitu karena beriman kepada dua nabi. (Dan Allah mempunyai karunia yang besar).",[["لِّئَلَّا","Jadi itu"],["يَعْلَمَ","mungkin tahu"],["أَهْلُ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["أَلَّا","itu tidak"],["يَقْدِرُونَ","mereka mempunyai kuasa"],["عَلَىٰ","atas"],["شَىْءٍۢ","sesuatu"],["مِّن","daripada"],["فَضْلِ","(the) Bounty"],["ٱللَّهِ ۙ","(milik) Allah"],["وَأَنَّ","dan bahawa"],["ٱلْفَضْلَ","Bounty"],["بِيَدِ","(ada) di Tangan Allah"],["ٱللَّهِ","(ada) di Tangan Allah"],["يُؤْتِيهِ","Dia memberikannya"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["ذُو","(ialah) Pemilik Karunia"],["ٱلْفَضْلِ","(ialah) Pemilik Karunia"],["ٱلْعَظِيمِ","yang Agung"]]]});